'use client';

import { useRouter, useParams } from 'next/navigation';
import { useAuth } from '@/context/AuthContext';
import { useWishlist } from '@/context/WishlistContext';
import { useCart } from '@/context/CartContext';
import ProductCard from '@/components/ProductCard';
import {
    getMyOrders, getAddresses, addAddress as apiAddAddress,
    updateAddress as apiUpdateAddress, deleteAddress as apiDeleteAddress,
    getCustomerProfile, updateCustomerProfile, deactivateAccount,
    uploadProfileImage, getProfileImage, removeProfileImage, getOrderById,
    cancelOrder as apiCancelOrder, formatVND, downloadInvoice
} from '@/lib/api';
import { Order, Address } from '@/types';
import {
    Package, MapPin, Heart, LogOut, User, Plus, Pencil, Trash2,
    Loader2, ShieldOff, Camera, X, Check, Star, Phone, Calendar, Mail,
    CheckCircle2, Smartphone, AlertCircle, Eye, ChevronRight, Shield, FileText
} from 'lucide-react';
import { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import toast from 'react-hot-toast';
import PrivacyDashboard from '@/components/account/PrivacyDashboard';
import ReviewForm from '@/components/reviews/ReviewForm';
import { BadgeCheck, MessageSquarePlus } from 'lucide-react';

type Tab = 'orders' | 'wishlist' | 'addresses' | 'profile' | 'privacy';

const VALID_TABS: Tab[] = ['orders', 'wishlist', 'addresses', 'profile', 'privacy'];

export default function AccountPage() {
    const router = useRouter();
    const params = useParams<{ tab?: string[] }>();
    const { user, isAuthenticated, isLoading, logout } = useAuth();
    const { items: wishlistItems, removeItem: removeWishlistItem } = useWishlist();
    const { addItem: addCartItem } = useCart();

    // Derive active tab from URL path segment, default to 'orders'
    const activeTab: Tab = useMemo(() => {
        const slug = params?.tab?.[0] as Tab | undefined;
        return slug && VALID_TABS.includes(slug) ? slug : 'orders';
    }, [params?.tab]);

    // Orders state
    const [orders, setOrders] = useState<Order[]>([]);
    const [ordersLoading, setOrdersLoading] = useState(false);
    const [selectedOrderDetails, setSelectedOrderDetails] = useState<any | null>(null);
    const [isOrderLoading, setIsOrderLoading] = useState(false);
    const [isTrackOrderModalOpen, setIsTrackOrderModalOpen] = useState(false);
    const [trackOrderId, setTrackOrderId] = useState<string | null>(null);

    // Profile Edit State
    const [isEditingProfile, setIsEditingProfile] = useState(false);
    const [editForm, setEditForm] = useState({ full_name: '', phone: '', date_of_birth: '' });

    // Addresses state
    const [addresses, setAddresses] = useState<Address[]>([]);
    const [addressesLoading, setAddressesLoading] = useState(false);
    const [showAddressForm, setShowAddressForm] = useState(false);
    const [editingAddress, setEditingAddress] = useState<Address | null>(null);
    const [addressForm, setAddressForm] = useState({
        address_line1: '', address_line2: '', city: '', state: '', pincode: '',
        country: 'India', phone: '', label: '', is_default: false,
    });

    // Profile state
    const [orderCount, setOrderCount] = useState(0);
    const [profileEditing, setProfileEditing] = useState(false);
    const [profileSaving, setProfileSaving] = useState(false);
    const [profileData, setProfileData] = useState({
        full_name: '', email: '', phone: '', date_of_birth: '',
        is_email_verified: false, is_mobile_verified: false,
    });

    // Profile image state
    const [profileImageUrl, setProfileImageUrl] = useState<string | null>(null);
    const [imageUploading, setImageUploading] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    // Deactivation state
    const [showDeactivateModal, setShowDeactivateModal] = useState(false);
    const [deactivatePassword, setDeactivatePassword] = useState('');
    const [deactivating, setDeactivating] = useState(false);

    // Delete address confirmation
    const [deletingAddressId, setDeletingAddressId] = useState<string | null>(null);

    // Cancel order state
    const [cancellingOrderId, setCancellingOrderId] = useState<string | null>(null);
    const [cancelReason, setCancelReason] = useState('');
    const [cancelSubmitting, setCancelSubmitting] = useState(false);

    // Review modal state
    const [reviewModal, setReviewModal] = useState<{ orderId: string; productId: string; productName: string } | null>(null);

    // Body scroll lock for modals
    useEffect(() => {
        if (selectedOrderDetails || isTrackOrderModalOpen || showDeactivateModal || deletingAddressId || cancellingOrderId || reviewModal) {
            document.body.style.overflow = 'hidden';
        } else {
            document.body.style.overflow = 'unset';
        }
        return () => {
            document.body.style.overflow = 'unset';
        };
    }, [selectedOrderDetails, isTrackOrderModalOpen, showDeactivateModal, deletingAddressId, cancellingOrderId, reviewModal]);

    useEffect(() => {
        if (!isLoading && !isAuthenticated) {
            router.push('/login');
        }
    }, [isLoading, isAuthenticated, router]);

    // ── Fetch orders ─────────────────────────────────────────────────
    const fetchOrders = useCallback(async () => {
        if (!user?.id) return;
        setOrdersLoading(true);
        try {
            const res = await getMyOrders(user.id);
            if (res.success) {
                const ordersArray = Array.isArray(res.data) ? res.data : Array.isArray(res.data?.orders) ? res.data.orders : [];
                setOrders(ordersArray);
                setOrderCount(ordersArray.length);
            }
        } catch (err) {
            console.error('Failed to fetch orders:', err);
        } finally {
            setOrdersLoading(false);
        }
    }, [user?.id]);

    // ── Fetch addresses ──────────────────────────────────────────────
    const fetchAddresses = useCallback(async () => {
        if (!user?.id) return;
        setAddressesLoading(true);
        try {
            const res = await getAddresses(user.id);
            if (res.success && Array.isArray(res.data)) {
                setAddresses(res.data);
            }
        } catch (err) {
            console.error('Failed to fetch addresses:', err);
        } finally {
            setAddressesLoading(false);
        }
    }, [user?.id]);

    // ── Fetch profile ────────────────────────────────────────────────
    const fetchProfile = useCallback(async () => {
        if (!user?.id) return;
        try {
            const res = await getCustomerProfile(user.id);
            if (res.success && res.data) {
                setProfileData({
                    full_name: res.data.full_name || '',
                    email: res.data.email || '',
                    phone: res.data.phone || '',
                    date_of_birth: res.data.date_of_birth ? res.data.date_of_birth.split('T')[0] : '',
                    is_email_verified: !!res.data.is_email_verified,
                    is_mobile_verified: !!res.data.is_mobile_verified,
                });
            }
        } catch (err) {
            console.error('Failed to fetch profile:', err);
        }
    }, [user?.id]);

    // ── Fetch profile image ──────────────────────────────────────────
    const fetchProfileImage = useCallback(async () => {
        if (!user?.id) return;
        try {
            const res = await getProfileImage(user.id);
            if (res.success && res.data?.profile_image) {
                const mime = res.data.mime_type || 'image/jpeg';
                setProfileImageUrl(`data:${mime};base64,${res.data.profile_image}`);
            }
        } catch {
            // No image or error, stay with fallback
        }
    }, [user?.id]);

    useEffect(() => {
        if (!user?.id) return;
        if (activeTab === 'orders') fetchOrders();
        if (activeTab === 'addresses') fetchAddresses();
        if (activeTab === 'profile') {
            fetchOrders(); // for order count
            fetchProfile();
            fetchProfileImage();
        }
    }, [activeTab, user?.id, fetchOrders, fetchAddresses, fetchProfile, fetchProfileImage]);

    // ── Profile save handler ─────────────────────────────────────────
    const handleProfileSave = async () => {
        if (!user?.id) return;
        setProfileSaving(true);
        try {
            const res = await updateCustomerProfile(user.id, profileData);
            if (res.success) {
                toast.success('Profile updated successfully');
                setProfileEditing(false);
            } else {
                toast.error(res.message || 'Failed to update profile');
            }
        } catch {
            toast.error('Server error. Please try again.');
        } finally {
            setProfileSaving(false);
        }
    };

    // ── Image upload handler ─────────────────────────────────────────
    const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file || !user?.id) return;

        if (file.size > 5 * 1024 * 1024) {
            toast.error('Image must be under 5MB');
            return;
        }

        setImageUploading(true);
        try {
            const reader = new FileReader();
            reader.onload = async () => {
                const base64 = reader.result as string;
                setProfileImageUrl(base64); // immediate preview
                try {
                    const res = await uploadProfileImage(user.id, base64);
                    if (res.success) {
                        toast.success('Profile photo updated!');
                    } else {
                        toast.error(res.message || 'Failed to upload image');
                        setProfileImageUrl(null);
                    }
                } catch {
                    toast.error('Upload failed. Please try again.');
                    setProfileImageUrl(null);
                } finally {
                    setImageUploading(false);
                }
            };
            reader.readAsDataURL(file);
        } catch {
            setImageUploading(false);
            toast.error('Could not read file');
        }
        // Reset input so same file can be re-selected
        if (fileInputRef.current) fileInputRef.current.value = '';
    };

    // ── Remove image ─────────────────────────────────────────────────
    const handleRemoveImage = async () => {
        if (!user?.id) return;
        try {
            const res = await removeProfileImage(user.id);
            if (res.success) {
                setProfileImageUrl(null);
                toast.success('Profile photo removed');
            } else {
                toast.error(res.message || 'Failed to remove image');
            }
        } catch {
            toast.error('Server error');
        }
    };

    // ── Address handlers ─────────────────────────────────────────────
    const handleAddressSubmit = async () => {
        if (!user?.id) return;
        if (!addressForm.address_line1 || !addressForm.city || !addressForm.state || !addressForm.pincode) {
            toast.error('Please fill in all required fields');
            return;
        }

        try {
            if (editingAddress) {
                const res = await apiUpdateAddress(user.id, editingAddress.address_id, addressForm as unknown as Record<string, string>);
                if (res.success) {
                    toast.success('Address updated');
                } else {
                    toast.error(res.message || 'Failed to update address');
                }
            } else {
                const res = await apiAddAddress(user.id, addressForm as unknown as Record<string, string>);
                if (res.success) {
                    toast.success('Address added');
                } else {
                    toast.error(res.message || 'Failed to add address');
                }
            }
            resetAddressForm();
            fetchAddresses();
        } catch {
            toast.error('Something went wrong');
        }
    };

    const handleDeleteAddress = async (addressId: string) => {
        if (!user?.id) return;
        try {
            const res = await apiDeleteAddress(user.id, addressId);
            if (res.success) {
                toast.success('Address deleted');
                setDeletingAddressId(null);
                fetchAddresses();
            } else {
                toast.error(res.message || 'Failed to delete address');
            }
        } catch {
            toast.error('Something went wrong');
        }
    };

    const handleSetDefault = async (addr: Address) => {
        if (!user?.id) return;
        try {
            const res = await apiUpdateAddress(user.id, addr.address_id, { is_default: 'true' } as Record<string, string>);
            if (res.success) {
                toast.success('Default address updated');
                fetchAddresses();
            } else {
                toast.error(res.message || 'Failed to set default');
            }
        } catch {
            toast.error('Something went wrong');
        }
    };

    const startEditAddress = (addr: Address) => {
        setEditingAddress(addr);
        setAddressForm({
            address_line1: addr.address_line1 || '',
            address_line2: addr.address_line2 || '',
            city: addr.city || '',
            state: addr.state || '',
            pincode: addr.pincode || '',
            country: addr.country || 'India',
            phone: addr.phone || '',
            label: addr.label || '',
            is_default: addr.is_default || false,
        });
        setShowAddressForm(true);
    };

    const resetAddressForm = () => {
        setShowAddressForm(false);
        setEditingAddress(null);
        setAddressForm({
            address_line1: '', address_line2: '', city: '', state: '', pincode: '',
            country: 'India', phone: '', label: '', is_default: false,
        });
    };

    const handleViewOrderDetails = async (orderId: string) => {
        setIsOrderLoading(true);
        try {
            const res = await getOrderById(orderId);
            if (res.success && res.data) {
                setSelectedOrderDetails(res.data);
            } else {
                toast.error('Failed to load order details');
            }
        } catch (error) {
            console.error('Error fetching order details:', error);
            toast.error('Failed to load order details due to a server error.');
        } finally {
            setIsOrderLoading(false);
        }
    };

    const handleTrackOrder = (orderId: string) => {
        setTrackOrderId(orderId);
        setIsTrackOrderModalOpen(true);
    };

    if (isLoading) {
        return (
            <div className="min-h-screen bg-cream flex items-center justify-center">
                <Loader2 className="h-8 w-8 animate-spin text-burgundy" />
            </div>
        );
    }

    if (!isAuthenticated) {
        return null;
    }

    const getStatusColor = (status: string) => {
        const s = status?.toLowerCase();
        if (s === 'confirmed' || s === 'completed') return 'bg-green-100 text-green-700';
        if (s === 'shipped' || s === 'processing') return 'bg-blue-100 text-blue-700';
        if (s === 'delivered') return 'bg-purple-100 text-purple-700';
        if (s === 'cancelled') return 'bg-red-100 text-red-700';
        return 'bg-yellow-100 text-yellow-700';
    };

    const tabs: { id: Tab; label: string; icon: React.ElementType; count?: number }[] = [
        { id: 'orders', label: 'Orders', icon: Package, count: orderCount },
        { id: 'wishlist', label: 'Wishlist', icon: Heart, count: wishlistItems.length },
        { id: 'addresses', label: 'Addresses', icon: MapPin, count: addresses.length },
        { id: 'profile', label: 'Profile', icon: User },
        { id: 'privacy', label: 'Privacy', icon: Shield },
    ];

    return (
        <div className="min-h-screen bg-cream">
            {/* Header */}
            <div className="border-b border-light-border bg-white">
                <div className="mx-auto max-w-7xl px-4 py-8">
                    <div className="flex items-center justify-between">
                        <div>
                            <h1 className="font-serif text-3xl font-bold text-charcoal">My Account</h1>
                            <p className="mt-1 text-sm text-warm-gray">Welcome back, {user?.name}!</p>
                        </div>
                        <button
                            onClick={() => { logout(); toast.success('Logged out'); router.push('/'); }}
                            className="flex items-center gap-2 rounded-lg border border-light-border px-4 py-2 text-sm font-medium text-warm-gray hover:text-red-500 hover:border-red-200 transition-colors"
                        >
                            <LogOut className="h-4 w-4" /> Sign Out
                        </button>
                    </div>
                </div>
            </div>

            <div className="mx-auto max-w-7xl px-4 py-8">
                {/* Tabs */}
                <div className="flex gap-1 border-b border-light-border mb-8 overflow-x-auto">
                    {tabs.map(tab => (
                        <button
                            key={tab.id}
                            onClick={() => router.push(`/account/${tab.id}`)}
                            className={`flex items-center gap-2 whitespace-nowrap border-b-2 px-5 py-3 text-sm font-medium transition-colors ${activeTab === tab.id
                                ? 'border-burgundy text-burgundy'
                                : 'border-transparent text-warm-gray hover:text-charcoal'
                                }`}
                        >
                            <tab.icon className="h-4 w-4" />
                            {tab.label}
                            {tab.count !== undefined && tab.count > 0 && (
                                <span className="rounded-full bg-burgundy/10 px-2 py-0.5 text-[10px] font-bold text-burgundy">
                                    {tab.count}
                                </span>
                            )}
                        </button>
                    ))}
                </div>

                {/* ═══════════════════ ORDERS TAB ═══════════════════ */}
                {activeTab === 'orders' && (
                    <div>
                        {ordersLoading ? (
                            <div className="flex justify-center py-16">
                                <Loader2 className="h-8 w-8 animate-spin text-burgundy" />
                            </div>
                        ) : orders.length === 0 ? (
                            <div className="rounded-2xl border border-light-border bg-white py-16 text-center">
                                <Package className="mx-auto h-12 w-12 text-warm-gray/40 mb-3" />
                                <p className="font-serif text-lg text-charcoal">No orders yet</p>
                                <p className="mt-1 text-sm text-warm-gray">Your orders will appear here</p>
                            </div>
                        ) : (
                            <div className="space-y-4">
                                {orders.map(order => (
                                    <div key={order.order_id} className="rounded-xl border border-light-border bg-white p-6 shadow-sm hover:shadow-md transition-shadow">
                                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">

                                            {/* Left Section: Order Info & Status */}
                                            <div className="space-y-3">
                                                <div className="flex items-center gap-2">
                                                    <Package className="h-5 w-5 text-warm-gray" />
                                                    <span className="font-serif text-lg font-bold text-charcoal">
                                                        Order #{order.order_id.split('-')[0].toUpperCase()}
                                                    </span>
                                                </div>
                                                <div className="flex items-center gap-2 text-sm text-warm-gray">
                                                    <Calendar className="h-4 w-4" />
                                                    {new Date(order.created_at).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })}
                                                </div>
                                                <div className="flex items-center gap-2 text-sm font-medium">
                                                    <span className="flex items-center gap-1.5 text-charcoal">
                                                        <span className={`h-2.5 w-2.5 rounded-full ${order.order_status === 'DELIVERED' ? 'bg-purple-500' : order.order_status === 'SHIPPED' ? 'bg-blue-500' : order.order_status === 'CONFIRMED' ? 'bg-green-500' : 'bg-yellow-500'}`}></span>
                                                        {order.order_status}
                                                    </span>
                                                    <span className="text-warm-gray/40">|</span>
                                                    <span className="flex items-center gap-1.5 text-charcoal">
                                                        <span className={`h-2.5 w-2.5 rounded-full ${order.payment_status?.toLowerCase() === 'paid' ? 'bg-green-500' : 'bg-red-500'}`}></span>
                                                        {order.payment_status || 'UNPAID'}
                                                    </span>
                                                </div>
                                            </div>

                                            {/* Middle Section: Product Preview */}
                                            <div className="flex-1 md:border-l md:border-r border-light-border md:px-6 py-2">
                                                <div className="flex items-center gap-4">
                                                    <div className="h-16 w-16 rounded-lg border border-light-border overflow-hidden bg-cream flex-shrink-0">
                                                        {order.first_item?.thumbnail_url ? (
                                                            // eslint-disable-next-line @next/next/no-img-element
                                                            <img src={order.first_item.thumbnail_url} alt="Product" className="h-full w-full object-cover" />
                                                        ) : (
                                                            <div className="h-full w-full flex items-center justify-center text-warm-gray">
                                                                <Package className="h-6 w-6" />
                                                            </div>
                                                        )}
                                                    </div>
                                                    <div>
                                                        <p className="font-medium text-charcoal line-clamp-2 text-sm">
                                                            {order.first_item?.product_name || 'Product'}
                                                        </p>
                                                        {Number(order.item_count) > 1 && (
                                                            <p className="text-sm text-burgundy font-medium mt-1">
                                                                +{Number(order.item_count) - 1} more order items
                                                            </p>
                                                        )}
                                                    </div>
                                                </div>
                                            </div>

                                            {/* Right Section: Total & Actions */}
                                            <div className="flex flex-col items-start md:items-end justify-between space-y-4">
                                                <div className="flex flex-col items-start md:items-end gap-1">
                                                    <span className="text-charcoal flex items-center gap-1.5 font-bold font-serif text-lg">
                                                        <span className="text-xl">💰</span>{formatVND(order.final_total || order.total_amount)}
                                                    </span>
                                                    {order.vat_amount ? (
                                                        <span className="text-xs text-warm-gray">incl. VAT {formatVND(order.vat_amount)}</span>
                                                    ) : null}
                                                    {order.order_status === 'CANCELLED' && order.cancellation_reason && (
                                                        <span className="text-xs text-red-500 max-w-[180px] md:text-right">
                                                            Reason: {order.cancellation_reason}
                                                        </span>
                                                    )}
                                                </div>

                                                <div className="flex flex-wrap gap-2">
                                                    <button onClick={() => handleTrackOrder(order.order_id)} className="rounded-lg border border-light-border px-4 py-2 text-sm font-semibold text-charcoal hover:bg-cream transition-colors">
                                                        Track Order
                                                    </button>
                                                    <button onClick={() => handleViewOrderDetails(order.order_id)} className="rounded-lg border border-light-border px-4 py-2 text-sm font-semibold text-charcoal hover:bg-cream transition-colors">
                                                        {isOrderLoading && selectedOrderDetails?.order_id === order.order_id ? <Loader2 className="h-4 w-4 animate-spin inline-block" /> : 'View Details'}
                                                    </button>
                                                    {(order.order_status === 'PENDING' || order.order_status === 'CONFIRMED') && (
                                                        <button
                                                            onClick={() => { setCancellingOrderId(order.order_id); setCancelReason(''); }}
                                                            className="rounded-lg border border-red-200 px-4 py-2 text-sm font-semibold text-red-600 hover:bg-red-50 transition-colors"
                                                        >
                                                            Cancel Order
                                                        </button>
                                                    )}
                                                    {order.order_status === 'DELIVERED' && (
                                                        <button
                                                            onClick={async () => {
                                                                // Fetch order details to get product info for the review
                                                                const res = await getOrderById(order.order_id);
                                                                if (res.success && res.data?.items?.length > 0) {
                                                                    const firstItem = res.data.items[0];
                                                                    const productId = firstItem.product?.product_id || firstItem.product_id;
                                                                    const productName = firstItem.product?.product_name || firstItem.product_name || 'Product';
                                                                    if (productId) {
                                                                        setReviewModal({ orderId: order.order_id, productId, productName });
                                                                    } else {
                                                                        toast.error('Could not load product info');
                                                                    }
                                                                } else {
                                                                    toast.error('Could not load order details');
                                                                }
                                                            }}
                                                            className="rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-2 text-sm font-semibold text-emerald-700 hover:bg-emerald-100 transition-colors flex items-center gap-1.5"
                                                        >
                                                            <BadgeCheck className="h-4 w-4" />
                                                            Write Review
                                                        </button>
                                                    )}
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                )}

                {/* ─── Cancel Order Confirmation Modal ─── */}
                {cancellingOrderId && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
                        <div className="bg-white rounded-2xl shadow-xl w-full max-w-md p-6 space-y-4">
                            <div className="flex items-center gap-3">
                                <div className="p-2 rounded-full bg-red-100">
                                    <X className="h-5 w-5 text-red-600" />
                                </div>
                                <div>
                                    <h3 className="font-serif font-bold text-charcoal text-lg">Cancel Order?</h3>
                                    <p className="text-sm text-warm-gray">This action cannot be undone. Stock will be restored.</p>
                                </div>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-charcoal mb-1">Reason (optional)</label>
                                <textarea
                                    rows={3}
                                    value={cancelReason}
                                    onChange={e => setCancelReason(e.target.value)}
                                    placeholder="e.g. Changed my mind, ordered by mistake..."
                                    className="w-full rounded-lg border border-light-border px-3 py-2 text-sm text-charcoal placeholder:text-warm-gray/60 focus:border-burgundy/40 focus:outline-none focus:ring-1 focus:ring-burgundy/30 resize-none"
                                />
                            </div>
                            <div className="flex gap-3">
                                <button
                                    disabled={cancelSubmitting}
                                    onClick={() => { setCancellingOrderId(null); setCancelReason(''); }}
                                    className="flex-1 rounded-lg border border-light-border py-2.5 text-sm font-semibold text-charcoal hover:bg-cream transition-colors"
                                >
                                    Keep Order
                                </button>
                                <button
                                    disabled={cancelSubmitting}
                                    onClick={async () => {
                                        if (!cancellingOrderId) return;
                                        setCancelSubmitting(true);
                                        try {
                                            const res = await apiCancelOrder(cancellingOrderId, cancelReason);
                                            if (res.success) {
                                                toast.success('Order cancelled successfully');
                                                setCancellingOrderId(null);
                                                setCancelReason('');
                                                fetchOrders();
                                            } else {
                                                toast.error(res.message || 'Failed to cancel order');
                                            }
                                        } catch {
                                            toast.error('Something went wrong. Please try again.');
                                        } finally {
                                            setCancelSubmitting(false);
                                        }
                                    }}
                                    className="flex-1 flex items-center justify-center gap-2 rounded-lg bg-red-500 hover:bg-red-600 py-2.5 text-sm font-semibold text-white transition-colors disabled:opacity-60"
                                >
                                    {cancelSubmitting ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
                                    Yes, Cancel Order
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                {/* ─── Verified Purchase Review Modal ─── */}
                {reviewModal && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
                        <div className="bg-white rounded-2xl shadow-xl w-full max-w-lg overflow-hidden">
                            <div className="h-1" style={{ background: 'linear-gradient(90deg, #10b981, #D4A847)' }} />
                            <div className="p-6">
                                <div className="flex items-center justify-between mb-4">
                                    <div className="flex items-center gap-2">
                                        <BadgeCheck className="h-5 w-5 text-emerald-600" />
                                        <h3 className="font-serif font-bold text-charcoal text-lg">Verified Purchase Review</h3>
                                    </div>
                                    <button
                                        onClick={() => setReviewModal(null)}
                                        className="p-1.5 rounded-lg hover:bg-cream transition-colors text-warm-gray hover:text-charcoal"
                                    >
                                        <X className="h-4 w-4" />
                                    </button>
                                </div>
                                <p className="text-sm text-warm-gray mb-4">
                                    Reviewing: <span className="font-medium text-charcoal">{reviewModal.productName}</span>
                                </p>
                                <div className="flex items-center gap-2 mb-5 px-3 py-2 rounded-lg bg-emerald-50 border border-emerald-100">
                                    <BadgeCheck className="h-4 w-4 text-emerald-600 flex-shrink-0" />
                                    <p className="text-xs text-emerald-700">This review will have a <strong>Verified Purchase</strong> badge because your order has been delivered.</p>
                                </div>
                                <ReviewForm
                                    productId={reviewModal.productId}
                                    orderId={reviewModal.orderId}
                                    onSubmitted={() => {
                                        setReviewModal(null);
                                        toast.success('Review submitted with Verified Purchase badge!');
                                    }}
                                />
                            </div>
                        </div>
                    </div>
                )}

                {/* ═══════════════════ WISHLIST TAB ═══════════════════ */}
                {activeTab === 'wishlist' && (
                    <div>
                        {wishlistItems.length === 0 ? (
                            <div className="rounded-2xl border border-light-border bg-white py-16 text-center">
                                <Heart className="mx-auto h-12 w-12 text-warm-gray/40 mb-3" />
                                <p className="font-serif text-lg text-charcoal">Wishlist is empty</p>
                                <p className="mt-1 text-sm text-warm-gray">Save your favorite wines here</p>
                            </div>
                        ) : (
                            <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
                                {wishlistItems.map(product => (
                                    <ProductCard
                                        key={product.product_id}
                                        product={product}
                                        onMoveToCart={(e) => {
                                            e.preventDefault();
                                            e.stopPropagation();
                                            addCartItem(product.product_id, null, 1);
                                            removeWishlistItem(product.product_id);
                                            toast.success(`${product.product_name} moved to cart`);
                                        }}
                                    />
                                ))}
                            </div>
                        )}
                    </div>
                )}

                {/* ═══════════════════ ADDRESSES TAB ═══════════════════ */}
                {activeTab === 'addresses' && (
                    <div>
                        <div className="flex justify-between items-center mb-6">
                            <div>
                                <h2 className="font-serif text-lg font-bold text-charcoal">Address Book</h2>
                                <p className="text-sm text-warm-gray mt-0.5">Manage your delivery addresses</p>
                            </div>
                            {!showAddressForm && (
                                <button
                                    onClick={() => {
                                        resetAddressForm();
                                        setShowAddressForm(true);
                                    }}
                                    className="flex items-center gap-2 rounded-lg bg-burgundy px-4 py-2.5 text-sm font-semibold text-white hover:bg-burgundy-dark transition-all hover:shadow-md"
                                >
                                    <Plus className="h-4 w-4" /> Add Address
                                </button>
                            )}
                        </div>

                        {/* Address Form (animated) */}
                        {showAddressForm && (
                            <div
                                className="mb-6 rounded-2xl border border-light-border bg-white overflow-hidden shadow-sm"
                                style={{ animation: 'slideDown 0.3s ease-out' }}
                            >
                                {/* Form header accent */}
                                <div className="h-1" style={{ background: 'linear-gradient(90deg, #6B2737, #D4A847)' }} />
                                <div className="p-6">
                                    <div className="flex items-center justify-between mb-5">
                                        <h3 className="font-serif text-base font-bold text-charcoal">
                                            {editingAddress ? 'Edit Address' : 'New Address'}
                                        </h3>
                                        <button onClick={resetAddressForm} className="p-1.5 rounded-lg hover:bg-cream transition-colors text-warm-gray hover:text-charcoal">
                                            <X className="h-4 w-4" />
                                        </button>
                                    </div>
                                    <div className="grid gap-4 sm:grid-cols-2">
                                        <div className="sm:col-span-2">
                                            <label className="block text-sm font-medium text-charcoal mb-1">Address Line 1 *</label>
                                            <input type="text" value={addressForm.address_line1}
                                                onChange={e => setAddressForm({ ...addressForm, address_line1: e.target.value })}
                                                className="w-full rounded-lg border border-light-border px-4 py-2.5 text-sm focus:border-burgundy focus:outline-none transition-colors"
                                                placeholder="Street address" />
                                        </div>
                                        <div className="sm:col-span-2">
                                            <label className="block text-sm font-medium text-charcoal mb-1">Address Line 2</label>
                                            <input type="text" value={addressForm.address_line2}
                                                onChange={e => setAddressForm({ ...addressForm, address_line2: e.target.value })}
                                                className="w-full rounded-lg border border-light-border px-4 py-2.5 text-sm focus:border-burgundy focus:outline-none transition-colors"
                                                placeholder="Apartment, suite, etc." />
                                        </div>
                                        <div>
                                            <label className="block text-sm font-medium text-charcoal mb-1">City *</label>
                                            <input type="text" value={addressForm.city}
                                                onChange={e => setAddressForm({ ...addressForm, city: e.target.value })}
                                                className="w-full rounded-lg border border-light-border px-4 py-2.5 text-sm focus:border-burgundy focus:outline-none transition-colors"
                                                placeholder="City" />
                                        </div>
                                        <div>
                                            <label className="block text-sm font-medium text-charcoal mb-1">State *</label>
                                            <input type="text" value={addressForm.state}
                                                onChange={e => setAddressForm({ ...addressForm, state: e.target.value })}
                                                className="w-full rounded-lg border border-light-border px-4 py-2.5 text-sm focus:border-burgundy focus:outline-none transition-colors"
                                                placeholder="State" />
                                        </div>
                                        <div>
                                            <label className="block text-sm font-medium text-charcoal mb-1">Pincode *</label>
                                            <input type="text" value={addressForm.pincode}
                                                onChange={e => setAddressForm({ ...addressForm, pincode: e.target.value })}
                                                className="w-full rounded-lg border border-light-border px-4 py-2.5 text-sm focus:border-burgundy focus:outline-none transition-colors"
                                                placeholder="Pincode" />
                                        </div>
                                        <div>
                                            <label className="block text-sm font-medium text-charcoal mb-1">Country</label>
                                            <input type="text" value={addressForm.country}
                                                onChange={e => setAddressForm({ ...addressForm, country: e.target.value })}
                                                className="w-full rounded-lg border border-light-border px-4 py-2.5 text-sm focus:border-burgundy focus:outline-none transition-colors"
                                                placeholder="Country" />
                                        </div>
                                        <div>
                                            <label className="block text-sm font-medium text-charcoal mb-1">Phone</label>
                                            <input type="tel" value={addressForm.phone}
                                                onChange={e => setAddressForm({ ...addressForm, phone: e.target.value })}
                                                className="w-full rounded-lg border border-light-border px-4 py-2.5 text-sm focus:border-burgundy focus:outline-none transition-colors"
                                                placeholder="Phone number" />
                                        </div>
                                        <div>
                                            <label className="block text-sm font-medium text-charcoal mb-1">Label</label>
                                            <div className="flex gap-2">
                                                {['Home', 'Office', 'Other'].map(l => (
                                                    <button key={l} type="button"
                                                        onClick={() => setAddressForm({ ...addressForm, label: l })}
                                                        className={`rounded-lg px-4 py-2.5 text-sm font-medium border transition-all ${addressForm.label === l
                                                            ? 'border-burgundy bg-burgundy/5 text-burgundy'
                                                            : 'border-light-border text-warm-gray hover:border-burgundy/30'}`
                                                        }>
                                                        {l}
                                                    </button>
                                                ))}
                                            </div>
                                        </div>
                                        <div className="sm:col-span-2">
                                            <label className="flex items-center gap-2 cursor-pointer">
                                                <input type="checkbox" checked={addressForm.is_default}
                                                    onChange={e => setAddressForm({ ...addressForm, is_default: e.target.checked })}
                                                    className="rounded border-light-border text-burgundy focus:ring-burgundy w-4 h-4" />
                                                <span className="text-sm text-charcoal">Set as default address</span>
                                            </label>
                                        </div>
                                    </div>
                                    <div className="mt-5 flex gap-3">
                                        <button onClick={handleAddressSubmit}
                                            className="rounded-lg bg-burgundy px-6 py-2.5 text-sm font-semibold text-white hover:bg-burgundy-dark transition-all hover:shadow-md">
                                            {editingAddress ? 'Update Address' : 'Save Address'}
                                        </button>
                                        <button onClick={resetAddressForm}
                                            className="rounded-lg border border-light-border px-6 py-2.5 text-sm font-medium text-charcoal hover:bg-cream transition-colors">
                                            Cancel
                                        </button>
                                    </div>
                                </div>
                            </div>
                        )}

                        {addressesLoading ? (
                            <div className="flex justify-center py-16">
                                <Loader2 className="h-8 w-8 animate-spin text-burgundy" />
                            </div>
                        ) : addresses.length === 0 && !showAddressForm ? (
                            <div className="rounded-2xl border border-light-border bg-white py-16 text-center">
                                <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-cream">
                                    <MapPin className="h-8 w-8 text-warm-gray/50" />
                                </div>
                                <p className="font-serif text-lg text-charcoal">No saved addresses</p>
                                <p className="mt-1 text-sm text-warm-gray mb-5">Add your first delivery address</p>
                                <button
                                    onClick={() => { resetAddressForm(); setShowAddressForm(true); }}
                                    className="rounded-lg bg-burgundy px-5 py-2.5 text-sm font-semibold text-white hover:bg-burgundy-dark transition-colors"
                                >
                                    <Plus className="inline h-4 w-4 mr-1 -mt-0.5" /> Add Address
                                </button>
                            </div>
                        ) : (
                            <div className="grid gap-4 sm:grid-cols-2">
                                {addresses.map(addr => (
                                    <div key={addr.address_id}
                                        className={`group relative rounded-xl border bg-white p-5 transition-all hover:shadow-md ${addr.is_default ? 'border-burgundy/30 ring-1 ring-burgundy/10' : 'border-light-border'}`}
                                    >
                                        {/* Default badge */}
                                        {addr.is_default && (
                                            <div className="absolute -top-2.5 left-4 flex items-center gap-1 rounded-full px-2.5 py-0.5 text-[10px] font-bold text-white"
                                                style={{ background: 'linear-gradient(135deg, #D4A847, #B8902D)' }}>
                                                <Star className="h-2.5 w-2.5" fill="white" /> DEFAULT
                                            </div>
                                        )}

                                        <div className="flex justify-between items-start">
                                            <div className="pt-1">
                                                {addr.label && (
                                                    <span className="inline-block rounded-full bg-burgundy/10 px-2.5 py-0.5 text-[10px] font-bold text-burgundy uppercase mb-2">
                                                        {addr.label}
                                                    </span>
                                                )}
                                                <p className="text-sm font-medium text-charcoal">{addr.address_line1}</p>
                                                {addr.address_line2 && <p className="text-sm text-warm-gray">{addr.address_line2}</p>}
                                                <p className="text-sm text-warm-gray">{addr.city}, {addr.state} {addr.pincode}</p>
                                                {addr.country && addr.country !== 'India' && (
                                                    <p className="text-sm text-warm-gray">{addr.country}</p>
                                                )}
                                                {addr.phone && (
                                                    <p className="mt-2 text-sm text-charcoal flex items-center gap-1.5">
                                                        <Phone className="h-3 w-3 text-warm-gray" /> {addr.phone}
                                                    </p>
                                                )}
                                            </div>
                                            <div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
                                                {!addr.is_default && (
                                                    <button onClick={() => handleSetDefault(addr)}
                                                        title="Set as default"
                                                        className="p-2 text-warm-gray hover:text-amber-600 transition-colors rounded-lg hover:bg-amber-50">
                                                        <Star className="h-4 w-4" />
                                                    </button>
                                                )}
                                                <button onClick={() => startEditAddress(addr)}
                                                    className="p-2 text-warm-gray hover:text-burgundy transition-colors rounded-lg hover:bg-burgundy/5">
                                                    <Pencil className="h-4 w-4" />
                                                </button>
                                                <button onClick={() => setDeletingAddressId(addr.address_id)}
                                                    className="p-2 text-warm-gray hover:text-red-500 transition-colors rounded-lg hover:bg-red-50">
                                                    <Trash2 className="h-4 w-4" />
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                )}

                {/* ═══════════════════ PROFILE TAB ═══════════════════ */}
                {activeTab === 'profile' && (
                    <div className="max-w-2xl space-y-6">

                        {/* ── Profile Card with Avatar ── */}
                        <div className="rounded-2xl border border-light-border bg-white overflow-hidden shadow-sm">
                            {/* Header gradient */}
                            <div className="h-24 relative" style={{ background: 'linear-gradient(135deg, #6B2737 0%, #8B3A4A 40%, #D4A847 100%)' }}>
                                <div className="absolute -bottom-12 left-6">
                                    <div className="relative group">
                                        {/* Avatar */}
                                        <div className="h-24 w-24 rounded-full border-4 border-white shadow-lg overflow-hidden bg-cream-dark flex items-center justify-center">
                                            {profileImageUrl ? (
                                                // eslint-disable-next-line @next/next/no-img-element
                                                <img src={profileImageUrl} alt="Profile" className="h-full w-full object-cover" />
                                            ) : (
                                                <span className="font-serif text-3xl font-bold text-burgundy">
                                                    {user?.name?.charAt(0).toUpperCase()}
                                                </span>
                                            )}

                                            {/* Upload overlay */}
                                            {imageUploading && (
                                                <div className="absolute inset-0 bg-black/50 flex items-center justify-center rounded-full">
                                                    <Loader2 className="h-6 w-6 animate-spin text-white" />
                                                </div>
                                            )}
                                        </div>

                                        {/* Camera button */}
                                        <button
                                            onClick={() => fileInputRef.current?.click()}
                                            disabled={imageUploading}
                                            className="absolute -bottom-1 -right-1 h-8 w-8 rounded-full bg-burgundy text-white flex items-center justify-center shadow-md hover:bg-burgundy-dark transition-all hover:scale-110 disabled:opacity-50"
                                        >
                                            <Camera className="h-3.5 w-3.5" />
                                        </button>
                                        <input
                                            ref={fileInputRef}
                                            type="file"
                                            accept="image/*"
                                            onChange={handleImageUpload}
                                            className="hidden"
                                        />
                                    </div>
                                </div>

                                {/* Edit / save button */}
                                <div className="absolute top-4 right-4">
                                    {profileEditing ? (
                                        <div className="flex gap-2">
                                            <button onClick={handleProfileSave} disabled={profileSaving}
                                                className="flex items-center gap-1.5 rounded-lg bg-white/20 backdrop-blur-sm px-3 py-1.5 text-xs font-semibold text-white hover:bg-white/30 transition-colors disabled:opacity-50">
                                                {profileSaving ? <Loader2 className="h-3 w-3 animate-spin" /> : <Check className="h-3 w-3" />}
                                                Save
                                            </button>
                                            <button onClick={() => { setProfileEditing(false); fetchProfile(); }}
                                                className="flex items-center gap-1.5 rounded-lg bg-white/20 backdrop-blur-sm px-3 py-1.5 text-xs font-semibold text-white hover:bg-white/30 transition-colors">
                                                <X className="h-3 w-3" /> Cancel
                                            </button>
                                        </div>
                                    ) : (
                                        <button onClick={() => setProfileEditing(true)}
                                            className="flex items-center gap-1.5 rounded-lg bg-white/20 backdrop-blur-sm px-3 py-1.5 text-xs font-semibold text-white hover:bg-white/30 transition-colors">
                                            <Pencil className="h-3 w-3" /> Edit Profile
                                        </button>
                                    )}
                                </div>
                            </div>

                            <div className="pt-16 px-6 pb-6">
                                {/* Photo actions */}
                                <div className="flex items-center gap-3 mb-6">
                                    <button onClick={() => fileInputRef.current?.click()}
                                        className="text-xs font-medium text-burgundy hover:text-burgundy-dark transition-colors">
                                        Change Photo
                                    </button>
                                    {profileImageUrl && (
                                        <>
                                            <span className="text-warm-gray/30">|</span>
                                            <button onClick={handleRemoveImage}
                                                className="text-xs font-medium text-warm-gray hover:text-red-500 transition-colors">
                                                Remove Photo
                                            </button>
                                        </>
                                    )}
                                </div>

                                {/* Profile fields */}
                                <div className="space-y-4">
                                    {/* Full Name */}
                                    <div className="flex items-center gap-3 py-3 border-b border-light-border">
                                        <User className="h-4 w-4 text-warm-gray flex-shrink-0" />
                                        <div className="flex-1 min-w-0">
                                            <p className="text-[11px] font-medium text-warm-gray uppercase tracking-wider">Full Name</p>
                                            {profileEditing ? (
                                                <input type="text" value={profileData.full_name}
                                                    onChange={e => setProfileData({ ...profileData, full_name: e.target.value })}
                                                    className="w-full mt-0.5 text-sm text-charcoal font-medium bg-transparent border-b border-burgundy/30 focus:border-burgundy focus:outline-none py-0.5 transition-colors" />
                                            ) : (
                                                <p className="text-sm text-charcoal font-medium mt-0.5">{profileData.full_name || '—'}</p>
                                            )}
                                        </div>
                                    </div>

                                    {/* Email */}
                                    <div className="flex items-center gap-3 py-3 border-b border-light-border">
                                        <Mail className="h-4 w-4 text-warm-gray flex-shrink-0" />
                                        <div className="flex-1 min-w-0">
                                            <p className="text-[11px] font-medium text-warm-gray uppercase tracking-wider">Email Address</p>
                                            {profileEditing ? (
                                                <input type="email" value={profileData.email}
                                                    onChange={e => setProfileData({ ...profileData, email: e.target.value })}
                                                    className="w-full mt-0.5 text-sm text-charcoal font-medium bg-transparent border-b border-burgundy/30 focus:border-burgundy focus:outline-none py-0.5 transition-colors" />
                                            ) : (
                                                <p className="text-sm text-charcoal font-medium mt-0.5">{profileData.email || '—'}</p>
                                            )}
                                        </div>
                                    </div>

                                    {/* Phone */}
                                    <div className="flex items-center gap-3 py-3 border-b border-light-border">
                                        <Phone className="h-4 w-4 text-warm-gray flex-shrink-0" />
                                        <div className="flex-1 min-w-0">
                                            <p className="text-[11px] font-medium text-warm-gray uppercase tracking-wider">Phone Number</p>
                                            {profileEditing ? (
                                                <input type="tel" value={profileData.phone}
                                                    onChange={e => setProfileData({ ...profileData, phone: e.target.value })}
                                                    className="w-full mt-0.5 text-sm text-charcoal font-medium bg-transparent border-b border-burgundy/30 focus:border-burgundy focus:outline-none py-0.5 transition-colors"
                                                    placeholder="Add phone number" />
                                            ) : (
                                                <p className="text-sm text-charcoal font-medium mt-0.5">{profileData.phone || 'Not provided'}</p>
                                            )}
                                        </div>
                                    </div>

                                    {/* Date of Birth */}
                                    <div className="flex items-center gap-3 py-3">
                                        <Calendar className="h-4 w-4 text-warm-gray flex-shrink-0" />
                                        <div className="flex-1 min-w-0">
                                            <p className="text-[11px] font-medium text-warm-gray uppercase tracking-wider">Date of Birth</p>
                                            {profileEditing ? (
                                                <input type="date" value={profileData.date_of_birth}
                                                    onChange={e => setProfileData({ ...profileData, date_of_birth: e.target.value })}
                                                    className="w-full mt-0.5 text-sm text-charcoal font-medium bg-transparent border-b border-burgundy/30 focus:border-burgundy focus:outline-none py-0.5 transition-colors" />
                                            ) : (
                                                <p className="text-sm text-charcoal font-medium mt-0.5">
                                                    {profileData.date_of_birth
                                                        ? new Date(profileData.date_of_birth + 'T00:00:00').toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })
                                                        : 'Not provided'}
                                                </p>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* ── Verification Status ── */}
                        <div className="rounded-2xl border border-light-border bg-white overflow-hidden shadow-sm">
                            <div className="h-1" style={{ background: 'linear-gradient(90deg, #6B2737, #D4A847)' }} />
                            <div className="p-6">
                                <h3 className="font-serif text-base font-bold text-charcoal mb-4">Verification Status</h3>
                                <div className="space-y-3">
                                    {/* Email Verification */}
                                    <div className="flex items-center justify-between py-3 px-4 rounded-xl bg-cream/50 border border-light-border">
                                        <div className="flex items-center gap-3">
                                            <div className={`flex h-9 w-9 items-center justify-center rounded-full ${profileData.is_email_verified ? 'bg-green-100' : 'bg-amber-100'}`}>
                                                <Mail className={`h-4 w-4 ${profileData.is_email_verified ? 'text-green-600' : 'text-amber-600'}`} />
                                            </div>
                                            <div>
                                                <p className="text-sm font-medium text-charcoal">Email Address</p>
                                                <p className="text-xs text-warm-gray">{profileData.email}</p>
                                            </div>
                                        </div>
                                        {profileData.is_email_verified ? (
                                            <span className="flex items-center gap-1.5 rounded-full bg-green-100 px-3 py-1 text-xs font-semibold text-green-700">
                                                <CheckCircle2 className="h-3.5 w-3.5" /> Verified
                                            </span>
                                        ) : (
                                            <button
                                                onClick={() => router.push('/verify-email')}
                                                className="flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-xs font-semibold text-white transition-all hover:shadow-md"
                                                style={{ backgroundColor: '#D4A847' }}
                                            >
                                                <AlertCircle className="h-3.5 w-3.5" /> Verify Now
                                            </button>
                                        )}
                                    </div>

                                    {/* Mobile Verification */}
                                    <div className="flex items-center justify-between py-3 px-4 rounded-xl bg-cream/50 border border-light-border">
                                        <div className="flex items-center gap-3">
                                            <div className={`flex h-9 w-9 items-center justify-center rounded-full ${profileData.is_mobile_verified ? 'bg-green-100' : 'bg-amber-100'}`}>
                                                <Smartphone className={`h-4 w-4 ${profileData.is_mobile_verified ? 'text-green-600' : 'text-amber-600'}`} />
                                            </div>
                                            <div>
                                                <p className="text-sm font-medium text-charcoal">Mobile Number</p>
                                                <p className="text-xs text-warm-gray">{profileData.phone || 'Not provided'}</p>
                                            </div>
                                        </div>
                                        {profileData.is_mobile_verified ? (
                                            <span className="flex items-center gap-1.5 rounded-full bg-green-100 px-3 py-1 text-xs font-semibold text-green-700">
                                                <CheckCircle2 className="h-3.5 w-3.5" /> Verified
                                            </span>
                                        ) : (
                                            <button
                                                onClick={() => router.push('/verify-otp')}
                                                className="flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-xs font-semibold text-white transition-all hover:shadow-md"
                                                style={{ backgroundColor: '#D4A847' }}
                                            >
                                                <AlertCircle className="h-3.5 w-3.5" /> Verify Now
                                            </button>
                                        )}
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* ── Quick Stats ── */}
                        <div className="grid grid-cols-3 gap-4">
                            <div className="rounded-xl border border-light-border bg-white p-4 text-center">
                                <p className="font-serif text-2xl font-bold text-burgundy">{orderCount}</p>
                                <p className="text-xs text-warm-gray mt-1">Orders</p>
                            </div>
                            <div className="rounded-xl border border-light-border bg-white p-4 text-center">
                                <p className="font-serif text-2xl font-bold text-burgundy">{wishlistItems.length}</p>
                                <p className="text-xs text-warm-gray mt-1">Wishlist</p>
                            </div>
                            <div className="rounded-xl border border-light-border bg-white p-4 text-center">
                                <p className="font-serif text-2xl font-bold text-burgundy">{addresses.length}</p>
                                <p className="text-xs text-warm-gray mt-1">Addresses</p>
                            </div>
                        </div>

                        {/* ── Account Control ── */}
                        <div className="rounded-xl border p-6" style={{ borderColor: 'rgba(107, 39, 55, 0.2)', backgroundColor: 'rgba(107, 39, 55, 0.03)' }}>
                            <div className="flex items-start gap-3 mb-4">
                                <ShieldOff className="h-5 w-5 mt-0.5 flex-shrink-0" style={{ color: '#6B2737' }} />
                                <div>
                                    <h3 className="font-serif text-base font-bold" style={{ color: '#6B2737' }}>Account Control</h3>
                                    <p className="mt-1 text-sm text-warm-gray leading-relaxed">
                                        Deactivating your account will log you out and hide your profile.
                                        Your data — orders, wishlist, and addresses — will be safely preserved.
                                        You can reactivate anytime by signing in again.
                                    </p>
                                </div>
                            </div>
                            <button
                                onClick={() => { setDeactivatePassword(''); setShowDeactivateModal(true); }}
                                className="rounded-lg px-5 py-2.5 text-sm font-semibold text-white transition-all hover:shadow-md"
                                style={{ backgroundColor: '#6B2737' }}
                            >
                                Deactivate My Account
                            </button>
                        </div>
                    </div>
                )}

                {/* ═══════════════════ PRIVACY TAB ═══════════════════ */}
                {activeTab === 'privacy' && (
                    <PrivacyDashboard />
                )}

                {/* ═══ Deactivation Confirmation Modal ═══ */}
                {showDeactivateModal && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center px-4" style={{ animation: 'fadeIn 0.3s ease-out' }}>
                        <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={() => setShowDeactivateModal(false)} />
                        <div className="relative w-full max-w-md rounded-2xl bg-white p-8 shadow-2xl border border-light-border" style={{ animation: 'slideUp 0.35s ease-out' }}>
                            <div className="absolute top-0 left-0 right-0 h-1.5 rounded-t-2xl" style={{ background: 'linear-gradient(90deg, #6B2737, #D4A847)' }} />
                            <div className="mx-auto mb-5 flex h-14 w-14 items-center justify-center rounded-full" style={{ background: 'rgba(107, 39, 55, 0.1)' }}>
                                <ShieldOff className="h-7 w-7" style={{ color: '#6B2737' }} />
                            </div>
                            <h2 className="text-center font-serif text-xl font-bold text-charcoal mb-2">Confirm Deactivation</h2>
                            <p className="text-center text-sm text-warm-gray mb-6">
                                Please enter your password to confirm account deactivation.
                            </p>
                            <input
                                type="password"
                                value={deactivatePassword}
                                onChange={e => setDeactivatePassword(e.target.value)}
                                placeholder="Enter your password"
                                className="w-full rounded-lg border border-light-border px-4 py-3 text-sm focus:border-burgundy focus:outline-none mb-6"
                                autoFocus
                            />
                            <div className="flex gap-3">
                                <button
                                    onClick={() => setShowDeactivateModal(false)}
                                    disabled={deactivating}
                                    className="flex-1 rounded-xl border border-light-border py-3 text-sm font-medium text-charcoal hover:bg-cream transition-colors disabled:opacity-50"
                                >
                                    Cancel
                                </button>
                                <button
                                    onClick={async () => {
                                        if (!deactivatePassword) { toast.error('Password is required'); return; }
                                        setDeactivating(true);
                                        try {
                                            const res = await deactivateAccount(deactivatePassword);
                                            if (res.success) {
                                                setShowDeactivateModal(false);
                                                logout();
                                                toast.success('Account deactivated. You can reactivate anytime.');
                                                router.push('/');
                                            } else {
                                                toast.error(res.message || 'Failed to deactivate account');
                                            }
                                        } catch {
                                            toast.error('Server error. Please try again.');
                                        } finally {
                                            setDeactivating(false);
                                        }
                                    }}
                                    disabled={deactivating || !deactivatePassword}
                                    className="flex-1 rounded-xl py-3 text-sm font-semibold text-white transition-all hover:shadow-md disabled:opacity-50"
                                    style={{ backgroundColor: '#6B2737' }}
                                >
                                    {deactivating ? 'Deactivating...' : 'Deactivate'}
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                {/* ═══ Delete Address Confirmation Modal ═══ */}
                {deletingAddressId && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center px-4" style={{ animation: 'fadeIn 0.2s ease-out' }}>
                        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setDeletingAddressId(null)} />
                        <div className="relative w-full max-w-sm rounded-2xl bg-white p-6 shadow-2xl border border-light-border" style={{ animation: 'slideUp 0.25s ease-out' }}>
                            <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-red-50">
                                <Trash2 className="h-5 w-5 text-red-500" />
                            </div>
                            <h3 className="text-center font-serif text-lg font-bold text-charcoal mb-1">Delete Address?</h3>
                            <p className="text-center text-sm text-warm-gray mb-5">This action cannot be undone.</p>
                            <div className="flex gap-3">
                                <button onClick={() => setDeletingAddressId(null)}
                                    className="flex-1 rounded-xl border border-light-border py-2.5 text-sm font-medium text-charcoal hover:bg-cream transition-colors">
                                    Cancel
                                </button>
                                <button onClick={() => deletingAddressId && handleDeleteAddress(deletingAddressId)}
                                    className="flex-1 rounded-xl py-2.5 text-sm font-semibold text-white bg-red-500 hover:bg-red-600 transition-colors">
                                    Delete
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                {/* ═══ Order Details Modal ═══ */}
                {selectedOrderDetails && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center px-4 p-4 sm:p-0" style={{ animation: 'fadeIn 0.2s ease-out' }}>
                        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setSelectedOrderDetails(null)} />
                        <div className="relative w-full max-w-2xl max-h-[90vh] overflow-y-auto rounded-2xl bg-white p-6 shadow-2xl border border-light-border" style={{ animation: 'slideUp 0.25s ease-out' }}>
                            <div className="flex justify-between items-center mb-6">
                                <h3 className="font-serif text-xl font-bold text-charcoal">Order Details</h3>
                                <button onClick={() => setSelectedOrderDetails(null)} className="rounded-full p-2 hover:bg-cream transition-colors text-warm-gray">
                                    <X className="h-5 w-5" />
                                </button>
                            </div>

                            <div className="space-y-6">
                                {/* Order Info */}
                                <div className="grid grid-cols-2 gap-4 bg-cream p-4 rounded-xl text-sm">
                                    <div>
                                        <p className="text-warm-gray mb-1">Order ID</p>
                                        <p className="font-mono font-medium text-charcoal text-xs break-all">{selectedOrderDetails.order_id}</p>
                                    </div>
                                    <div>
                                        <p className="text-warm-gray mb-1">Date</p>
                                        <p className="font-medium text-charcoal">{new Date(selectedOrderDetails.created_at).toLocaleString()}</p>
                                    </div>
                                    <div>
                                        <p className="text-warm-gray mb-1">Order Status</p>
                                        <span className={`inline-block rounded-full px-2 py-0.5 text-xs font-semibold ${getStatusColor(selectedOrderDetails.order_status)}`}>
                                            {selectedOrderDetails.order_status}
                                        </span>
                                    </div>
                                    <div>
                                        <p className="text-warm-gray mb-1">Payment Status</p>
                                        <span className={`inline-block rounded-full px-2 py-0.5 text-xs font-semibold ${selectedOrderDetails.payment_status?.toLowerCase() === 'paid' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                            {selectedOrderDetails.payment_status || 'UNPAID'}
                                        </span>
                                    </div>
                                </div>

                                {/* Items List */}
                                <div>
                                    <h4 className="font-serif text-lg font-bold text-charcoal mb-4">Items</h4>
                                    <div className="space-y-3">
                                        {selectedOrderDetails.items?.map((item: any) => (
                                            <div key={item.order_item_id} className="flex gap-4 p-3 border border-light-border rounded-xl hover:border-burgundy/30 transition-colors">
                                                <div className="h-16 w-16 bg-cream rounded-lg flex items-center justify-center flex-shrink-0 overflow-hidden border border-light-border">
                                                    {item.thumbnail_url ? (
                                                        // eslint-disable-next-line @next/next/no-img-element
                                                        <img src={item.thumbnail_url} alt="Product" className="h-full w-full object-cover" />
                                                    ) : (
                                                        <Package className="h-6 w-6 text-warm-gray" />
                                                    )}
                                                </div>
                                                <div className="flex-1 min-w-0">
                                                    <p className="font-medium text-charcoal truncate">{item.product?.product_name || 'Product'}</p>
                                                    <p className="text-xs text-warm-gray mt-1">Brand: {item.product?.brand || 'N/A'} | Size: {item.variant?.size_label || 'N/A'}</p>
                                                    <div className="flex justify-between items-center mt-2">
                                                        <p className="text-sm font-medium text-charcoal">Qty: {item.quantity}</p>
                                                        <p className="text-sm font-bold text-burgundy">{formatVND(parseFloat(item.line_total || (item.unit_price * item.quantity + item.tax_amount)))}</p>
                                                    </div>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>

                                {/* Summary */}
                                <div className="border-t border-light-border pt-4 space-y-2 text-sm">
                                    <div className="flex justify-between text-warm-gray">
                                        <span>Subtotal</span>
                                        <span>{formatVND(parseFloat(selectedOrderDetails.total_amount))}</span>
                                    </div>
                                    <div className="flex justify-between text-warm-gray">
                                        <span>Tax</span>
                                        <span>{formatVND(parseFloat(selectedOrderDetails.total_tax))}</span>
                                    </div>
                                    <div className="flex justify-between font-bold text-charcoal text-base mt-2 pt-2 border-t border-light-border">
                                        <span>Grand Total</span>
                                        <span className="text-burgundy">{formatVND(parseFloat(selectedOrderDetails.total_amount) + parseFloat(selectedOrderDetails.total_tax))}</span>
                                    </div>
                                </div>

                                {/* Download Invoice Button */}
                                <div className="pt-2">
                                    <button
                                        onClick={async () => {
                                            const toastId = toast.loading('Downloading invoice...');
                                            const res = await downloadInvoice(selectedOrderDetails.order_id);
                                            if (res.success) {
                                                toast.success('Invoice downloaded!', { id: toastId });
                                            } else {
                                                toast.error(res.message || 'Failed to download invoice', { id: toastId });
                                            }
                                        }}
                                        className="w-full rounded-xl bg-gradient-to-r from-[#722F37] to-[#8B3A42] px-4 py-3 text-sm font-semibold text-white hover:from-[#5E252C] hover:to-[#722F37] transition-all shadow-sm hover:shadow-md flex items-center justify-center gap-2"
                                    >
                                        <FileText className="h-4 w-4" />
                                        Download Invoice
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {/* ═══ Track Order Modal ═══ */}
                {isTrackOrderModalOpen && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center px-4" style={{ animation: 'fadeIn 0.2s ease-out' }}>
                        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setIsTrackOrderModalOpen(false)} />
                        <div className="relative w-full max-w-md rounded-2xl bg-white p-8 shadow-2xl border border-light-border text-center" style={{ animation: 'slideUp 0.25s ease-out' }}>
                            <div className="mx-auto mb-5 flex h-16 w-16 items-center justify-center rounded-full bg-cream">
                                <Package className="h-8 w-8 text-burgundy" />
                            </div>
                            <h3 className="font-serif text-2xl font-bold text-charcoal mb-2">Track Order</h3>
                            <p className="font-mono text-sm font-semibold text-warm-gray mb-4">#{trackOrderId?.split('-')[0].toUpperCase()}</p>
                            <div className="bg-light-border/30 rounded-xl p-4 mb-6 relative overflow-hidden">
                                <div className="absolute top-0 left-0 w-1 h-full bg-burgundy"></div>
                                <p className="text-charcoal text-sm leading-relaxed font-medium">
                                    We will integrate with a third-party application for real-time tracking in the future. Check back soon!
                                </p>
                            </div>
                            <button
                                onClick={() => setIsTrackOrderModalOpen(false)}
                                className="w-full rounded-xl py-3 text-sm font-semibold text-white transition-all shadow-md hover:shadow-lg hover:opacity-90"
                                style={{ backgroundColor: '#6B2737' }}
                            >
                                Close
                            </button>
                        </div>
                    </div>
                )}

                {/* Keyframe animations */}
                <style jsx>{`
                    @keyframes fadeIn {
                        from { opacity: 0; }
                        to { opacity: 1; }
                    }
                    @keyframes slideUp {
                        from { opacity: 0; transform: translateY(20px) scale(0.97); }
                        to { opacity: 1; transform: translateY(0) scale(1); }
                    }
                    @keyframes slideDown {
                        from { opacity: 0; max-height: 0; transform: translateY(-10px); }
                        to { opacity: 1; max-height: 800px; transform: translateY(0); }
                    }
                `}</style>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, use } from 'react';
import Link from 'next/link';
import { getBlogPostBySlug, getRelatedBlogPosts, getBlogComments, recordBlogView, BlogPost, BlogComment } from '@/lib/api';
import SocialShareBar from '@/components/blog/SocialShareBar';
import BlogCommentSection from '@/components/blog/BlogCommentSection';
import BlogPostCard from '@/components/blog/BlogPostCard';

export default function BlogPostPage({ params }: { params: Promise<{ slug: string }> }) {
    const resolvedParams = use(params);
    const [post, setPost] = useState<BlogPost | null>(null);
    const [related, setRelated] = useState<BlogPost[]>([]);
    const [comments, setComments] = useState<BlogComment[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        (async () => {
            setLoading(true);
            const p = await getBlogPostBySlug(resolvedParams.slug);
            setPost(p);
            if (p) {
                recordBlogView(p.post_id);
                const [rel, comm] = await Promise.all([
                    getRelatedBlogPosts(p.post_id, 3),
                    getBlogComments(p.post_id),
                ]);
                setRelated(rel);
                setComments(comm);
            }
            setLoading(false);
        })();
    }, [resolvedParams.slug]);

    if (loading) {
        return (
            <div className="min-h-screen bg-cream pt-8">
                <div className="max-w-3xl mx-auto px-4 space-y-6">
                    <div className="h-6 w-32 bg-cream-dark animate-shimmer rounded" />
                    <div className="h-10 w-3/4 bg-cream-dark animate-shimmer rounded" />
                    <div className="h-64 bg-cream-dark animate-shimmer rounded-2xl" />
                    <div className="space-y-3">
                        {[1, 2, 3, 4, 5].map(i => (
                            <div key={i} className="h-4 bg-cream-dark animate-shimmer rounded" />
                        ))}
                    </div>
                </div>
            </div>
        );
    }

    if (!post) {
        return (
            <div className="min-h-screen bg-cream flex items-center justify-center">
                <div className="text-center">
                    <h1 className="font-serif text-3xl font-bold text-charcoal mb-3">Article Not Found</h1>
                    <p className="text-warm-gray mb-6">This article might have been moved or deleted.</p>
                    <Link href="/blog" className="px-6 py-3 rounded-full bg-burgundy text-white font-semibold hover:bg-burgundy-dark transition-colors">
                        Back to Blog
                    </Link>
                </div>
            </div>
        );
    }

    const publishDate = post.published_at
        ? new Date(post.published_at).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })
        : '';

    return (
        <div className="min-h-screen bg-cream">
            {/* ── Header ──────────────────────────────────────────── */}
            <article className="max-w-3xl mx-auto px-4 pt-8 pb-16">
                {/* Breadcrumb */}
                <nav className="flex items-center gap-2 text-sm text-warm-gray mb-6">
                    <Link href="/blog" className="hover:text-burgundy transition-colors">Blog</Link>
                    <span>/</span>
                    {post.category_name && (
                        <>
                            <Link href={`/blog/category/${post.category_slug}`} className="hover:text-burgundy transition-colors">{post.category_name}</Link>
                            <span>/</span>
                        </>
                    )}
                    <span className="text-charcoal truncate max-w-[200px]">{post.title}</span>
                </nav>

                {/* Category + Blog Type */}
                <div className="flex items-center gap-3 mb-4">
                    {post.category_name && (
                        <Link href={`/blog/category/${post.category_slug}`} className="px-3 py-1 rounded-full text-xs font-semibold uppercase tracking-wider bg-burgundy/10 text-burgundy hover:bg-burgundy/20 transition-colors">
                            {post.category_name}
                        </Link>
                    )}
                    {post.blog_type && (
                        <span className="px-3 py-1 rounded-full text-xs font-medium bg-cream-dark text-warm-gray border border-light-border">
                            {post.blog_type.replace(/_/g, ' ')}
                        </span>
                    )}
                </div>

                {/* Title */}
                <h1 className="font-serif text-3xl md:text-4xl font-bold text-charcoal leading-tight mb-4 animate-fade-in-up">
                    {post.title}
                </h1>

                {/* Excerpt */}
                {post.excerpt && (
                    <p className="text-lg text-warm-gray leading-relaxed mb-6">{post.excerpt}</p>
                )}

                {/* Author & Meta */}
                <div className="flex items-center gap-4 mb-8 pb-6 border-b border-light-border">
                    <div className="w-11 h-11 rounded-full bg-burgundy/10 flex items-center justify-center text-burgundy font-serif font-bold text-lg flex-shrink-0">
                        {post.author_avatar ? (
                            <img src={post.author_avatar} alt={post.author_name} className="w-full h-full rounded-full object-cover" />
                        ) : (
                            post.author_name?.charAt(0) || '?'
                        )}
                    </div>
                    <div>
                        {post.author_name && <p className="text-sm font-semibold text-charcoal">{post.author_name}</p>}
                        <div className="flex items-center gap-2 text-xs text-warm-gray">
                            {publishDate && <span>{publishDate}</span>}
                            {post.reading_time && (
                                <>
                                    <span className="w-1 h-1 rounded-full bg-warm-gray/40" />
                                    <span>{post.reading_time} min read</span>
                                </>
                            )}
                            {(post.view_count ?? 0) > 0 && (
                                <>
                                    <span className="w-1 h-1 rounded-full bg-warm-gray/40" />
                                    <span>{post.view_count?.toLocaleString()} views</span>
                                </>
                            )}
                        </div>
                    </div>
                    <div className="ml-auto">
                        <SocialShareBar shareUrls={post.share_urls} postId={post.post_id} title={post.title} />
                    </div>
                </div>

                {/* Cover Image */}
                {post.cover_image && (
                    <div className="rounded-2xl overflow-hidden mb-8 border border-light-border">
                        <img src={post.cover_image} alt={post.title} className="w-full h-auto" />
                    </div>
                )}

                {/* Tags */}
                {post.tags && post.tags.length > 0 && (
                    <div className="flex flex-wrap gap-2 mb-8">
                        {post.tags.map(tag => (
                            <Link
                                key={tag.tag_id}
                                href={`/blog/tag/${tag.slug}`}
                                className="px-3 py-1 rounded-full text-xs font-medium bg-cream-dark text-charcoal border border-light-border hover:border-burgundy/30 hover:text-burgundy transition-all"
                            >
                                #{tag.name}
                            </Link>
                        ))}
                    </div>
                )}

                {/* Article Body */}
                <div
                    className="prose prose-lg max-w-none text-charcoal/90 leading-relaxed
                        prose-headings:font-serif prose-headings:text-charcoal
                        prose-h2:text-2xl prose-h2:mt-10 prose-h2:mb-4
                        prose-h3:text-xl prose-h3:mt-8 prose-h3:mb-3
                        prose-p:mb-5
                        prose-a:text-burgundy prose-a:no-underline hover:prose-a:underline
                        prose-blockquote:border-l-burgundy/40 prose-blockquote:bg-cream-dark prose-blockquote:rounded-r-xl prose-blockquote:py-1 prose-blockquote:px-5
                        prose-img:rounded-xl prose-img:border prose-img:border-light-border
                        prose-strong:text-charcoal"
                    dangerouslySetInnerHTML={{ __html: post.body }}
                />

                {/* Bottom Share Bar */}
                <div className="mt-10 pt-6 border-t border-light-border">
                    <SocialShareBar shareUrls={post.share_urls} postId={post.post_id} title={post.title} />
                </div>

                {/* Author Bio */}
                {post.author_bio && (
                    <div className="mt-8 rounded-2xl border border-light-border bg-white p-6 flex gap-4 items-start">
                        <div className="w-14 h-14 rounded-full bg-burgundy/10 flex items-center justify-center text-burgundy font-serif font-bold text-xl flex-shrink-0">
                            {post.author_avatar ? (
                                <img src={post.author_avatar} alt={post.author_name} className="w-full h-full rounded-full object-cover" />
                            ) : (
                                post.author_name?.charAt(0) || '?'
                            )}
                        </div>
                        <div>
                            <p className="font-serif font-bold text-charcoal mb-1">About {post.author_name}</p>
                            <p className="text-sm text-warm-gray leading-relaxed">{post.author_bio}</p>
                        </div>
                    </div>
                )}

                {/* Related Posts */}
                {related.length > 0 && (
                    <section className="mt-12">
                        <h3 className="font-serif text-xl font-bold text-charcoal mb-6">You Might Also Like</h3>
                        <div className="grid md:grid-cols-3 gap-4">
                            {related.map(p => (
                                <BlogPostCard key={p.post_id} post={p} />
                            ))}
                        </div>
                    </section>
                )}

                {/* Comments */}
                <BlogCommentSection postId={post.post_id} initialComments={comments} />
            </article>
        </div>
    );
}

'use client';

import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useState } from 'react';
import { useCart } from '@/context/CartContext';
import { useAuth } from '@/context/AuthContext';
import { Minus, Plus, X, ShoppingCart, ArrowLeft, Loader2, Ticket, Bookmark } from 'lucide-react';
import { formatVND } from '@/lib/api';
import toast from 'react-hot-toast';

export default function CartPage() {
    const {
        items, savedItems, updateQuantity, removeItem, saveForLater, moveToCart,
        totalPrice, totalItems, loading, error,
        couponCode, couponDiscount, couponType, couponError, applyCoupon, removeCoupon,
    } = useCart();
    const { isAuthenticated } = useAuth();
    const router = useRouter();
    const [couponInput, setCouponInput] = useState('');
    const [applyingCoupon, setApplyingCoupon] = useState(false);

    // Loading state
    if (loading && items.length === 0) {
        return (
            <div className="min-h-screen bg-cream flex items-center justify-center">
                <Loader2 className="h-8 w-8 animate-spin text-burgundy" />
            </div>
        );
    }

    if (items.length === 0 && savedItems.length === 0) {
        return (
            <div className="min-h-screen bg-cream flex items-center justify-center">
                <div className="text-center">
                    <ShoppingCart className="mx-auto h-16 w-16 text-warm-gray/40 mb-4" />
                    <h1 className="font-serif text-2xl font-bold text-charcoal">Your Cart is Empty</h1>
                    <p className="mt-2 text-warm-gray">Explore our wines and add something you like</p>
                    <Link
                        href="/products"
                        className="mt-6 inline-flex items-center gap-2 rounded-lg bg-burgundy px-8 py-3 text-sm font-semibold text-white hover:bg-burgundy-dark transition-colors"
                    >
                        Continue Shopping
                    </Link>
                </div>
            </div>
        );
    }

    // Compute price breakdown
    const totalMRP = items.reduce((sum, item) => sum + (item.original_price ?? item.price ?? 0) * item.quantity, 0);
    const saleDiscount = totalMRP - items.reduce((sum, item) => sum + (item.price ?? 0) * item.quantity, 0);

    // Total taxes are not exposed directly in CartContext at the top level, but it can be derived if not available
    // or we can sum it up from the items:
    const totalTaxes = items.reduce((sum, item) => sum + ((item as any).pricing?.tax_amount ?? 0), 0);

    const deliveryFee = couponType === 'free_shipping' ? 0 : (totalPrice > 50 ? 0 : 5);

    // Use the backend's grandTotal directly since that includes taxes. If there's a coupon, 
    // the backend will handle it, but since applying coupon happens client-side for delivery sometimes:
    const grandTotal = totalPrice - couponDiscount + deliveryFee;

    return (
        <div className="min-h-screen bg-cream">
            {/* Step Indicator */}
            <div className="border-b border-light-border bg-white py-6">
                <div className="mx-auto max-w-4xl flex items-center justify-center gap-8">
                    {['Cart', 'Address', 'Payment', 'Confirmation'].map((step, i) => (
                        <div key={step} className="flex items-center gap-2">
                            <div className={`flex h-8 w-8 items-center justify-center rounded-full text-sm font-semibold ${i === 0 ? 'bg-burgundy text-white' : 'bg-cream-dark text-warm-gray'
                                }`}>
                                {i + 1}
                            </div>
                            <span className={`text-sm font-medium ${i === 0 ? 'text-burgundy' : 'text-warm-gray'}`}>
                                {step}
                            </span>
                        </div>
                    ))}
                </div>
            </div>

            <div className="mx-auto max-w-7xl px-4 py-10">
                <h1 className="font-serif text-3xl font-bold text-charcoal mb-8">Your Cart</h1>

                {error && (
                    <div className="mb-4 rounded-lg bg-red-50 border border-red-200 p-3 text-sm text-red-700">
                        {error}
                    </div>
                )}

                <div className="lg:grid lg:grid-cols-[1fr_380px] lg:gap-8">
                    {/* Left Column: Cart Items + Saved Items */}
                    <div className="flex flex-col gap-12">
                        {/* Cart Items */}
                        <div className="space-y-4">
                            {items.length === 0 ? (
                                <div className="rounded-xl border border-dashed border-light-border p-8 text-center bg-white/50">
                                    <p className="text-warm-gray font-medium">Your active cart is empty.</p>
                                </div>
                            ) : (
                                items.map(item => {
                                    const price = item.price ?? 0;
                                    return (
                                        <div
                                            key={item.cart_item_id}
                                            className="flex items-center gap-4 rounded-xl border border-light-border bg-white p-4 sm:p-6 transition-all hover:shadow-sm"
                                        >
                                            {/* Image */}
                                            <Link href={`/products/${item.product_id || item.product?.product_id || ''}`} className="h-20 w-20 sm:h-24 sm:w-24 flex-shrink-0 rounded-lg bg-cream-dark flex items-center justify-center cursor-pointer hover:opacity-80 transition-opacity">
                                                {item.image_url ? (
                                                    <img src={item.image_url} alt={item.product_name || ''} className="h-full w-full object-cover rounded-lg" />
                                                ) : (
                                                    <span className="text-4xl">🍷</span>
                                                )}
                                            </Link>

                                            {/* Info */}
                                            <div className="flex-1 min-w-0">
                                                <Link href={`/products/${item.product_id || item.product?.product_id || ''}`} className="hover:text-burgundy transition-colors">
                                                    <h3 className="font-serif text-base font-semibold text-charcoal truncate">
                                                        {item.product_name || 'Product'}
                                                    </h3>
                                                </Link>
                                                {item.size_label && (
                                                    <p className="text-xs text-warm-gray mt-0.5">{item.size_label}</p>
                                                )}
                                                {item.sku && (
                                                    <p className="text-xs text-warm-gray mt-0.5">SKU: {item.sku}</p>
                                                )}
                                                <p className="mt-1 font-serif text-lg font-bold text-burgundy">
                                                    {formatVND(price)}
                                                </p>
                                            </div>

                                            {/* Quantity */}
                                            <div className="flex items-center rounded-lg border border-light-border">
                                                <button
                                                    onClick={() => updateQuantity(item.cart_item_id, item.quantity - 1)}
                                                    disabled={loading}
                                                    className="px-2.5 py-1.5 text-warm-gray hover:text-charcoal disabled:opacity-50"
                                                >
                                                    <Minus className="h-3 w-3" />
                                                </button>
                                                <span className="w-8 text-center text-sm font-medium text-charcoal">{item.quantity}</span>
                                                <button
                                                    onClick={() => updateQuantity(item.cart_item_id, item.quantity + 1)}
                                                    disabled={loading}
                                                    className="px-2.5 py-1.5 text-warm-gray hover:text-charcoal disabled:opacity-50"
                                                >
                                                    <Plus className="h-3 w-3" />
                                                </button>
                                            </div>

                                            {/* Actions */}
                                            <div className="flex flex-col gap-2 items-end justify-center ml-2">
                                                <button
                                                    onClick={() => { removeItem(item.cart_item_id); toast.success('Removed from cart'); }}
                                                    disabled={loading}
                                                    className="p-2.5 text-warm-gray hover:text-red-500 hover:bg-red-50 rounded-full transition-colors disabled:opacity-50"
                                                    title="Remove item"
                                                >
                                                    <X className="h-5 w-5" />
                                                </button>
                                                <button
                                                    onClick={() => { saveForLater(item.cart_item_id); toast.success('Saved for later'); }}
                                                    disabled={loading}
                                                    className="p-2.5 text-warm-gray hover:text-burgundy hover:bg-burgundy/5 rounded-full transition-colors disabled:opacity-50"
                                                    title="Save for later"
                                                >
                                                    <Bookmark className="h-4 w-4" />
                                                </button>
                                            </div>
                                        </div>
                                    );
                                }))}
                        </div>

                        {/* Saved for Later Section */}
                        {savedItems.length > 0 && (
                            <div>
                                <h2 className="font-serif text-2xl font-bold text-charcoal mb-6 border-b border-light-border pb-4 flex items-center gap-2">
                                    <Bookmark className="h-6 w-6 text-burgundy" />
                                    Saved for Later ({savedItems.length})
                                </h2>
                                <div className="space-y-4">
                                    {savedItems.map(item => {
                                        const price = item.price ?? 0;
                                        return (
                                            <div
                                                key={item.cart_item_id}
                                                className="flex items-center gap-4 rounded-xl border border-light-border bg-white p-4 sm:p-6 transition-all hover:shadow-sm opacity-80 hover:opacity-100"
                                            >
                                                {/* Image */}
                                                <Link href={`/products/${item.product_id || item.product?.product_id || ''}`} className="h-16 w-16 sm:h-20 sm:w-20 flex-shrink-0 rounded-lg bg-cream-dark flex items-center justify-center cursor-pointer">
                                                    {item.image_url ? (
                                                        <img src={item.image_url} alt={item.product_name || ''} className="h-full w-full object-cover rounded-lg" />
                                                    ) : (
                                                        <span className="text-3xl">🍷</span>
                                                    )}
                                                </Link>

                                                {/* Info */}
                                                <div className="flex-1 min-w-0">
                                                    <Link href={`/products/${item.product_id || item.product?.product_id || ''}`} className="hover:text-burgundy transition-colors">
                                                        <h3 className="font-serif text-base font-semibold text-charcoal truncate">
                                                            {item.product_name || 'Product'}
                                                        </h3>
                                                    </Link>
                                                    {item.size_label && (
                                                        <p className="text-xs text-warm-gray mt-0.5">{item.size_label}</p>
                                                    )}
                                                    <p className="mt-1 font-serif text-lg font-bold text-warm-gray">
                                                        {formatVND(price)}
                                                    </p>
                                                </div>

                                                {/* Actions */}
                                                <div className="flex flex-col gap-2 items-end">
                                                    <button
                                                        onClick={() => { moveToCart(item.cart_item_id); toast.success('Moved to cart'); }}
                                                        disabled={loading}
                                                        className="px-4 py-2 text-sm font-semibold rounded-lg bg-burgundy/10 text-burgundy hover:bg-burgundy hover:text-white transition-colors disabled:opacity-50 whitespace-nowrap"
                                                    >
                                                        Move to Cart
                                                    </button>
                                                    <button
                                                        onClick={() => { removeItem(item.cart_item_id); toast.success('Removed saved item'); }}
                                                        disabled={loading}
                                                        className="px-4 py-2 text-sm font-medium text-warm-gray hover:text-red-500 transition-colors disabled:opacity-50"
                                                    >
                                                        Remove
                                                    </button>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Order Summary */}
                    <div className="mt-8 lg:mt-0">
                        <div className="sticky top-24 rounded-xl border border-light-border bg-white p-6">
                            <h2 className="font-serif text-lg font-bold text-charcoal mb-4">Order Summary</h2>

                            {/* Item list */}
                            <div className="space-y-3 text-sm border-b border-light-border pb-4 mb-4">
                                {items.map(item => {
                                    const price = item.price ?? 0;
                                    const lineTotal = price * item.quantity;
                                    return (
                                        <div key={item.cart_item_id} className="flex items-start gap-3">
                                            <div className="h-12 w-12 flex-shrink-0 rounded-lg bg-cream-dark flex items-center justify-center">
                                                {item.image_url ? (
                                                    <img src={item.image_url} alt="" className="h-full w-full object-cover rounded-lg" />
                                                ) : (
                                                    <span className="text-lg">🍷</span>
                                                )}
                                            </div>
                                            <div className="flex-1 min-w-0">
                                                <p className="text-charcoal font-medium truncate">{item.product_name || 'Product'}</p>
                                                <p className="text-xs text-warm-gray">
                                                    {formatVND(price)} × {item.quantity}
                                                </p>
                                            </div>
                                            <p className="text-charcoal font-medium">{formatVND(lineTotal)}</p>
                                        </div>
                                    );
                                })}
                            </div>

                            {/* Price breakdown */}
                            <div className="space-y-2.5 text-sm">
                                <div className="flex justify-between">
                                    <span className="text-warm-gray">Total MRP</span>
                                    <span className="text-charcoal">{formatVND(totalMRP)}</span>
                                </div>
                                <div className="flex justify-between">
                                    <span className="text-warm-gray">Discount on MRP</span>
                                    <span className={saleDiscount > 0 ? 'text-green-600 font-medium' : 'text-charcoal'}>
                                        {saleDiscount > 0 ? `-${formatVND(saleDiscount)}` : formatVND(0)}
                                    </span>
                                </div>
                                <div className="flex justify-between">
                                    <span className="text-warm-gray">Coupon Discount</span>
                                    <span className={couponDiscount > 0 ? 'text-green-600 font-medium' : 'text-charcoal'}>
                                        {couponDiscount > 0 ? `-${formatVND(couponDiscount)}` : formatVND(0)}
                                    </span>
                                </div>
                                {totalTaxes > 0 && (
                                    <div className="flex justify-between">
                                        <span className="text-warm-gray">Taxes (VAT & Excise)</span>
                                        <span className="text-charcoal">{formatVND(totalTaxes)}</span>
                                    </div>
                                )}
                                <div className="flex justify-between">
                                    <span className="text-warm-gray">Delivery Fee</span>
                                    <span className={deliveryFee === 0 ? 'text-green-600 font-medium' : 'text-charcoal'}>
                                        {deliveryFee === 0 ? 'FREE' : formatVND(deliveryFee)}
                                    </span>
                                </div>
                            </div>

                            {/* Coupon Input Section */}
                            <div className="mt-4 border-t border-light-border pt-4">
                                {couponCode ? (
                                    <div className="flex items-center justify-between bg-green-50 border border-green-200 rounded-lg px-4 py-2.5">
                                        <div className="flex items-center gap-2">
                                            <Ticket className="h-4 w-4 text-green-600" />
                                            <span className="text-sm font-medium text-green-700">{couponCode}</span>
                                            <span className="text-xs text-green-600">(-{formatVND(couponDiscount)})</span>
                                        </div>
                                        <button onClick={() => { removeCoupon(); toast.success('Coupon removed'); }} className="text-xs text-red-500 hover:text-red-700 font-medium">
                                            Remove
                                        </button>
                                    </div>
                                ) : (
                                    <div>
                                        <div className="flex gap-2">
                                            <input
                                                type="text"
                                                placeholder="Enter coupon code"
                                                value={couponInput}
                                                onChange={e => setCouponInput(e.target.value.toUpperCase())}
                                                className="flex-1 rounded-lg border border-light-border px-3 py-2 text-sm font-mono uppercase focus:border-burgundy focus:outline-none"
                                            />
                                            <button
                                                onClick={async () => {
                                                    if (!couponInput.trim()) return;
                                                    setApplyingCoupon(true);
                                                    const ok = await applyCoupon(couponInput.trim());
                                                    if (ok) { toast.success('Coupon applied!'); setCouponInput(''); }
                                                    setApplyingCoupon(false);
                                                }}
                                                disabled={applyingCoupon || !couponInput.trim()}
                                                className="rounded-lg bg-burgundy px-4 py-2 text-sm font-semibold text-white hover:bg-burgundy-dark transition-colors disabled:opacity-50 flex items-center gap-1"
                                            >
                                                {applyingCoupon ? <Loader2 className="h-3 w-3 animate-spin" /> : 'Apply'}
                                            </button>
                                        </div>
                                        {couponError && (
                                            <p className="mt-1.5 text-xs text-red-500">{couponError}</p>
                                        )}
                                    </div>
                                )}
                            </div>

                            {/* Grand Total */}
                            <div className="mt-4 border-t border-light-border pt-4 flex justify-between">
                                <span className="font-serif text-lg font-bold text-burgundy">Grand Total</span>
                                <span className="font-serif text-lg font-bold text-burgundy">{formatVND(grandTotal)}</span>
                            </div>

                            <button
                                onClick={() => {
                                    if (!isAuthenticated) {
                                        toast('Please sign in to proceed to checkout', { icon: '🔐' });
                                        router.push('/login?redirect=/cart');
                                    } else {
                                        router.push('/checkout');
                                    }
                                }}
                                className="mt-6 flex w-full items-center justify-center gap-2 rounded-lg bg-burgundy py-3 text-sm font-semibold text-white transition-all hover:bg-burgundy-dark"
                            >
                                {isAuthenticated ? 'Proceed to Checkout' : 'Sign In to Checkout'}
                            </button>
                        </div>
                    </div>
                </div>

                {/* Continue Shopping */}
                <div className="mt-8">
                    <Link
                        href="/products"
                        className="inline-flex items-center gap-2 rounded-lg border border-light-border px-4 py-2.5 text-sm font-medium text-charcoal hover:bg-white transition-colors"
                    >
                        <ArrowLeft className="h-4 w-4" /> Continue Shopping
                    </Link>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { useCart } from '@/context/CartContext';
import { useAuth } from '@/context/AuthContext';
import { checkoutOrder, directCheckout, getAddresses, formatVND } from '@/lib/api';
import { Address } from '@/types';
import { CheckCircle, Loader2, MapPin } from 'lucide-react';
import toast from 'react-hot-toast';
import Link from 'next/link';

interface BuyNowItem {
    product_id: string;
    product_name: string;
    variant_id: string | null;
    size_label: string;
    quantity: number;
    unit_price: number;
    image_url: string;
}

export default function CheckoutPage() {
    const router = useRouter();
    const searchParams = useSearchParams();
    const isBuyNow = searchParams.get('buyNow') === 'true';
    const { items, totalPrice, clearCart, cartId, couponCode, couponDiscount, couponType, removeCoupon } = useCart();
    const { user, isAuthenticated, verifyUserAge } = useAuth();
    const [step, setStep] = useState(1); // 1: Address, 2: Payment, 3: Confirmation
    const [orderPlaced, setOrderPlaced] = useState(false);
    const [placing, setPlacing] = useState(false);
    const [orderId, setOrderId] = useState<string | null>(null);
    const [orderNotes, setOrderNotes] = useState('');

    // Age Verification State
    const [showAgeModal, setShowAgeModal] = useState(false);
    const [dob, setDob] = useState('');
    const [verifyingAge, setVerifyingAge] = useState(false);

    // Saved addresses
    const [savedAddresses, setSavedAddresses] = useState<Address[]>([]);
    const [selectedAddressId, setSelectedAddressId] = useState<string | null>(null);
    const [useNewAddress, setUseNewAddress] = useState(false);
    const [addressesLoading, setAddressesLoading] = useState(false);

    // New address form fields (matching backend)
    const [newAddress, setNewAddress] = useState({
        address_line1: '', address_line2: '', city: '', state: '', pincode: '', phone: '',
    });

    // Buy Now single-item state
    const [buyNowItem, setBuyNowItem] = useState<BuyNowItem | null>(null);

    // Load Buy Now item from sessionStorage
    useEffect(() => {
        if (isBuyNow) {
            try {
                const stored = sessionStorage.getItem('ksp_buy_now_item');
                if (stored) {
                    setBuyNowItem(JSON.parse(stored));
                } else {
                    // No item found, fall back to normal cart checkout
                    router.replace('/checkout');
                }
            } catch {
                router.replace('/checkout');
            }
        }
    }, [isBuyNow, router]);

    // Compute prices based on Buy Now or Cart
    const checkoutItems = isBuyNow && buyNowItem
        ? [buyNowItem]
        : items;

    // Base subtotal without taxes (MRP)
    const baseSubtotal = isBuyNow && buyNowItem
        ? buyNowItem.unit_price * buyNowItem.quantity
        : items.reduce((sum, item) => sum + (item.price ?? 0) * item.quantity, 0);

    // Compute taxes: sum from cart items, or 0 for Buy Now (since BuyNow didn't compute them yet, just an approximation)
    const totalTaxes = isBuyNow ? 0 : items.reduce((sum, item) => sum + ((item as any).pricing?.tax_amount ?? 0), 0);

    // totalPrice from context already includes taxes. BuyNow currently ignores taxes.
    const subtotalWithTaxes = isBuyNow && buyNowItem
        ? buyNowItem.unit_price * buyNowItem.quantity
        : totalPrice;

    const shippingCost = couponType === 'free_shipping' ? 0 : (subtotalWithTaxes > 50 ? 0 : 5);
    const discount = isBuyNow ? 0 : couponDiscount; // Coupons don't apply to Buy Now
    const grandTotal = subtotalWithTaxes + shippingCost - discount;

    // Load saved addresses for logged-in users
    useEffect(() => {
        if (user?.id) {
            setAddressesLoading(true);
            getAddresses(user.id)
                .then(res => {
                    if (res.success && Array.isArray(res.data)) {
                        setSavedAddresses(res.data);
                        const defaultAddr = res.data.find((a: Address) => a.is_default) || res.data[0];
                        if (defaultAddr) {
                            setSelectedAddressId(defaultAddr.address_id);
                        } else {
                            setUseNewAddress(true);
                        }
                    } else {
                        setUseNewAddress(true);
                    }
                })
                .catch(() => setUseNewAddress(true))
                .finally(() => setAddressesLoading(false));
        } else {
            setUseNewAddress(true);
        }
    }, [user?.id]);

    useEffect(() => {
        // Only redirect to cart if NOT in Buy Now mode and cart is empty
        if (!isBuyNow && items.length === 0 && !orderPlaced) {
            router.push('/cart');
        }
    }, [items.length, orderPlaced, router, isBuyNow]);

    // Auto-proceed checkout when is_age_verified becomes true
    useEffect(() => {
        if (isAuthenticated && user?.is_age_verified && showAgeModal) {
            toast.success('Age verified. Placing order...');
            setShowAgeModal(false);
            // We can't call handlePlaceOrder here directly since it's defined below,
            // so we set a flag that the JSX/next render cycle will pick up
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [user?.is_age_verified]);

    if (!isBuyNow && items.length === 0 && !orderPlaced) {
        return null;
    }
    // For Buy Now mode, wait until item is loaded
    if (isBuyNow && !buyNowItem && !orderPlaced) {
        return (
            <div className="min-h-screen bg-cream flex items-center justify-center">
                <Loader2 className="h-8 w-8 animate-spin text-burgundy" />
            </div>
        );
    }

    const handlePlaceOrder = async () => {
        // Validate address
        if (useNewAddress) {
            if (!newAddress.address_line1 || !newAddress.city || !newAddress.state || !newAddress.pincode) {
                toast.error('Please fill in all required address fields');
                return;
            }
        } else if (!selectedAddressId) {
            toast.error('Please select a shipping address');
            return;
        }

        if (isAuthenticated && user && !user.is_age_verified) {
            setShowAgeModal(true);
            return;
        }

        setPlacing(true);

        try {
            let result;

            if (isBuyNow && buyNowItem) {
                // ── Buy Now: use directCheckout for the single item only ──
                result = await directCheckout({
                    customer_id: user?.id || undefined,
                    customer_name: user?.name || undefined,
                    customer_email: user?.email || undefined,
                    items: [{
                        product_id: buyNowItem.product_id,
                        variant_id: buyNowItem.variant_id,
                        quantity: buyNowItem.quantity,
                        unit_price: buyNowItem.unit_price,
                    }],
                    shipping_address_id: useNewAddress ? undefined : selectedAddressId || undefined,
                    shipping_address: useNewAddress ? newAddress as unknown as Record<string, string> : undefined,
                    payment_method: 'cod',
                    order_notes: orderNotes.trim() || undefined,
                });
            } else if (isAuthenticated && cartId && user?.id) {
                // Cart-based checkout for logged-in users
                result = await checkoutOrder({
                    cart_id: cartId,
                    customer_id: user.id,
                    shipping_address_id: useNewAddress ? undefined : selectedAddressId || undefined,
                    coupon_code: couponCode || undefined,
                    order_notes: orderNotes.trim() || undefined,
                });
            } else {
                // Direct checkout fallback (guest or no cart)
                const orderItems = items.map(item => ({
                    product_id: item.product_id || '',
                    variant_id: item.variant_id,
                    quantity: item.quantity,
                    unit_price: Number(item.price) || 0,
                }));

                result = await directCheckout({
                    customer_id: user?.id || undefined,
                    customer_name: user?.name || undefined,
                    customer_email: user?.email || undefined,
                    items: orderItems,
                    shipping_address: useNewAddress ? newAddress as unknown as Record<string, string> : undefined,
                    payment_method: 'cod',
                    coupon_code: couponCode || undefined,
                    order_notes: orderNotes.trim() || undefined,
                });
            }

            if (result.success) {
                setOrderId(result.data?.order_id || null);
                // Only clear cart on non-Buy Now flows
                if (!isBuyNow) {
                    await clearCart(true);
                    removeCoupon();
                }
                // Clean up Buy Now sessionStorage
                sessionStorage.removeItem('ksp_buy_now_item');
                setOrderPlaced(true);
                setStep(3);
                toast.success('Order placed successfully!');
            } else {
                toast.error(result.message || 'Failed to place order');
            }
        } catch (error) {
            console.error('Checkout error:', error);
            toast.error('Something went wrong. Please try again.');
        } finally {
            setPlacing(false);
        }
    };

    const handleVerifyAge = async () => {
        if (!dob) {
            toast.error('Please enter your date of birth');
            return;
        }
        setVerifyingAge(true);
        try {
            const res = await verifyUserAge(dob);
            if (res.success) {
                toast.success('Age verified successfully!');
                setShowAgeModal(false);
                // After success, recursively call handlePlaceOrder, but since user state updates asynchronously
                // we might need to rely on the updated user.is_age_verified. But the API already succeeded so 
                // we'll just bypass the check by calling handlePlaceOrder immediately. However, since the state needs time to update,
                // let's manually update the state or just bypass the check
            } else {
                toast.error(res.error || 'You must be 18 or older to purchase.');
            }
        } catch (error) {
            toast.error('Something went wrong verifying your age.');
        } finally {
            setVerifyingAge(false);
        }
    };



    // Order Confirmation
    if (orderPlaced) {
        return (
            <div className="min-h-screen bg-cream flex items-center justify-center">
                <div className="text-center max-w-md p-8">
                    <CheckCircle className="mx-auto h-20 w-20 text-green-600 mb-6" />
                    <h1 className="font-serif text-3xl font-bold text-charcoal">Order Confirmed!</h1>
                    {orderId && (
                        <p className="mt-2 text-sm font-mono text-warm-gray">Order ID: {orderId}</p>
                    )}
                    <p className="mt-3 text-warm-gray">
                        Thank you for your order. We&apos;ll send you an email confirmation shortly.
                    </p>
                    <div className="mt-8 flex flex-col gap-3">
                        <Link
                            href="/account"
                            className="rounded-lg bg-burgundy py-3 text-sm font-semibold text-white hover:bg-burgundy-dark transition-colors"
                        >
                            View Order History
                        </Link>
                        <Link
                            href="/products"
                            className="rounded-lg border border-light-border py-3 text-sm font-medium text-charcoal hover:bg-white transition-colors"
                        >
                            Continue Shopping
                        </Link>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-cream">
            {/* Step Indicator */}
            <div className="border-b border-light-border bg-white py-6">
                <div className="mx-auto max-w-4xl flex items-center justify-center gap-8">
                    {['Cart', 'Address', 'Payment', 'Confirmation'].map((s, i) => (
                        <div key={s} className="flex items-center gap-2">
                            <div className={`flex h-8 w-8 items-center justify-center rounded-full text-sm font-semibold ${i <= step ? 'bg-burgundy text-white' : 'bg-cream-dark text-warm-gray'
                                }`}>
                                {i + 1}
                            </div>
                            <span className={`text-sm font-medium hidden sm:inline ${i <= step ? 'text-burgundy' : 'text-warm-gray'}`}>
                                {s}
                            </span>
                        </div>
                    ))}
                </div>
            </div>

            <div className="mx-auto max-w-4xl px-4 py-10">
                {step === 1 && (
                    <div>
                        <h1 className="font-serif text-2xl font-bold text-charcoal mb-6">Shipping Address</h1>

                        {/* Saved Addresses */}
                        {addressesLoading ? (
                            <div className="flex justify-center py-8">
                                <Loader2 className="h-6 w-6 animate-spin text-burgundy" />
                            </div>
                        ) : savedAddresses.length > 0 && (
                            <div className="mb-6">
                                <p className="text-sm font-medium text-charcoal mb-3">Select a saved address:</p>
                                <div className="grid gap-3 sm:grid-cols-2">
                                    {savedAddresses.map(addr => (
                                        <label
                                            key={addr.address_id}
                                            className={`flex items-start gap-3 rounded-xl border p-4 cursor-pointer transition-colors ${selectedAddressId === addr.address_id && !useNewAddress
                                                ? 'border-burgundy bg-burgundy/5'
                                                : 'border-light-border hover:border-burgundy/50'
                                                }`}
                                        >
                                            <input
                                                type="radio"
                                                name="address"
                                                checked={selectedAddressId === addr.address_id && !useNewAddress}
                                                onChange={() => { setSelectedAddressId(addr.address_id); setUseNewAddress(false); }}
                                                className="mt-1 accent-burgundy"
                                            />
                                            <div>
                                                {addr.label && <span className="text-xs font-bold text-burgundy uppercase">{addr.label}</span>}
                                                <p className="text-sm text-charcoal">{addr.address_line1}</p>
                                                {addr.address_line2 && <p className="text-sm text-warm-gray">{addr.address_line2}</p>}
                                                <p className="text-sm text-warm-gray">{addr.city}, {addr.state} {addr.pincode}</p>
                                                {addr.phone && <p className="text-xs text-warm-gray mt-1">📞 {addr.phone}</p>}
                                            </div>
                                        </label>
                                    ))}
                                </div>

                                <button
                                    onClick={() => setUseNewAddress(true)}
                                    className={`mt-3 flex items-center gap-2 text-sm font-medium transition-colors ${useNewAddress ? 'text-burgundy' : 'text-warm-gray hover:text-charcoal'}`}
                                >
                                    <MapPin className="h-4 w-4" /> Use a new address
                                </button>
                            </div>
                        )}

                        {/* New Address Form */}
                        {useNewAddress && (
                            <div className="rounded-xl border border-light-border bg-white p-6">
                                <div className="grid gap-4 sm:grid-cols-2">
                                    <div className="sm:col-span-2">
                                        <label className="block text-sm font-medium text-charcoal mb-1">Address Line 1 *</label>
                                        <input
                                            type="text"
                                            value={newAddress.address_line1}
                                            onChange={e => setNewAddress({ ...newAddress, address_line1: e.target.value })}
                                            className="w-full rounded-lg border border-light-border px-4 py-2.5 text-sm focus:border-burgundy focus:outline-none"
                                            placeholder="Street address"
                                        />
                                    </div>
                                    <div className="sm:col-span-2">
                                        <label className="block text-sm font-medium text-charcoal mb-1">Address Line 2</label>
                                        <input
                                            type="text"
                                            value={newAddress.address_line2}
                                            onChange={e => setNewAddress({ ...newAddress, address_line2: e.target.value })}
                                            className="w-full rounded-lg border border-light-border px-4 py-2.5 text-sm focus:border-burgundy focus:outline-none"
                                            placeholder="Apartment, suite, etc."
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-charcoal mb-1">City *</label>
                                        <input
                                            type="text"
                                            value={newAddress.city}
                                            onChange={e => setNewAddress({ ...newAddress, city: e.target.value })}
                                            className="w-full rounded-lg border border-light-border px-4 py-2.5 text-sm focus:border-burgundy focus:outline-none"
                                            placeholder="City"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-charcoal mb-1">State *</label>
                                        <input
                                            type="text"
                                            value={newAddress.state}
                                            onChange={e => setNewAddress({ ...newAddress, state: e.target.value })}
                                            className="w-full rounded-lg border border-light-border px-4 py-2.5 text-sm focus:border-burgundy focus:outline-none"
                                            placeholder="State"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-charcoal mb-1">Pincode *</label>
                                        <input
                                            type="text"
                                            value={newAddress.pincode}
                                            onChange={e => setNewAddress({ ...newAddress, pincode: e.target.value })}
                                            className="w-full rounded-lg border border-light-border px-4 py-2.5 text-sm focus:border-burgundy focus:outline-none"
                                            placeholder="Pincode"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-charcoal mb-1">Phone</label>
                                        <input
                                            type="tel"
                                            value={newAddress.phone}
                                            onChange={e => setNewAddress({ ...newAddress, phone: e.target.value })}
                                            className="w-full rounded-lg border border-light-border px-4 py-2.5 text-sm focus:border-burgundy focus:outline-none"
                                            placeholder="Phone number"
                                        />
                                    </div>
                                </div>
                            </div>
                        )}

                        <button
                            onClick={() => setStep(2)}
                            className="mt-6 w-full rounded-lg bg-burgundy py-3 text-sm font-semibold text-white hover:bg-burgundy-dark transition-colors"
                        >
                            Continue to Payment
                        </button>
                    </div>
                )}

                {step === 2 && (
                    <div>
                        <h1 className="font-serif text-2xl font-bold text-charcoal mb-6">Payment</h1>
                        <div className="rounded-xl border border-light-border bg-white p-6">
                            <div className="space-y-4 mb-6">
                                <label className="flex items-center gap-3 rounded-lg border border-light-border p-4 cursor-pointer hover:border-burgundy transition-colors">
                                    <input type="radio" name="payment" defaultChecked className="accent-burgundy" />
                                    <span className="text-sm font-medium text-charcoal">Cash on Delivery (COD)</span>
                                </label>
                                <label className="flex items-center gap-3 rounded-lg border border-light-border p-4 cursor-pointer hover:border-burgundy transition-colors">
                                    <input type="radio" name="payment" className="accent-burgundy" />
                                    <span className="text-sm font-medium text-charcoal">Bank Transfer</span>
                                </label>
                            </div>

                            {/* Order Notes */}
                            <div className="mb-6">
                                <label className="block text-sm font-medium text-charcoal mb-1">Order Notes <span className="text-warm-gray font-normal">(optional)</span></label>
                                <textarea
                                    id="order-notes"
                                    value={orderNotes}
                                    onChange={e => setOrderNotes(e.target.value.slice(0, 200))}
                                    maxLength={200}
                                    rows={3}
                                    placeholder="Any special instructions for your order..."
                                    className="w-full rounded-lg border border-light-border px-4 py-2.5 text-sm focus:border-burgundy focus:outline-none resize-none"
                                />
                                <p className="mt-1 text-xs text-warm-gray text-right">{orderNotes.length}/200</p>
                            </div>

                            {/* Order Summary */}
                            <div className="border-t border-light-border pt-4 space-y-2 text-sm">
                                {/* Show item details for Buy Now */}
                                {isBuyNow && buyNowItem && (
                                    <div className="flex items-center gap-3 mb-3 pb-3 border-b border-light-border">
                                        {buyNowItem.image_url && (
                                            <img src={buyNowItem.image_url} alt={buyNowItem.product_name} className="w-12 h-12 object-cover rounded-lg" />
                                        )}
                                        <div className="flex-1">
                                            <p className="text-sm font-medium text-charcoal">{buyNowItem.product_name}</p>
                                            {buyNowItem.size_label && <p className="text-xs text-warm-gray">{buyNowItem.size_label}</p>}
                                            <p className="text-xs text-warm-gray">Qty: {buyNowItem.quantity}</p>
                                        </div>
                                        <p className="text-sm font-semibold">{formatVND(buyNowItem.unit_price * buyNowItem.quantity)}</p>
                                    </div>
                                )}
                                <div className="flex justify-between">
                                    <span className="text-warm-gray">Subtotal ({checkoutItems.length} {checkoutItems.length === 1 ? 'item' : 'items'})</span>
                                    <span>{formatVND(baseSubtotal)}</span>
                                </div>
                                {totalTaxes > 0 && (
                                    <div className="flex justify-between">
                                        <span className="text-warm-gray">Taxes (VAT & Excise)</span>
                                        <span className="text-charcoal">{formatVND(totalTaxes)}</span>
                                    </div>
                                )}
                                <div className="flex justify-between">
                                    <span className="text-warm-gray">Shipping</span>
                                    <span>{shippingCost === 0 ? 'Free' : formatVND(shippingCost)}</span>
                                </div>
                                {!isBuyNow && couponDiscount > 0 && (
                                    <div className="flex justify-between text-green-600">
                                        <span>Coupon ({couponCode})</span>
                                        <span>-{formatVND(couponDiscount)}</span>
                                    </div>
                                )}
                                <div className="flex justify-between font-serif text-lg font-bold text-burgundy pt-2 border-t border-light-border mt-2">
                                    <span>Total</span><span>{formatVND(grandTotal)}</span>
                                </div>
                            </div>

                            {/* Terms and Conditions Notice */}
                            <div className="mt-8 mb-4 p-4 rounded-lg bg-cream border border-light-border">
                                <p className="text-xs text-warm-gray leading-relaxed text-center">
                                    By placing your order, you confirm that you are of legal drinking age in your state and agree to our Terms & Conditions, Privacy Policy, Refund Policy, and applicable state alcohol laws. Valid government ID verification will be required at delivery.
                                </p>
                            </div>

                            <div className="mt-2 flex gap-3">
                                <button
                                    onClick={() => setStep(1)}
                                    className="rounded-lg border border-light-border px-6 py-3 text-sm font-medium text-charcoal hover:bg-cream transition-colors"
                                >
                                    Back
                                </button>
                                <button
                                    onClick={handlePlaceOrder}
                                    disabled={placing}
                                    className="flex-1 rounded-lg bg-burgundy py-3 text-sm font-semibold text-white hover:bg-burgundy-dark transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                                >
                                    {placing ? (
                                        <><Loader2 className="h-4 w-4 animate-spin" /> Placing Order...</>
                                    ) : (
                                        `Place Order — ${formatVND(grandTotal)}`
                                    )}
                                </button>
                            </div>
                        </div>
                    </div>
                )}
            </div>

            {/* Age Verification Modal */}
            {showAgeModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
                    <div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl" style={{ animation: 'slideUp 0.3s ease-out' }}>
                        <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-cream-dark">
                            <span className="font-serif text-2xl font-bold text-burgundy">18+</span>
                        </div>
                        <h2 className="text-center font-serif text-2xl font-bold text-charcoal mb-2">Age Verification Required</h2>
                        <p className="text-center text-sm text-warm-gray mb-6">
                            You must be at least 18 years old to purchase alcohol. Please enter your date of birth to continue checkout.
                        </p>

                        <div className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-charcoal mb-1">Date of Birth</label>
                                <input
                                    type="date"
                                    value={dob}
                                    onChange={(e) => setDob(e.target.value)}
                                    className="w-full rounded-lg border border-light-border px-4 py-3 text-sm focus:border-burgundy focus:outline-none"
                                    max={new Date().toISOString().split('T')[0]}
                                />
                            </div>

                            <div className="flex gap-3 pt-2">
                                <button
                                    onClick={() => setShowAgeModal(false)}
                                    className="flex-1 rounded-lg border border-light-border py-3 text-sm font-medium text-charcoal hover:bg-cream transition-colors"
                                    disabled={verifyingAge}
                                >
                                    Cancel
                                </button>
                                <button
                                    onClick={handleVerifyAge}
                                    disabled={verifyingAge || !dob}
                                    className="flex-1 rounded-lg bg-burgundy py-3 text-sm font-semibold text-white hover:bg-burgundy-dark transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
                                >
                                    {verifyingAge ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Verify & Place Order'}
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import toast from 'react-hot-toast';
import { forgotPassword } from '@/lib/api';
import { ArrowLeft, Mail } from 'lucide-react';

export default function ForgotPasswordPage() {
    const router = useRouter();
    const [loading, setLoading] = useState(false);
    const [email, setEmail] = useState('');
    const [submitted, setSubmitted] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!email) {
            toast.error('Please enter your email address');
            return;
        }

        setLoading(true);

        try {
            const result = await forgotPassword(email);
            if (result?.success) {
                setSubmitted(true);
            } else {
                toast.error(result?.error || result?.message || 'Something went wrong');
            }
        } catch (error) {
            console.error('Password reset request error:', error);
            toast.error('Server error. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="min-h-screen bg-cream flex flex-col items-center justify-center px-4 py-12">
            <div className="w-full max-w-md">

                <Link href="/login" className="inline-flex items-center gap-2 mb-8 text-sm font-medium text-warm-gray hover:text-burgundy transition-colors">
                    <ArrowLeft className="w-4 h-4" />
                    Back to login
                </Link>

                <div className="text-center mb-8">
                    <div className="w-16 h-16 mx-auto mb-6 rounded-full bg-burgundy/10 flex items-center justify-center">
                        <Mail className="w-8 h-8 text-burgundy" />
                    </div>
                    <h1 className="font-serif text-3xl font-bold text-charcoal">
                        Forgot Password
                    </h1>
                    <p className="mt-2 text-sm text-warm-gray">
                        {submitted
                            ? "Check your email for the reset link"
                            : "Enter your email and we'll send you a link to reset your password."}
                    </p>
                </div>

                {submitted ? (
                    <div className="rounded-2xl border border-light-border bg-white p-8 shadow-sm text-center">
                        <p className="text-sm text-charcoal mb-6">
                            We've sent an email to <strong className="font-semibold">{email}</strong> with a link to reset your password. It may take a few minutes to arrive.
                        </p>
                        <button
                            onClick={() => router.push('/login')}
                            className="w-full rounded-lg bg-charcoal py-3 text-sm font-semibold text-white transition-all hover:bg-gray-800"
                        >
                            Return to Login
                        </button>
                    </div>
                ) : (
                    <form
                        onSubmit={handleSubmit}
                        className="rounded-2xl border border-light-border bg-white p-8 shadow-sm"
                    >
                        <div className="mb-6">
                            <label className="block text-sm font-medium text-charcoal mb-1">
                                Email Address
                            </label>
                            <input
                                type="email"
                                value={email}
                                onChange={e => setEmail(e.target.value)}
                                className="w-full rounded-lg border border-light-border px-4 py-2.5 text-sm focus:border-burgundy focus:outline-none focus:ring-1 focus:ring-burgundy"
                                placeholder="you@example.com"
                                required
                            />
                        </div>

                        <button
                            type="submit"
                            disabled={loading || !email}
                            className="w-full rounded-lg bg-burgundy py-3 text-sm font-semibold text-white transition-all hover:bg-burgundy-dark disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            {loading ? 'Sending...' : 'Send Reset Link'}
                        </button>
                    </form>
                )}
            </div>
        </div>
    );
}

import Navbar from "@/components/Navbar";
import Footer from "@/components/Footer";

async function getPrivacyPolicy() {
    try {
        const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL || 'http://127.0.0.1:5000'}/api/gdpr/policy/active`, { cache: 'no-store' });
        if (!res.ok) return null;
        const data = await res.json();
        return data.data; // { version, content, published_at }
    } catch {
        return null; // fallback
    }
}

export default async function PrivacyPolicyPage() {
    const policy = await getPrivacyPolicy();

    return (
        <div className="min-h-screen bg-cream flex flex-col">
            <div className="flex-1 max-w-4xl mx-auto px-4 py-16 w-full">
                <div className="bg-white rounded-2xl shadow-sm border border-light-border p-8 md:p-12">
                    <h1 className="font-serif text-3xl font-bold text-charcoal mb-4">Privacy & Cookie Policy</h1>

                    {policy ? (
                        <>
                            <div className="flex items-center gap-4 text-sm text-warm-gray mb-8 border-b border-light-border pb-6">
                                <span>Version: {policy.version}</span>
                                <span>|</span>
                                <span>Last Updated: {new Date(policy.published_at).toLocaleDateString()}</span>
                            </div>

                            <div
                                className="prose prose-emerald prose-a:text-burgundy max-w-none text-charcoal"
                                dangerouslySetInnerHTML={{ __html: policy.content.replace(/\n/g, '<br/>') }}
                            />
                        </>
                    ) : (
                        <div className="text-center py-16 text-warm-gray">
                            <p>Unable to load the current privacy policy. Please contact support.</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

'use client';

