import { SkeletonLine } from '@/components/Skeleton';
import { Heart, ShoppingCart, Minus, Plus, Star, Truck, RotateCcw, ChevronRight, AlertTriangle, Sparkles, Info } from 'lucide-react';
import ReviewSection from '@/components/reviews/ReviewSection';
import ProductImageGallery from '@/components/gallery/ProductImageGallery';
import toast from 'react-hot-toast';
import { useRouter, useSearchParams } from 'next/navigation';
import { useRecentlyViewed } from '@/hooks/useRecentlyViewed';
import RecentlyViewedProducts from '@/components/RecentlyViewedProducts';

interface Props {
    params: Promise<{ id: string }>;
}

export default function ProductDetailPage({ params }: Props) {
    const { id } = use(params);

    const [product, setProduct] = useState<ProductWithDetails | null>(null);
    const [relatedProducts, setRelatedProducts] = useState<Product[]>([]);
    const [crossSellProducts, setCrossSellProducts] = useState<Product[]>([]);
    const [loading, setLoading] = useState(true);
    const [quantity, setQuantity] = useState(1);


    // ✅ Variant state
    const [variants, setVariants] = useState<any[]>([]);
    const [selectedVariant, setSelectedVariant] = useState<any>(null);
    const [selectedSize, setSelectedSize] = useState<string | null>(null);
    const [selectedPack, setSelectedPack] = useState<number | null>(null);
    const [localQty, setLocalQty] = useState<number | null>(null);
    const router = useRouter();
    const searchParams = useSearchParams();
    const { isAuthenticated } = useAuth();

    useEffect(() => {
        setLocalQty(null);
    }, [selectedVariant?.variant_id]);

    const { addItem, items, updateQuantity, removeItem, loading: cartLoading } = useCart();
    const { isInWishlist, toggleItem } = useWishlist();
    const { addProduct: trackRecentlyViewed } = useRecentlyViewed();

    useEffect(() => {
        const load = async () => {
            setLoading(true);

            let data = await getProductDetails(id);
            if (!data) {
                const simple = await getProduct(id);
                if (simple) data = simple as ProductWithDetails;
            }

            setProduct(data);

            // ✅ store variants with size/pack defaults
            if (data?.variants?.length) {
                const vs = data.variants;
                setVariants(vs);

                // Pick the default variant (is_default=true), falling back to first
                const defaultV = vs.find((v: any) => v.is_default === true) || vs[0];
                const firstSize = defaultV?.size_label ?? null;
                const firstPack = defaultV?.pack_quantity ?? 1;
                setSelectedSize(firstSize);
                setSelectedPack(firstPack);
                setSelectedVariant(defaultV);
            }

            // related products (similar)
            const similar = await getRelatedProducts(id, 'similar', 4);
            setRelatedProducts(similar);

            // cross-sell products (perfect pairings)
            const crossSells = await getRelatedProducts(id, 'pairs_with', 4);
            setCrossSellProducts(crossSells);

            setLoading(false);

            // Track this product as recently viewed
            if (data) trackRecentlyViewed(id);
        };

        load();
    }, [id]);

    // ── Express checkout: auto-trigger Buy Now after login redirect ──
    useEffect(() => {
        if (searchParams.get('buyNow') === 'true' && isAuthenticated && product && !loading) {
            // Clear the buyNow param from URL without reload
            const url = new URL(window.location.href);
            url.searchParams.delete('buyNow');
            window.history.replaceState({}, '', url.pathname);

            // Store the Buy Now item and redirect to checkout
            const timer = setTimeout(() => {
                const buyNowItem = {
                    product_id: product.product_id,
                    product_name: product.product_name,
                    variant_id: selectedVariant?.variant_id || null,
                    size_label: selectedVariant?.size_label || '',
                    quantity: displayQuantity ?? 1,
                    unit_price: Number(selectedVariant?.price ?? product.price ?? 0),
                    image_url: (product as any).thumbnail_url || '',
                };
                sessionStorage.setItem('ksp_buy_now_item', JSON.stringify(buyNowItem));
                router.push('/checkout?buyNow=true');
            }, 300);
            return () => clearTimeout(timer);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [searchParams, isAuthenticated, product, loading]);

    if (loading) {
        return (
            <div className="min-h-screen bg-cream">
                <div className="mx-auto max-w-7xl px-4 py-8">
                    <div className="grid gap-10 lg:grid-cols-2">
                        <div className="aspect-square rounded-2xl animate-shimmer" />
                        <div className="space-y-4">
                            <SkeletonLine className="h-6 w-1/3" />
                            <SkeletonLine className="h-8 w-2/3" />
                            <SkeletonLine className="h-6 w-1/4" />
                            <SkeletonLine className="h-20 w-full" />
                            <SkeletonLine className="h-12 w-full" />
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    if (!product) return null;

    const wishlisted = isInWishlist(product.product_id);

    const displayPrice = selectedVariant?.price ?? product.price ??
        Math.floor(Math.random() * 500000 + 100000);

    const isOnSale = selectedVariant?.is_on_sale ?? product.is_on_sale ?? false;
    const originalPrice = selectedVariant?.original_price ?? product.original_price ?? displayPrice;
    const discountPercent = selectedVariant?.discount_percentage ?? product.discount_percentage ?? 0;

    // Stock availability
    const stockQty = selectedVariant?.stock_quantity ?? product.stock_quantity ?? null;
    const isOutOfStock = stockQty !== null && stockQty <= 0;
    const maxQty = stockQty !== null && stockQty > 0 ? stockQty : 99;

    // Scheduled availability
    const isComingSoon = product.is_coming_soon ?? false;
    const isExpired = product.is_availability_expired ?? false;
    const isUnavailable = isComingSoon || isExpired || isOutOfStock;



    const cartItem = product ? items.find(i =>
        i.product_id === product.product_id &&
        (selectedVariant?.variant_id ? i.variant_id === selectedVariant.variant_id : true)
    ) : undefined;

    const displayQuantity = localQty !== null ? localQty : (cartItem ? cartItem.quantity : quantity);
    const isModified = cartItem ? (displayQuantity !== cartItem.quantity) : true;

    const handleMinus = async () => {
        const current = displayQuantity;
        if (cartItem && current === cartItem.quantity) {
            // Dynamic decrease directly in cart
            if (cartItem.quantity > 1) {
                setLocalQty(null);
                await updateQuantity(cartItem.cart_item_id, cartItem.quantity - 1);
            } else {
                setLocalQty(null);
                await removeItem(cartItem.cart_item_id);
            }
        } else {
            // Local decrease
            const next = Math.max(1, current - 1);
            if (cartItem && next === cartItem.quantity) {
                setLocalQty(null); // Re-synced
            } else {
                setLocalQty(next);
            }
            if (!cartItem) setQuantity(next); // Fallback for pure local state
        }
    };

    const handlePlus = async () => {
        const current = displayQuantity;
        const next = Math.min(maxQty, current + 1);
        setLocalQty(next);
        if (!cartItem) setQuantity(next); // Fallback for pure local state
    };

    const handleAddToCart = async () => {
        if (!product || isOutOfStock) return;

        if (cartItem) {
            if (!isModified) return; // do nothing if not modified

            await updateQuantity(cartItem.cart_item_id, displayQuantity);
            toast.success(`Cart updated to ${displayQuantity} x ${product.product_name}!`);
            setLocalQty(null);
        } else {
            await addItem(
                product.product_id,
                selectedVariant?.variant_id || null,
                displayQuantity
            );
            toast.success(`Added ${displayQuantity} x ${product.product_name} to cart!`);
            setLocalQty(null);
        }
    };

    const handleBuyNow = async () => {
        if (!product || isUnavailable) return;

        // If user is NOT signed in, redirect to login with a return URL
        if (!isAuthenticated) {
            const returnUrl = `/products/${product.product_id}?buyNow=true`;
            router.push(`/login?redirect=${encodeURIComponent(returnUrl)}`);
            return;
        }

        // User IS signed in — store the single item and go straight to checkout
        const buyNowItem = {
            product_id: product.product_id,
            product_name: product.product_name,
            variant_id: selectedVariant?.variant_id || null,
            size_label: selectedVariant?.size_label || '',
            quantity: displayQuantity,
            unit_price: Number(selectedVariant?.price ?? product.price ?? 0),
            image_url: (product as any).thumbnail_url || '',
        };
        sessionStorage.setItem('ksp_buy_now_item', JSON.stringify(buyNowItem));
        router.push('/checkout?buyNow=true');
    };

    return (
        <div className="min-h-screen bg-cream">
            {/* Breadcrumb */}
            <div className="border-b border-light-border bg-white">
                <div className="mx-auto max-w-7xl px-4 py-3">
                    <nav className="flex items-center gap-2 text-sm text-warm-gray">
                        <Link href="/">Home</Link>
                        <ChevronRight className="h-3 w-3" />
                        <Link href="/products">Shop</Link>
                        <ChevronRight className="h-3 w-3" />
                        <span className="text-charcoal font-medium">{product.product_name}</span>
                    </nav>
                </div>
            </div>

            <div className="mx-auto max-w-7xl px-4 py-10">
                <div className="grid gap-10 lg:grid-cols-2">
                    {/* IMAGE GALLERY */}
                    <div>
                        <ProductImageGallery
                            assets={product.assets}
                            productName={product.product_name}
                            variantId={selectedVariant?.variant_id}
                            fallbackImages={product.images}
                        />
                    </div>

                    {/* DETAILS */}
                    <div className="space-y-6">
                        <h1 className="font-serif text-3xl font-bold">
                            {product.product_name}
                        </h1>

                        {product.brand && (
                            <p className="text-warm-gray">{product.brand}</p>
                        )}

                        {/* Product metadata tags */}
                        <div className="flex flex-wrap gap-x-5 gap-y-1.5 text-sm">
                            {product.category && (
                                <span className="flex items-center gap-1.5">
                                    <span className="text-warm-gray/60 font-medium">Category:</span>
                                    <span className="text-charcoal">{product.category}</span>
                                </span>
                            )}
                            {product.country_of_origin && (
                                <span className="flex items-center gap-1.5">
                                    <span className="text-warm-gray/60 font-medium">Country of Origin:</span>
                                    <span className="text-burgundy/80 font-semibold">{product.country_of_origin}</span>
                                </span>
                            )}
                            <span className="flex items-center gap-1.5">
                                <span className="text-warm-gray/60 font-medium">Alcohol:</span>
                                <span className="text-burgundy/80 font-semibold">
                                    {(() => {
                                        const abv = product.alcohol_percentage ?? selectedVariant?.alcohol_percentage ?? null;
                                        return abv != null ? `${abv}% ABV` : '—';
                                    })()}
                                </span>
                            </span>
                        </div>

                        {/* PRICE */}
                        <div className="flex items-center gap-3">
                            <p className="text-3xl font-bold text-burgundy">
                                {formatVND(displayPrice)}
                            </p>
                            {isOnSale && originalPrice && (
                                <>
                                    <p className="text-lg text-warm-gray/60 line-through decoration-burgundy/40">
                                        {formatVND(originalPrice)}
                                    </p>
                                    <span className="bg-red-50 text-red-600 text-xs font-bold px-2 py-1 rounded border border-red-200 uppercase tracking-wide">
                                        {discountPercent}% OFF
                                    </span>
                                </>
                            )}
                        </div>

                        {/* ✅ VARIANT SELECTORS: Size + Pack */}
                        {variants.length > 0 && (() => {
                            const uniqueSizes = [...new Set(variants.map((v: any) => v.size_label as string))].filter(Boolean);
                            const uniquePacks = [...new Set(variants.map((v: any) => (v.pack_quantity ?? 1) as number))].sort((a, b) => a - b);

                            const handleSizeSelect = (size: string) => {
                                setSelectedSize(size);
                                const match = variants.find((v: any) => v.size_label === size && (v.pack_quantity ?? 1) === (selectedPack ?? 1));
                                if (match) setSelectedVariant(match);
                                else {
                                    // fallback: find any variant with this size
                                    const fallback = variants.find((v: any) => v.size_label === size);
                                    if (fallback) {
                                        setSelectedPack(fallback.pack_quantity ?? 1);
                                        setSelectedVariant(fallback);
                                    }
                                }
                            };

                            const handlePackSelect = (pack: number) => {
                                setSelectedPack(pack);
                                const match = variants.find((v: any) => v.size_label === selectedSize && (v.pack_quantity ?? 1) === pack);
                                if (match) setSelectedVariant(match);
                                else {
                                    // fallback: find any variant with this pack
                                    const fallback = variants.find((v: any) => (v.pack_quantity ?? 1) === pack);
                                    if (fallback) {
                                        setSelectedSize(fallback.size_label);
                                        setSelectedVariant(fallback);
                                    }
                                }
                            };

                            const hasCombo = (size: string, pack: number) =>
                                variants.some((v: any) => v.size_label === size && (v.pack_quantity ?? 1) === pack);

                            return (
                                <div className="space-y-4">
                                    {/* Choose Size */}
                                    {uniqueSizes.length > 0 && (
                                        <div>
                                            <p className="text-sm font-semibold mb-2">Choose Size:</p>
                                            <div className="flex gap-2 flex-wrap">
                                                {uniqueSizes.map((size) => (
                                                    <button
                                                        key={size}
                                                        onClick={() => handleSizeSelect(size)}
                                                        className={`px-4 py-2 rounded-lg border text-sm font-medium transition
                                                            ${selectedSize === size
                                                                ? 'bg-burgundy text-white border-burgundy'
                                                                : 'border-light-border hover:border-burgundy'
                                                            }`}
                                                    >
                                                        {size}
                                                    </button>
                                                ))}
                                            </div>
                                        </div>
                                    )}

                                    {/* Choose Pack — only show if more than 1 unique pack */}
                                    {uniquePacks.length > 1 && (
                                        <div>
                                            <p className="text-sm font-semibold mb-2">Choose Pack:</p>
                                            <div className="flex gap-2 flex-wrap">
                                                {uniquePacks.map((pack) => {
                                                    const available = hasCombo(selectedSize!, pack);
                                                    return (
                                                        <button
                                                            key={pack}
                                                            onClick={() => available && handlePackSelect(pack)}
                                                            disabled={!available}
                                                            className={`px-4 py-2 rounded-lg border text-sm font-medium transition
                                                                ${selectedPack === pack
                                                                    ? 'bg-burgundy text-white border-burgundy'
                                                                    : available
                                                                        ? 'border-light-border hover:border-burgundy'
                                                                        : 'border-light-border opacity-40 cursor-not-allowed'
                                                                }`}
                                                        >
                                                            Pack of {pack}
                                                        </button>
                                                    );
                                                })}
                                            </div>
                                        </div>
                                    )}
                                </div>
                            );
                        })()}

                        {/* STOCK AVAILABILITY BADGE */}
                        {isComingSoon ? (
                            <div className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold bg-purple-50 text-purple-700 border border-purple-200">
                                🕒 Coming Soon
                            </div>
                        ) : isExpired ? (
                            <div className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold bg-red-50 text-red-600 border border-red-200">
                                <AlertTriangle size={12} /> Availability Ended
                            </div>
                        ) : stockQty !== null && (
                            <div className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold ${isOutOfStock
                                ? 'bg-red-50 text-red-600 border border-red-200'
                                : stockQty <= 5
                                    ? 'bg-amber-50 text-amber-600 border border-amber-200'
                                    : 'bg-emerald-50 text-emerald-600 border border-emerald-200'
                                }`}>
                                {isOutOfStock ? (
                                    <><AlertTriangle size={12} /> Out of Stock</>
                                ) : stockQty <= 5 ? (
                                    <><AlertTriangle size={12} /> Only {stockQty} left</>
                                ) : (
                                    <>✓ In Stock</>
                                )}
                            </div>
                        )}

                        {/* QUANTITY + CART */}
                        <div className="flex flex-col gap-3">
                            <div className="flex gap-4">
                                <div className={`flex border rounded-lg ${cartLoading ? 'opacity-50 pointer-events-none' : ''}`}>
                                    <button onClick={handleMinus} className="px-3 hover:bg-black/5 rounded-l-lg transition-colors" disabled={isUnavailable || (displayQuantity <= 1 && !cartItem)}>
                                        <Minus size={16} />
                                    </button>
                                    <span className="px-4 py-2 flex items-center justify-center min-w-[3rem] font-medium text-charcoal">{displayQuantity}</span>
                                    <button onClick={handlePlus} className="px-3 hover:bg-black/5 rounded-r-lg transition-colors" disabled={isUnavailable || displayQuantity >= maxQty}>
                                        <Plus size={16} />
                                    </button>
                                </div>

                                <button
                                    onClick={handleAddToCart}
                                    disabled={isUnavailable || (!isModified && !!cartItem) || cartLoading}
                                    className={`flex-1 rounded-lg py-3 flex justify-center items-center gap-2 transition-all font-semibold ${isUnavailable
                                        ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                                        : cartItem && !isModified
                                            ? 'bg-emerald-600 text-white cursor-default shadow-md shadow-emerald-600/20'
                                            : 'bg-emerald-600 text-white hover:bg-emerald-700 shadow-md shadow-emerald-600/20'
                                        }`}
                                >
                                    <ShoppingCart size={18} />
                                    {isComingSoon ? 'Coming Soon' : isExpired ? 'No Longer Available' : isOutOfStock ? 'Out of Stock' : cartItem ? (isModified ? 'Update Cart' : 'In Cart') : 'Add to Cart'}
                                </button>

                                <button
                                    onClick={() => toggleItem(product)}
                                    className={`border rounded-lg px-3 flex items-center justify-center transition-colors ${wishlisted ? 'border-burgundy bg-burgundy/5' : 'hover:bg-black/5'}`}
                                >
                                    <Heart className={wishlisted ? "fill-current text-burgundy" : "text-charcoal"} size={20} />
                                </button>
                            </div>

                            <button
                                onClick={handleBuyNow}
                                disabled={isUnavailable || cartLoading}
                                className={`w-full rounded-lg py-3 flex justify-center items-center font-semibold transition-all shadow-md ${isUnavailable
                                    ? 'bg-gray-200 text-gray-400 cursor-not-allowed shadow-none'
                                    : 'bg-burgundy text-white hover:bg-burgundy/90 shadow-burgundy/20 hover:shadow-lg hover:-translate-y-0.5'
                                    }`}
                            >
                                Buy Now
                            </button>
                        </div>

                        {/* SHIPPING */}
                        <div className="grid grid-cols-2 gap-3">
                            <div className="flex items-center gap-2 text-xs">
                                <Truck size={16} /> Free shipping over $50
                            </div>
                            <div className="flex items-center gap-2 text-xs">
                                <RotateCcw size={16} /> 7-day returns
                            </div>
                        </div>
                    </div>
                </div>

                {/* INTENDED USE & DESCRIPTION */}
                {(product.description || product.intended_use) && (
                    <section className="mt-16 border-t border-neutral-100 pt-10">
                        <div className="space-y-12">
                            {product.intended_use && (
                                <div>
                                    <div className="flex items-center gap-3 mb-8">
                                        <Info className="h-6 w-6 text-[#C5A46D] flex-shrink-0" strokeWidth={1} />
                                        <h2 className="font-serif text-2xl font-bold text-neutral-800">Intended Use</h2>
                                    </div>
                                    <p className="text-[15px] text-neutral-600 leading-[1.85] whitespace-pre-line pl-9">
                                        {product.intended_use}
                                    </p>
                                </div>
                            )}
                            {product.description && (
                                <div>
                                    <div className="flex items-center gap-3 mb-8">
                                        <Info className="h-6 w-6 text-[#C5A46D] flex-shrink-0" strokeWidth={1} />
                                        <h2 className="font-serif text-2xl font-bold text-neutral-800">Description</h2>
                                    </div>
                                    <p className="text-[15px] text-neutral-600 leading-[1.85] whitespace-pre-line pl-9">
                                        {product.description}
                                    </p>
                                </div>
                            )}
                        </div>
                    </section>
                )}

                {/* REVIEWS SECTION */}
                <ReviewSection productId={id} />

                {/* PERFECT PAIRINGS */}
                {crossSellProducts.length > 0 && (
                    <div className="mt-16 border-t border-light-border pt-16">
                        <div className="flex items-center justify-between mb-8">
                            <h2 className="font-serif text-3xl font-bold text-charcoal flex items-center gap-3">
                                <Sparkles className="h-6 w-6 text-burgundy" />
                                Perfect Pairings
                            </h2>
                        </div>
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                            {crossSellProducts.map(p => (
                                <ProductCard key={p.product_id} product={p} />
                            ))}
                        </div>
                    </div>
                )}

                {/* YOU MAY ALSO LIKE */}
                {relatedProducts.length > 0 && (
                    <div className="mt-16 border-t border-light-border pt-16">
                        <div className="flex items-center justify-between mb-8">
                            <h2 className="font-serif text-3xl font-bold text-charcoal">
                                You May Also Like
                            </h2>
                        </div>
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                            {relatedProducts.map(p => (
                                <ProductCard key={p.product_id} product={p} />
                            ))}
                        </div>
                    </div>
                )}

                {/* RECENTLY VIEWED */}
                <RecentlyViewedProducts currentProductId={id} />
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, Suspense, useCallback } from 'react';
import { useSearchParams } from 'next/navigation';
import { getProducts, getCategories, formatVND, getFilterOptions, getBestSellers, getNewArrivals, getFilteredProducts, searchProducts } from '@/lib/api';
import { FilteredProduct, FilterMeta } from '@/types';
import ProductCard from '@/components/ProductCard';
import { SkeletonProductGrid } from '@/components/Skeleton';
import { SlidersHorizontal, Search, ChevronLeft, ChevronRight, X, Wine, Loader2 } from 'lucide-react';
import { useFilters } from '@/hooks/useFilters';
import { FILTER_CONFIGS, SORT_OPTIONS } from '@/lib/filterConfig';

// Filter components
import FilterSection from '@/components/filters/FilterSection';
import CheckboxGroup from '@/components/filters/CheckboxGroup';
import RangeSlider from '@/components/filters/RangeSlider';
import ToggleSwitch from '@/components/filters/ToggleSwitch';
import SortDropdown from '@/components/filters/SortDropdown';
import ActiveFilterChips from '@/components/filters/ActiveFilterChips';
import CountryDropdown from '@/components/filters/CountryDropdown';
import { COUNTRIES } from '@/lib/countries';

const ITEMS_PER_PAGE = 12;

function ProductsContent() {
    const {
        filters,
        activeChips,
        setSearch,
        setBrands,
        setCountry,
        setRatings,
        setPriceRange,
        setAlcoholRange,
        setInStock,
        setBestSellers,
        setNewArrivals,
        setSort,
        removeFilter,
        clearAll,
    } = useFilters();

    const searchParams = useSearchParams();
    const currentPage = Number(searchParams.get('page') || '1');

    const [products, setProducts] = useState<FilteredProduct[]>([]);
    const [meta, setMeta] = useState<FilterMeta | null>(null);
    const [loading, setLoading] = useState(true);
    const [mobileOpen, setMobileOpen] = useState(false);

    // Dynamic filter options (loaded from API)
    const [brandOptions, setBrandOptions] = useState<string[]>([]);
    const [countryOptions, setCountryOptions] = useState<string[]>([]);
    const [priceMax, setPriceMax] = useState<number>(5000);

    // Full 197-country list — merged with any countries already in the DB
    const displayCountryOptions = Array.from(
        new Set([...COUNTRIES.map(c => c.name), ...countryOptions])
    ).sort();

    // Load dynamic filter options once
    useEffect(() => {
        getFilterOptions().then(opts => {
            setBrandOptions(opts.brands);
            setCountryOptions(opts.countries);
            if (opts.maxPrice) setPriceMax(opts.maxPrice);
        });
    }, []);

    // Fetch products from backend filter endpoint whenever filters change
    useEffect(() => {
        const fetchProducts = async () => {
            setLoading(true);

            if (filters.search) {
                // Search uses a separate endpoint
                const data = await searchProducts(filters.search);
                setProducts(data as FilteredProduct[]);
                setMeta(null);
                setLoading(false);
                return;
            }

            // ── Best Sellers toggle: use dedicated endpoint ──
            if (filters.bestSellers) {
                const bsParams: Record<string, any> = {
                    limit: ITEMS_PER_PAGE,
                    page: currentPage,
                };
                if (filters.category) bsParams.category = filters.category;
                if (filters.country) bsParams.country = filters.country;
                if (filters.priceRange[0] !== 0) bsParams.minPrice = filters.priceRange[0];
                if (filters.priceRange[1] !== Infinity) bsParams.maxPrice = filters.priceRange[1];

                const result = await getBestSellers(bsParams);
                setProducts(result.data);
                setMeta(result.meta);
                setLoading(false);
                return;
            }

            // ── New Arrivals toggle: use dedicated endpoint ──
            if (filters.newArrivals) {
                const naParams: Record<string, any> = {
                    limit: ITEMS_PER_PAGE,
                };
                if (filters.category) naParams.category = filters.category;
                if (filters.country) naParams.region = filters.country;
                if (filters.brands.length === 1) naParams.brand = filters.brands[0];
                if (filters.priceRange[0] !== 0) naParams.min_price = filters.priceRange[0];
                if (filters.priceRange[1] !== Infinity) naParams.max_price = filters.priceRange[1];
                if (filters.inStock) naParams.in_stock = true;

                const result = await getNewArrivals(naParams);
                setProducts(result.data);
                setMeta(result.meta);
                setLoading(false);
                return;
            }

            // Build filter params for GET /api/products/filter
            const priceConfig = FILTER_CONFIGS.find(f => f.key === 'price');
            const alcConfig = FILTER_CONFIGS.find(f => f.key === 'alcohol');

            const params: Record<string, unknown> = {
                page: currentPage,
                limit: ITEMS_PER_PAGE,
            };

            // Sort
            if (filters.sort) params.sort = filters.sort;

            // Category / Subcategory
            if (filters.category) params.category = filters.category;
            if (filters.sub_category) params.sub_category = filters.sub_category;

            // Brand (comma-separated list → backend takes single brand ILIKE)
            if (filters.brands.length === 1) params.brand = filters.brands[0];

            // Price range
            const pMin = 0;
            if (filters.priceRange[0] !== pMin) params.min_price = filters.priceRange[0];
            if (filters.priceRange[1] !== Infinity) params.max_price = filters.priceRange[1];

            // Alcohol % range
            const aMin = alcConfig?.min ?? 0;
            const aMax = alcConfig?.max ?? 100;
            if (filters.alcoholRange[0] !== aMin) params.min_abv = filters.alcoholRange[0];
            if (filters.alcoholRange[1] !== aMax) params.max_abv = filters.alcoholRange[1];

            // Country
            if (filters.country) params.country = filters.country;

            // Rating — extract numeric value from strings like '4★ & above'
            if (filters.ratings.length > 0) {
                const ratingValues = filters.ratings.map(r => parseInt(r)).filter(n => !isNaN(n));
                if (ratingValues.length > 0) params.min_rating = Math.min(...ratingValues);
            }

            // Availability
            if (filters.inStock) params.availability = 'in_stock';

            const result = await getFilteredProducts(params as any);
            setProducts(result.data);
            setMeta(result.meta);
            setLoading(false);
        };
        fetchProducts();
    }, [filters, currentPage]);

    const totalCount = meta?.total_count ?? products.length;
    const totalPages = meta?.total_pages ?? Math.ceil(products.length / ITEMS_PER_PAGE);

    // Close mobile drawer on escape
    useEffect(() => {
        const handleEsc = (e: KeyboardEvent) => {
            if (e.key === 'Escape') setMobileOpen(false);
        };
        document.addEventListener('keydown', handleEsc);
        return () => document.removeEventListener('keydown', handleEsc);
    }, []);

    // Lock body scroll when mobile drawer is open
    useEffect(() => {
        document.body.style.overflow = mobileOpen ? 'hidden' : '';
        return () => { document.body.style.overflow = ''; };
    }, [mobileOpen]);

    /* ─── Sidebar content (shared between desktop & mobile) ─── */
    const sidebarContent = (
        <div className="space-y-0">
            {/* Brands — dynamic from API */}
            {brandOptions.length > 0 && (
                <FilterSection title="Brand">
                    <CheckboxGroup
                        options={brandOptions}
                        selected={filters.brands}
                        onChange={setBrands}
                    />
                </FilterSection>
            )}

            {/* Price Range */}
            <FilterSection title="Price Range">
                <div className="mb-5 flex flex-wrap gap-2 text-xs">
                    <button
                        onClick={() => setPriceRange([0, 1000], priceMax)}
                        className={`rounded-full border px-3 py-1.5 transition-colors ${(filters.priceRange[0] === 0 && filters.priceRange[1] === 1000) ? 'bg-burgundy text-white border-burgundy shadow-sm' : 'border-light-border bg-white text-warm-gray hover:border-burgundy/50 hover:text-charcoal hover:bg-burgundy/5'}`}
                    >
                        Under $1,000
                    </button>
                    <button
                        onClick={() => setPriceRange([1000, 2500], priceMax)}
                        className={`rounded-full border px-3 py-1.5 transition-colors ${(filters.priceRange[0] === 1000 && filters.priceRange[1] === 2500) ? 'bg-burgundy text-white border-burgundy shadow-sm' : 'border-light-border bg-white text-warm-gray hover:border-burgundy/50 hover:text-charcoal hover:bg-burgundy/5'}`}
                    >
                        $1,000 – $2,500
                    </button>
                    <button
                        onClick={() => setPriceRange([2500, 5000], priceMax)}
                        className={`rounded-full border px-3 py-1.5 transition-colors ${(filters.priceRange[0] === 2500 && filters.priceRange[1] === 5000) ? 'bg-burgundy text-white border-burgundy shadow-sm' : 'border-light-border bg-white text-warm-gray hover:border-burgundy/50 hover:text-charcoal hover:bg-burgundy/5'}`}
                    >
                        $2,500 – $5,000
                    </button>
                    <button
                        onClick={() => setPriceRange([5000, Infinity], priceMax)}
                        className={`rounded-full border px-3 py-1.5 transition-colors ${(filters.priceRange[0] === 5000 && filters.priceRange[1] === Infinity) ? 'bg-burgundy text-white border-burgundy shadow-sm' : 'border-light-border bg-white text-warm-gray hover:border-burgundy/50 hover:text-charcoal hover:bg-burgundy/5'}`}
                    >
                        $5,000+
                    </button>
                </div>
                <RangeSlider
                    min={0}
                    max={priceMax}
                    step={priceMax <= 5000 ? 100 : (priceMax <= 20000 ? 500 : 1000)}
                    value={[filters.priceRange[0] ?? 0, filters.priceRange[1] === Infinity ? priceMax : filters.priceRange[1]]}
                    onChange={(val) => setPriceRange(val, priceMax)}
                    formatLabel={v => formatVND(v)}
                />
            </FilterSection>

            {/* Alcohol % Range */}
            <FilterSection title="Alcohol %" defaultOpen={false}>
                <RangeSlider
                    min={FILTER_CONFIGS.find(f => f.key === 'alcohol')?.min ?? 0}
                    max={FILTER_CONFIGS.find(f => f.key === 'alcohol')?.max ?? 100}
                    step={FILTER_CONFIGS.find(f => f.key === 'alcohol')?.step ?? 1}
                    value={filters.alcoholRange}
                    onChange={setAlcoholRange}
                    formatLabel={v => `${v}%`}
                />
            </FilterSection>

            {/* Country — single-select dropdown (always shown) */}
            <CountryDropdown
                options={displayCountryOptions}
                selected={filters.country}
                onChange={setCountry}
            />

            {/* Rating */}
            <FilterSection title="Rating" defaultOpen={false}>
                <CheckboxGroup
                    options={FILTER_CONFIGS.find(f => f.key === 'rating')?.staticOptions ?? []}
                    selected={filters.ratings}
                    onChange={setRatings}
                />
            </FilterSection>

            {/* Toggles */}
            <FilterSection title="Availability">
                <div className="space-y-3">
                    <ToggleSwitch
                        label="In Stock Only"
                        checked={filters.inStock}
                        onChange={setInStock}
                    />
                    <ToggleSwitch
                        label="Best Sellers"
                        checked={filters.bestSellers}
                        onChange={setBestSellers}
                    />
                    <ToggleSwitch
                        label="New Arrivals"
                        checked={filters.newArrivals}
                        onChange={setNewArrivals}
                    />
                </div>
            </FilterSection>

            {/* Clear All */}
            {activeChips.length > 0 && (
                <div className="pt-4 border-t border-light-border/60">
                    <button
                        onClick={clearAll}
                        className="w-full rounded-lg border border-burgundy/20 py-2.5 text-sm font-semibold text-burgundy hover:bg-burgundy/5 transition-colors"
                    >
                        Clear All Filters
                    </button>
                </div>
            )}
        </div>
    );

    return (
        <div className="min-h-screen bg-cream">
            {/* Header */}
            <div className="border-b border-light-border bg-white">
                <div className="mx-auto max-w-[1440px] px-4 sm:px-6 py-8">
                    <div>
                        <h1 className="font-serif text-3xl font-bold text-wine-gold tracking-tight">
                            Shop Wines
                        </h1>
                        <p className="mt-0.5 text-sm text-warm-gray">
                            Explore our curated collection of fine wines
                        </p>
                    </div>
                </div>
            </div>

            <div className="mx-auto max-w-[1440px] px-4 sm:px-6 py-8">
                {/* Mobile Filter Button */}
                <button
                    onClick={() => setMobileOpen(true)}
                    className="mb-5 flex items-center gap-2 rounded-lg border border-light-border bg-white px-4 py-2.5 text-sm font-medium text-charcoal shadow-sm hover:shadow-md transition-shadow lg:hidden"
                >
                    <SlidersHorizontal className="h-4 w-4 text-burgundy" />
                    Filters
                    {activeChips.length > 0 && (
                        <span className="ml-1 flex h-5 w-5 items-center justify-center rounded-full bg-burgundy text-[10px] font-bold text-white">
                            {activeChips.length}
                        </span>
                    )}
                </button>

                <div className="lg:grid lg:grid-cols-[280px_1fr] lg:gap-8">
                    {/* ─── Desktop Sidebar ─── */}
                    <aside className="hidden lg:block">
                        <div className="sticky top-6 rounded-xl border border-light-border bg-white px-5 py-4 shadow-sm">
                            <h2 className="font-serif text-base font-semibold text-charcoal mb-1">Filters</h2>
                            <p className="text-xs text-warm-gray mb-4 flex items-center gap-2">
                                <span className={`transition-opacity ${loading ? 'opacity-50' : 'opacity-100'}`}>
                                    {totalCount} wine{totalCount !== 1 ? 's' : ''} found
                                </span>
                                {loading && <Loader2 className="h-3 w-3 animate-spin text-burgundy" />}
                            </p>
                            {sidebarContent}
                        </div>
                    </aside>

                    {/* ─── Mobile Drawer ─── */}
                    {mobileOpen && (
                        <div className="fixed inset-0 z-50 lg:hidden">
                            {/* Backdrop */}
                            <div
                                className="absolute inset-0 bg-black/40 animate-overlay-fade-in"
                                onClick={() => setMobileOpen(false)}
                            />
                            {/* Drawer */}
                            <div className="absolute left-0 top-0 bottom-0 w-[320px] max-w-[85vw] bg-white shadow-2xl animate-slide-in-right overflow-y-auto">
                                <div className="flex items-center justify-between border-b border-light-border px-5 py-4">
                                    <h2 className="font-serif text-lg font-semibold text-charcoal">Filters</h2>
                                    <button
                                        onClick={() => setMobileOpen(false)}
                                        className="rounded-full p-1.5 hover:bg-cream transition-colors"
                                    >
                                        <X className="h-5 w-5 text-warm-gray" />
                                    </button>
                                </div>
                                <div className="px-5 py-4">
                                    {sidebarContent}
                                </div>
                            </div>
                        </div>
                    )}

                    {/* ─── Product Grid ─── */}
                    <div className="min-w-0">
                        {/* Sort bar + Active chips */}
                        <div className="mb-2 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
                            <p className="text-sm text-warm-gray flex items-center gap-2">
                                <span className={`transition-opacity ${loading ? 'opacity-50' : 'opacity-100'}`}>
                                    Showing <span className="font-semibold text-charcoal">{products.length}</span> of{' '}
                                    <span className="font-semibold text-charcoal">{totalCount}</span> wines
                                </span>
                                {loading && <Loader2 className="h-4 w-4 animate-spin text-burgundy" />}
                            </p>
                            <SortDropdown
                                value={filters.sort}
                                onChange={setSort}
                                options={SORT_OPTIONS}
                            />
                        </div>

                        <ActiveFilterChips
                            chips={activeChips}
                            onRemove={removeFilter}
                            onClearAll={clearAll}
                        />

                        {loading ? (
                            <SkeletonProductGrid count={12} />
                        ) : products.length > 0 ? (
                            <>
                                <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-3">
                                    {products.map((product, i) => (
                                        <div
                                            key={product.product_id}
                                            className="animate-fade-in-up"
                                            style={{ animationDelay: `${i * 50}ms`, animationFillMode: 'both' }}
                                        >
                                            <ProductCard product={product} />
                                        </div>
                                    ))}
                                </div>

                                {/* Pagination */}
                                {totalPages > 1 && (
                                    <div className="mt-12 flex items-center justify-center gap-2">
                                        <button
                                            onClick={() => {
                                                const params = new URLSearchParams(searchParams.toString());
                                                params.set('page', String(Math.max(1, currentPage - 1)));
                                                window.history.pushState(null, '', `?${params.toString()}`);
                                                window.dispatchEvent(new PopStateEvent('popstate'));
                                                window.scrollTo({ top: 0, behavior: 'smooth' });
                                            }}
                                            disabled={currentPage === 1}
                                            className="flex items-center gap-1 rounded-lg border border-light-border px-3 py-2 text-sm text-warm-gray hover:text-charcoal hover:border-warm-gray/50 disabled:opacity-40 transition-all"
                                        >
                                            <ChevronLeft className="h-4 w-4" /> Previous
                                        </button>
                                        {Array.from({ length: Math.min(totalPages, 7) }).map((_, i) => {
                                            let pageNum: number;
                                            if (totalPages <= 7) {
                                                pageNum = i + 1;
                                            } else if (currentPage <= 4) {
                                                pageNum = i + 1;
                                            } else if (currentPage >= totalPages - 3) {
                                                pageNum = totalPages - 6 + i;
                                            } else {
                                                pageNum = currentPage - 3 + i;
                                            }
                                            return (
                                                <button
                                                    key={pageNum}
                                                    onClick={() => {
                                                        const params = new URLSearchParams(searchParams.toString());
                                                        params.set('page', String(pageNum));
                                                        window.history.pushState(null, '', `?${params.toString()}`);
                                                        window.dispatchEvent(new PopStateEvent('popstate'));
                                                        window.scrollTo({ top: 0, behavior: 'smooth' });
                                                    }}
                                                    className={`h-9 w-9 rounded-lg text-sm font-medium transition-all ${currentPage === pageNum
                                                        ? 'bg-burgundy text-white shadow-sm'
                                                        : 'border border-light-border text-warm-gray hover:text-charcoal hover:border-warm-gray/50'
                                                        }`}
                                                >
                                                    {pageNum}
                                                </button>
                                            );
                                        })}
                                        <button
                                            onClick={() => {
                                                const params = new URLSearchParams(searchParams.toString());
                                                params.set('page', String(Math.min(totalPages, currentPage + 1)));
                                                window.history.pushState(null, '', `?${params.toString()}`);
                                                window.dispatchEvent(new PopStateEvent('popstate'));
                                                window.scrollTo({ top: 0, behavior: 'smooth' });
                                            }}
                                            disabled={currentPage === totalPages}
                                            className="flex items-center gap-1 rounded-lg border border-light-border px-3 py-2 text-sm text-warm-gray hover:text-charcoal hover:border-warm-gray/50 disabled:opacity-40 transition-all"
                                        >
                                            Next <ChevronRight className="h-4 w-4" />
                                        </button>
                                    </div>
                                )}
                            </>
                        ) : (
                            <div className="rounded-xl border border-light-border bg-white py-20 text-center shadow-sm">
                                <Wine className="h-12 w-12 mx-auto text-warm-gray/30 mb-4" />
                                <p className="font-serif text-xl text-charcoal">No wines found</p>
                                <p className="mt-2 text-sm text-warm-gray">Try adjusting your filters or search</p>
                                {activeChips.length > 0 && (
                                    <button
                                        onClick={clearAll}
                                        className="mt-4 rounded-lg bg-burgundy px-5 py-2 text-sm font-medium text-white hover:bg-burgundy-dark transition-colors"
                                    >
                                        Clear All Filters
                                    </button>
                                )}
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

export default function ProductsPage() {
    return (
        <Suspense fallback={<div className="min-h-screen bg-cream p-8"><SkeletonProductGrid count={12} /></div>}>
            <ProductsContent />
        </Suspense>
    );
}

'use client';

import { useState, useEffect, useRef, useCallback, Suspense } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { useAuth } from '@/context/AuthContext';
import { sendVerificationEmail, verifyEmail, createCart } from '@/lib/api';
import { Mail, Loader2, CheckCircle2, XCircle, ArrowLeft, RefreshCw, Eye } from 'lucide-react';
import toast from 'react-hot-toast';

function VerifyEmailContent() {
    const router = useRouter();
    const searchParams = useSearchParams();
    const { user, isAuthenticated, isLoading: authLoading, loginFromVerification } = useAuth();

    const isFromRegistration = searchParams.get('registered') === 'true';
    const emailFromUrl = searchParams.get('email');
    const emailToUse = user?.email || emailFromUrl;

    const [otp, setOtp] = useState(['', '', '', '', '', '']);
    const [loading, setLoading] = useState(false);
    const [sending, setSending] = useState(false);
    const [status, setStatus] = useState<'idle' | 'success' | 'error'>('idle');
    const [errorMessage, setErrorMessage] = useState('');
    // If coming from registration, an OTP was just sent.
    const [cooldown, setCooldown] = useState(isFromRegistration ? 60 : 0);
    const [otpSent, setOtpSent] = useState(isFromRegistration);
    const inputRefs = useRef<(HTMLInputElement | null)[]>([]);

    // Removed: Redirect if not authenticated because during registration flow, 
    // the user is purposefully NOT authenticated until they verify and log in.

    // Cooldown timer
    useEffect(() => {
        if (cooldown <= 0) return;
        const timer = setInterval(() => setCooldown(c => c - 1), 1000);
        return () => clearInterval(timer);
    }, [cooldown]);

    // Auto-send OTP on mount
    const handleSendOtp = useCallback(async () => {
        if (sending || cooldown > 0) return;
        setSending(true);
        try {
            const res = await sendVerificationEmail(emailToUse || undefined);
            if (res.success) {
                setOtpSent(true);
                setCooldown(60);
                toast.success('Verification code sent to your email!');
            } else if (res.message?.includes('already verified')) {
                setStatus('success');
                toast.success('Email is already verified!');
            } else {
                toast.error(res.message || 'Failed to send verification code');
            }
        } catch {
            toast.error('Network error. Please try again.');
        } finally {
            setSending(false);
        }
    }, [sending, cooldown]);

    useEffect(() => {
        // If they just landed here and haven't had an OTP sent yet, and are authenticated 
        // OR we have their email from the URL, try to send one.
        if (!otpSent && status !== 'success' && emailToUse) {
            handleSendOtp();
        }
    }, [emailToUse, otpSent, status, handleSendOtp]);

    // OTP input handlers
    const handleChange = (index: number, value: string) => {
        if (!/^\d*$/.test(value)) return;
        const newOtp = [...otp];
        newOtp[index] = value.slice(-1);
        setOtp(newOtp);
        setErrorMessage('');
        setStatus('idle');

        if (value && index < 5) {
            inputRefs.current[index + 1]?.focus();
        }
    };

    const handleKeyDown = (index: number, e: React.KeyboardEvent) => {
        if (e.key === 'Backspace' && !otp[index] && index > 0) {
            inputRefs.current[index - 1]?.focus();
        }
    };

    const handlePaste = (e: React.ClipboardEvent) => {
        e.preventDefault();
        const pasted = e.clipboardData.getData('text').replace(/\D/g, '').slice(0, 6);
        if (pasted.length === 6) {
            const newOtp = pasted.split('');
            setOtp(newOtp);
            inputRefs.current[5]?.focus();
        }
    };

    // Submit OTP
    const handleVerify = async () => {
        const code = otp.join('');
        if (code.length !== 6) {
            setErrorMessage('Please enter the complete 6-digit code');
            return;
        }

        setLoading(true);
        setErrorMessage('');
        try {
            const res = await verifyEmail(code, emailToUse || undefined);
            if (res.success) {
                setStatus('success');

                // Check if this was a new account creation (deferred registration)
                if (res.data?.account_created && res.data?.customer) {
                    // Log in the user via AuthContext
                    loginFromVerification(res.data.customer, res.data.access_token);

                    // Create cart for the new user
                    try {
                        await createCart(res.data.customer.customer_id);
                        console.log('✅ Cart created for:', res.data.customer.customer_id);
                    } catch (cartErr) {
                        console.warn('⚠️ Cart creation failed:', cartErr);
                    }

                    toast.success('Account created & verified! Welcome!');
                    setTimeout(() => router.push('/account'), 2000);
                } else {
                    // Existing user just verifying email
                    toast.success('Email verified successfully!');
                    setTimeout(() => router.push('/account'), 2000);
                }
            } else {
                setStatus('error');
                setErrorMessage(res.message || 'Invalid verification code');
            }
        } catch {
            setStatus('error');
            setErrorMessage('Network error. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    // Retry OTP — clear inputs and refocus
    const handleRetry = () => {
        setOtp(['', '', '', '', '', '']);
        setStatus('idle');
        setErrorMessage('');
        inputRefs.current[0]?.focus();
    };

    // Auto-submit when all 6 digits are entered
    useEffect(() => {
        if (otp.every(d => d !== '') && status === 'idle' && !loading) {
            handleVerify();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [otp]);

    if (authLoading) {
        return (
            <div className="min-h-screen bg-cream flex items-center justify-center">
                <Loader2 className="h-8 w-8 animate-spin text-burgundy" />
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-cream flex items-center justify-center px-4">
            <div className="w-full max-w-md">
                {/* Back button */}
                <button
                    onClick={() => router.push('/account')}
                    className="flex items-center gap-2 text-sm text-warm-gray hover:text-charcoal mb-6 transition-colors"
                >
                    <ArrowLeft className="h-4 w-4" /> Back to Account
                </button>

                <div className="rounded-2xl border border-light-border bg-white overflow-hidden shadow-sm">
                    {/* Header gradient */}
                    <div
                        className="py-8 px-6 text-center"
                        style={{ background: 'linear-gradient(135deg, #6B2737 0%, #8B3A4A 40%, #D4A847 100%)' }}
                    >
                        <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-white/15 backdrop-blur-sm">
                            {status === 'success' ? (
                                <CheckCircle2 className="h-8 w-8 text-green-300" />
                            ) : status === 'error' ? (
                                <XCircle className="h-8 w-8 text-red-300" />
                            ) : (
                                <Mail className="h-8 w-8 text-white" />
                            )}
                        </div>
                        <h1 className="font-serif text-2xl font-bold text-white">
                            {status === 'success' ? 'Email Verified!' : 'Verify Your Email'}
                        </h1>
                        <p className="mt-2 text-sm text-white/80">
                            {status === 'success'
                                ? 'Your email has been verified successfully'
                                : `We sent a 6-digit code to ${emailToUse || 'your email'}`}
                        </p>
                    </div>

                    <div className="p-6">
                        {status === 'success' ? (
                            <div className="text-center py-4">
                                <p className="text-sm text-warm-gray mb-4">Redirecting to login...</p>
                                <Loader2 className="h-5 w-5 animate-spin text-burgundy mx-auto" />
                            </div>
                        ) : (
                            <>
                                {/* OTP Input */}
                                <div className="flex justify-center gap-3 mb-6" onPaste={handlePaste}>
                                    {otp.map((digit, i) => (
                                        <input
                                            key={i}
                                            ref={el => { inputRefs.current[i] = el; }}
                                            type="text"
                                            inputMode="numeric"
                                            maxLength={1}
                                            value={digit}
                                            onChange={e => handleChange(i, e.target.value)}
                                            onKeyDown={e => handleKeyDown(i, e)}
                                            className={`w-12 h-14 text-center text-xl font-bold rounded-xl border-2 transition-all duration-200 focus:outline-none
                                                ${status === 'error'
                                                    ? 'border-red-300 bg-red-50 text-red-700 focus:border-red-500'
                                                    : digit
                                                        ? 'border-burgundy/40 bg-burgundy/5 text-charcoal focus:border-burgundy'
                                                        : 'border-light-border bg-white text-charcoal focus:border-burgundy'
                                                }`}
                                            autoFocus={i === 0}
                                        />
                                    ))}
                                </div>

                                {/* Error message + Retry / Guest options */}
                                {errorMessage && (
                                    <div className="mb-4">
                                        <p className="text-center text-sm text-red-500 mb-4 flex items-center justify-center gap-1.5">
                                            <XCircle className="h-3.5 w-3.5" />
                                            {errorMessage}
                                        </p>
                                        <div className="flex gap-3">
                                            <button
                                                onClick={handleRetry}
                                                className="flex-1 rounded-xl py-2.5 text-sm font-semibold text-white transition-all hover:shadow-md"
                                                style={{ backgroundColor: '#6B2737' }}
                                            >
                                                <RefreshCw className="inline h-3.5 w-3.5 mr-1.5 -mt-0.5" />
                                                Retry OTP
                                            </button>
                                            <button
                                                onClick={() => { router.push('/'); }}
                                                className="flex-1 rounded-xl py-2.5 text-sm font-semibold border border-light-border text-charcoal hover:bg-cream transition-colors"
                                            >
                                                <Eye className="inline h-3.5 w-3.5 mr-1.5 -mt-0.5" />
                                                Continue as Guest
                                            </button>
                                        </div>
                                    </div>
                                )}

                                {/* Verify button — only show when no error */}
                                {status !== 'error' && (
                                    <button
                                        onClick={handleVerify}
                                        disabled={loading || otp.some(d => d === '')}
                                        className="w-full rounded-xl py-3 text-sm font-semibold text-white transition-all hover:shadow-md disabled:opacity-50"
                                        style={{ backgroundColor: '#6B2737' }}
                                    >
                                        {loading ? (
                                            <span className="flex items-center justify-center gap-2">
                                                <Loader2 className="h-4 w-4 animate-spin" /> Verifying...
                                            </span>
                                        ) : (
                                            'Verify Email'
                                        )}
                                    </button>
                                )}

                                {/* Resend */}
                                <div className="text-center mt-5">
                                    <p className="text-xs text-warm-gray mb-2">Didn&apos;t receive the code?</p>
                                    <button
                                        onClick={handleSendOtp}
                                        disabled={sending || cooldown > 0}
                                        className="inline-flex items-center gap-1.5 text-sm font-medium text-burgundy hover:text-burgundy-dark transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                                    >
                                        <RefreshCw className={`h-3.5 w-3.5 ${sending ? 'animate-spin' : ''}`} />
                                        {cooldown > 0
                                            ? `Resend in ${cooldown}s`
                                            : sending
                                                ? 'Sending...'
                                                : 'Resend Code'}
                                    </button>
                                </div>

                                {/* Continue as Guest — always visible */}
                                <div className="mt-4 pt-4 border-t border-light-border text-center">
                                    <button
                                        onClick={() => router.push('/')}
                                        className="text-xs font-medium text-warm-gray hover:text-charcoal transition-colors"
                                    >
                                        Skip for now — Continue as Guest
                                    </button>
                                </div>
                            </>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

export default function VerifyEmailPage() {
    return (
        <Suspense fallback={
            <div className="min-h-screen bg-cream flex items-center justify-center">
                <Loader2 className="h-8 w-8 animate-spin text-burgundy" />
            </div>
        }>
            <VerifyEmailContent />
        </Suspense>
    );
}

