                {wishlistCount > 0 && (
                  <span className="absolute -top-0.5 -right-0.5 bg-[#4b0f1a] text-white text-[9px] font-bold h-4 w-4 flex items-center justify-center rounded-full">
                    {wishlistCount}
                  </span>
                )}
              </button>

              <div className="flex items-center">
                <Link href="/cart" className="relative p-2 group">
                  <ShoppingCart className="h-[20px] w-[20px] text-gray-600 group-hover:text-[#4b0f1a] transition-colors" />
                  {totalItems > 0 && (
                    <span className="absolute -top-0.5 -right-0.5 bg-[#4b0f1a] text-white text-[9px] font-bold h-4 w-4 flex items-center justify-center rounded-full">
                      {totalItems}
                    </span>
                  )}
                </Link>

                {/* Cart Reminder Popup */}
                {showCartReminder && (
                  <div className="absolute top-full right-0 mt-3 w-72 bg-white rounded-xl shadow-2xl border border-gray-100 p-4 z-50 animate-in slide-in-from-top-4 fade-in duration-300">
                    <button
                      onClick={() => setShowCartReminder(false)}
                      className="absolute top-2 right-2 p-1.5 text-gray-400 hover:text-gray-600 transition-colors rounded-full hover:bg-gray-100"
                    >
                      <X className="h-4 w-4" />
