'use client';

import Link from 'next/link';
import { Heart, ShoppingCart } from 'lucide-react';
import { Product } from '@/types';
import { useWishlist } from '@/context/WishlistContext';
import { getRatingSummary, formatVND } from '@/lib/api';
import StarRating from '@/components/reviews/StarRating';
import { useState, useEffect } from 'react';
import toast from 'react-hot-toast';

interface ProductCardProps {
    product: Product;
    onMoveToCart?: (e: React.MouseEvent) => void;
}

export default function ProductCard({ product, onMoveToCart }: ProductCardProps) {
    const { isInWishlist, toggleItem } = useWishlist();
    const wishlisted = isInWishlist(product.product_id);
    const [activeImageIndex, setActiveImageIndex] = useState(0);

    const [avgRating, setAvgRating] = useState(0);
    const [totalReviews, setTotalReviews] = useState(0);

    useEffect(() => {
        getRatingSummary(product.product_id).then(res => {
            if (res.success && res.data) {
                setAvgRating(res.data.average_rating ?? 0);
                setTotalReviews(res.data.total_reviews ?? 0);
            }
        }).catch(() => { });
    }, [product.product_id]);

    const handleToggleWishlist = (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
        toggleItem(product);
        toast.success(wishlisted ? 'Removed from wishlist' : 'Added to wishlist');
    };

    const displayPrice = product.price ?? Math.floor(Math.random() * 500000 + 100000);
    const isOnSale = product.is_on_sale ?? false;
    const originalPrice = product.original_price ?? displayPrice;
    const discountPercent = product.discount_percentage ?? 0;

    return (
        <Link href={`/products/${product.product_id}`} className="group block">
            <div className="overflow-hidden rounded-xl bg-white border border-neutral-200 transition-all duration-200 hover:-translate-y-2 hover:shadow-2xl shadow-lg">

                {/* Image Section */}
                <div className="relative h-72 overflow-hidden bg-gradient-to-br from-[#f8f5f2] to-[#efe7df]">
                    <div className="absolute inset-0 flex items-center justify-center">
                        <img
                            src={product.images?.[activeImageIndex] || "/card-drink.webp"}
                            alt={product.product_name}
                            className="object-contain h-full w-full"
                        />

                        {/* {product.images && product.images.length > 0 ? (
                            <img
                                src={product.images[0]}
                                alt={product.product_name}
                                className="h-full w-full object-cover transition-transform duration-700 group-hover:scale-110"
                            />
                        ) : (
                            <span className="text-[110px] transition-transform duration-700 group-hover:scale-110">
                                <img src="/card-drink.webp" alt="" />
                            </span>
                        )} */}
                    </div>

                    {/* reflection overlay */}
                    <div className="pointer-events-none absolute inset-0 bg-gradient-to-t from-black/10 via-transparent to-white/30 opacity-60" />

                    {/* Wishlist */}
                    <button
                        onClick={handleToggleWishlist}
                        className="absolute top-4 right-4 rounded-full bg-white/85 stroke-wine-gold backdrop-blur-md p-2 shadow-md transition hover:scale-110"
                    >
                        <Heart
                            className={`h-4 w-4 transition ${wishlisted
                                ? 'fill-[#6b0f1a] text-[#6b0f1a]'
                                : 'text-wine-gold'
                                }`}
                        />
                    </button>

                    {/* Category Badge */}
                    {product.category && (
                        <span className="absolute left-4 top-4 rounded-full bg-burgundy px-3 py-1 text-[10px] tracking-widest text-white uppercase backdrop-blur">
                            {product.category}
                        </span>
                    )}

                    {/* Product Badges (bottom-left, stacked) */}
                    <div className="absolute left-4 bottom-4 flex flex-col gap-1.5">
                        {product.is_availability_expired && !product.is_coming_soon && (
                            <span className="rounded-full bg-gradient-to-r from-red-700 to-red-500 px-3 py-1 text-[10px] font-bold tracking-widest text-white uppercase shadow-md flex items-center gap-1">
                                ⏱ No Longer Available
                            </span>
                        )}
                        {product.is_coming_soon && (
                            <span className="rounded-full bg-gradient-to-r from-purple-600 to-indigo-500 px-3 py-1 text-[10px] font-bold tracking-widest text-white uppercase shadow-md flex items-center gap-1">
                                🕒 Coming Soon
                            </span>
                        )}
                        {product.is_best_seller && !product.is_coming_soon && (
                            <span className="rounded-full bg-gradient-to-r from-amber-600 to-yellow-500 px-3 py-1 text-[10px] font-bold tracking-widest text-white uppercase shadow-md flex items-center gap-1">
                                🏆 Best Seller
                            </span>
                        )}
                        {product.is_new_arrival && !product.is_coming_soon && (
                            <span className="rounded-full bg-gradient-to-r from-emerald-500 to-teal-400 px-3 py-1 text-[10px] font-bold tracking-widest text-white uppercase shadow-md flex items-center gap-1">
                                ✨ New Arrival
                            </span>
                        )}
                        {product.is_featured && !product.is_best_seller && !product.is_coming_soon && (
                            <span className="rounded-full bg-gradient-to-r from-amber-500 to-yellow-400 px-3 py-1 text-[10px] font-bold tracking-widest text-white uppercase shadow-md flex items-center gap-1">
                                ✦ Featured
                            </span>
                        )}
                    </div>

                    {/* Move to Cart – slides up on hover */}
                    {onMoveToCart && !product.is_coming_soon && !product.is_availability_expired && (
                        <button
                            onClick={onMoveToCart}
                            className="absolute bottom-0 left-0 right-0 flex items-center justify-center gap-2 bg-burgundy/95 backdrop-blur-sm py-3 text-sm font-semibold text-white translate-y-full group-hover:translate-y-0 transition-transform duration-300 ease-out hover:bg-burgundy cursor-pointer"
                        >
                            <ShoppingCart className="h-4 w-4" />
                            Move to Cart
                        </button>
                    )}
                </div>

                {/* Content */}
                <div className="p-5">
                    <h3 className="font-serif text-lg font-semibold text-neutral-900 leading-snug line-clamp-2 tracking-tight">
                        {product.product_name}
                    </h3>

                    {product.brand && (
                        <p className="mt-1 text-xs uppercase tracking-widest text-neutral-500">
                            {product.brand}
                        </p>
                    )}

                    <p className="mt-1.5 text-[11px] font-medium text-neutral-400 tracking-wide">
                        {product.alcohol_percentage != null ? product.alcohol_percentage : '0'}% ABV
                    </p>

                    <div className="mt-3 flex items-center gap-2 flex-wrap">
                        <p className="text-xl font-serif font-bold text-[#6b0f1a] tracking-tight">
                            {formatVND(displayPrice)}
                        </p>
                        {isOnSale && originalPrice && (
                            <>
                                <p className="text-xs text-neutral-400 line-through decoration-[#6b0f1a]/40">
                                    {formatVND(originalPrice)}
                                </p>
                                <span className="bg-red-50 text-red-600 text-[10px] font-bold px-1.5 py-0.5 rounded border border-red-200 uppercase tracking-wide">
                                    {discountPercent}% OFF
                                </span>
                            </>
                        )}
                    </div>

                    {/* Rating */}
                    <div className="mt-2 flex items-center gap-1.5">
                        <StarRating value={avgRating} size="sm" />
                        <span className="text-xs text-neutral-400">
                            {avgRating > 0 ? `${avgRating.toFixed(1)}` : ''}
                            {totalReviews > 0 && (
                                <span className="ml-1">({totalReviews} review{totalReviews !== 1 ? 's' : ''})</span>
                            )}
                        </span>
                    </div>
                </div>
            </div>
        </Link>
    );
}




