'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import { Search, X, Loader2 } from 'lucide-react';
import { searchAutocomplete, type SearchSuggestion } from '@/lib/api';

interface SearchAutocompleteProps {
    /** Called when the search overlay should close (e.g. mobile) */
    onClose?: () => void;
    /** Placeholder text */
    placeholder?: string;
    /** Additional wrapper classes */
    className?: string;
}

export default function SearchAutocomplete({
    onClose,
    placeholder = 'Search wines…',
    className = '',
}: SearchAutocompleteProps) {
    const router = useRouter();
    const [query, setQuery] = useState('');
    const [suggestions, setSuggestions] = useState<SearchSuggestion[]>([]);
    const [isOpen, setIsOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [activeIndex, setActiveIndex] = useState(-1);

    const inputRef = useRef<HTMLInputElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const debounceRef = useRef<ReturnType<typeof setTimeout>>(undefined);

    // ── Debounced fetch ────────────────────────────────────────
    const fetchSuggestions = useCallback(async (term: string) => {
        if (term.trim().length < 2) {
            setSuggestions([]);
            setIsOpen(false);
            return;
        }

        setIsLoading(true);
        try {
            const results = await searchAutocomplete(term);
            setSuggestions(results);
        } catch {
            setSuggestions([]);
        } finally {
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        if (debounceRef.current) clearTimeout(debounceRef.current);

        if (query.trim().length < 2) {
            setSuggestions([]);
            setIsOpen(false);
            setIsLoading(false);
            return;
        }

        setIsLoading(true);
        debounceRef.current = setTimeout(() => {
            fetchSuggestions(query);
        }, 300);

        return () => {
            if (debounceRef.current) clearTimeout(debounceRef.current);
        };
    }, [query, fetchSuggestions]);

    // ── Click outside to close ─────────────────────────────────
    useEffect(() => {
        const handleClickOutside = (e: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // ── Static Storefront Pages ──
    const storePages = [
        { title: 'Home', path: '/' },
        { title: 'All Products', path: '/products' },
        { title: 'Categories', path: '/categories' },
        { title: 'About Us', path: '/about' },
        { title: 'Contact Support', path: '/contact' },
    ];

    const matchedPages = query.trim().length >= 2
        ? storePages.filter(p => p.title.toLowerCase().includes(query.toLowerCase()))
        : [];

    const totalItems = matchedPages.length + suggestions.length;
    const isShowingViewAll = suggestions.length > 0;
    const maxIndex = isShowingViewAll ? totalItems : totalItems - 1;

    // ── Navigate to product, page, or search page ─────────────────────
    const goToProduct = (id: string) => {
        setIsOpen(false);
        setQuery('');
        onClose?.();
        router.push(`/products/${id}`);
    };

    const goToPage = (path: string) => {
        setIsOpen(false);
        setQuery('');
        onClose?.();
        router.push(path);
    };

    const goToSearch = () => {
        if (!query.trim()) return;
        setIsOpen(false);
        onClose?.();
        router.push(`/search?q=${encodeURIComponent(query.trim())}`);
    };

    // ── Keyboard navigation ────────────────────────────────────
    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (!isOpen && e.key !== 'Enter') return;

        switch (e.key) {
            case 'ArrowDown':
                e.preventDefault();
                setActiveIndex(prev => prev < maxIndex ? prev + 1 : 0);
                break;
            case 'ArrowUp':
                e.preventDefault();
                setActiveIndex(prev => prev > 0 ? prev - 1 : maxIndex);
                break;
            case 'Enter':
                e.preventDefault();
                if (activeIndex >= 0) {
                    if (activeIndex < matchedPages.length) {
                        goToPage(matchedPages[activeIndex].path);
                    } else if (activeIndex < totalItems) {
                        goToProduct(suggestions[activeIndex - matchedPages.length].product_id);
                    } else if (isShowingViewAll) {
                        goToSearch();
                    }
                } else {
                    goToSearch();
                }
                break;
            case 'Escape':
                setIsOpen(false);
                setActiveIndex(-1);
                inputRef.current?.blur();
                break;
        }
    };

    // ── Format price ───────────────────────────────────────────
    const formatPrice = (price?: number) => {
        if (price == null) return '';
        return new Intl.NumberFormat('en-IN', {
            style: 'currency',
            currency: 'INR',
            minimumFractionDigits: 0,
            maximumFractionDigits: 0,
        }).format(price);
    };

    return (
        <div ref={containerRef} className={`relative ${className}`}>
            {/* ─── Search Input ─── */}
            <div className="relative flex items-center">
                <Search className="absolute left-3 h-4 w-4 text-gray-400 pointer-events-none" />
                <input
                    ref={inputRef}
                    type="text"
                    value={query}
                    onChange={e => {
                        setQuery(e.target.value);
                        setActiveIndex(-1);
                        if (e.target.value.trim().length >= 2 && !isOpen) {
                            setIsOpen(true);
                        }
                    }}
                    onFocus={() => {
                        if (suggestions.length > 0 || query.trim().length >= 2) setIsOpen(true);
                    }}
                    onKeyDown={handleKeyDown}
                    placeholder={placeholder}
                    autoComplete="off"
                    className="
            w-full pl-9 pr-9 py-2 rounded-full
            bg-gray-100 border border-gray-200
            text-sm text-gray-800 placeholder-gray-400
            focus:outline-none focus:ring-2 focus:ring-[#4b0f1a]/30 focus:border-[#4b0f1a]/40
            transition-all duration-200
          "
                />
                {/* Clear / Loading indicator */}
                {query && (
                    <button
                        onClick={() => {
                            setQuery('');
                            setSuggestions([]);
                            setIsOpen(false);
                            inputRef.current?.focus();
                        }}
                        className="absolute right-3 p-0.5 text-gray-400 hover:text-gray-600 transition-colors"
                    >
                        {isLoading ? (
                            <Loader2 className="h-4 w-4 animate-spin" />
                        ) : (
                            <X className="h-4 w-4" />
                        )}
                    </button>
                )}
            </div>

            {/* ─── Dropdown Panel ─── */}
            {isOpen && query.trim().length >= 2 && (
                <div className="
          absolute top-full left-0 right-0 mt-1.5 z-[300]
          bg-white rounded-xl shadow-2xl border border-gray-100
          max-h-[420px] overflow-y-auto
          animate-in fade-in slide-in-from-top-1 duration-200
        ">
                    {/* Pages Section */}
                    {matchedPages.length > 0 && (
                        <div className="py-1">
                            <p className="px-4 py-1.5 text-[10px] font-semibold uppercase tracking-wider text-gray-400 bg-gray-50/50">
                                Pages
                            </p>
                            {matchedPages.map((page, index) => (
                                <button
                                    key={page.path}
                                    onClick={() => goToPage(page.path)}
                                    onMouseEnter={() => setActiveIndex(index)}
                                    className={`
                    w-full flex items-center gap-3 px-4 py-2.5 text-left
                    transition-colors duration-100
                    ${activeIndex === index ? 'bg-[#fdf6ee] text-[#4b0f1a]' : 'hover:bg-gray-50 text-gray-700'}
                  `}
                                >
                                    <div className="flex-shrink-0 w-8 h-8 rounded-lg bg-gray-100 flex items-center justify-center">
                                        <Search className="h-3.5 w-3.5 opacity-40" />
                                    </div>
                                    <span className="text-sm font-medium">{page.title}</span>
                                </button>
                            ))}
                        </div>
                    )}

                    {/* Products Section */}
                    {(suggestions.length > 0 || isLoading) && (
                        <div className="py-1 border-t border-gray-100">
                            <p className="px-4 py-1.5 text-[10px] font-semibold uppercase tracking-wider text-gray-400 bg-gray-50/50">
                                Products
                            </p>
                            {isLoading && suggestions.length === 0 && (
                                <div className="flex items-center gap-2 px-4 py-3 text-sm text-gray-400">
                                    <Loader2 className="h-4 w-4 animate-spin" />
                                    Searching...
                                </div>
                            )}
                            {suggestions.map((item, index) => {
                                const globalIndex = index + matchedPages.length;
                                return (
                                    <button
                                        key={item.product_id}
                                        onClick={() => goToProduct(item.product_id)}
                                        onMouseEnter={() => setActiveIndex(globalIndex)}
                                        className={`
                      w-full flex items-center gap-3 px-4 py-3 text-left
                      transition-colors duration-100 border-b border-gray-50 last:border-b-0
                      ${activeIndex === globalIndex ? 'bg-[#fdf6ee]' : 'hover:bg-gray-50'}
                    `}
                                    >
                                        {/* Thumbnail */}
                                        <div className="flex-shrink-0 w-10 h-10 rounded-lg bg-gray-100 overflow-hidden">
                                            {item.thumbnail_url ? (
                                                <img
                                                    src={item.thumbnail_url}
                                                    alt={item.product_name}
                                                    className="w-full h-full object-cover"
                                                    loading="lazy"
                                                />
                                            ) : (
                                                <div className="w-full h-full flex items-center justify-center text-gray-300">
                                                    <Search className="h-4 w-4" />
                                                </div>
                                            )}
                                        </div>

                                        {/* Text */}
                                        <div className="flex-1 min-w-0">
                                            <p className="text-sm font-medium text-gray-900 truncate">
                                                {item.product_name}
                                            </p>
                                            <p className="text-xs text-gray-500 truncate">
                                                {[item.brand, item.category].filter(Boolean).join(' · ')}
                                            </p>
                                        </div>

                                        {/* Price */}
                                        {item.price != null && (
                                            <span className="flex-shrink-0 text-sm font-semibold text-[#4b0f1a]">
                                                {formatPrice(item.price)}
                                            </span>
                                        )}
                                    </button>
                                );
                            })}
                        </div>
                    )}

                    {/* Empty state */}
                    {!isLoading && matchedPages.length === 0 && suggestions.length === 0 && (
                        <div className="px-4 py-6 text-center text-sm text-gray-400">
                            No results found for &ldquo;{query}&rdquo;
                        </div>
                    )}

                    {/* View All Results Link */}
                    {isShowingViewAll && (
                        <button
                            onClick={goToSearch}
                            onMouseEnter={() => setActiveIndex(totalItems)}
                            className={`
                w-full flex items-center justify-center gap-2 px-4 py-3 border-t border-gray-100
                text-sm font-medium transition-colors duration-100
                ${activeIndex === totalItems
                                    ? 'bg-[#4b0f1a] text-white'
                                    : 'bg-[#fdf6ee] text-[#4b0f1a] hover:bg-[#4b0f1a] hover:text-white'
                                }
                rounded-b-xl
              `}
                        >
                            <Search className="h-3.5 w-3.5" />
                            View all results for &ldquo;{query}&rdquo;
                        </button>
                    )}
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { Shield, Download, Trash2, Eye, ExternalLink, Loader2, Info } from 'lucide-react';
import toast from 'react-hot-toast';

export default function PrivacyDashboard() {
    const [loading, setLoading] = useState(false);
    const [requests, setRequests] = useState<any[]>([]);

    useEffect(() => {
        fetchRequests();
    }, []);

    const fetchRequests = async () => {
        try {
            const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL || 'http://127.0.0.1:5000'}/api/gdpr/data-request`, {
                headers: { 'Authorization': `Bearer ${localStorage.getItem('user_token')}` },
                credentials: 'include'
            });
            if (res.ok) {
                const data = await res.json();
                if (data.success) {
                    setRequests(data.data);
                }
            }
        } catch (error) {
            console.error('Failed to fetch requests', error);
        }
    };

    const handleExport = async () => {
        setLoading(true);
        try {
            const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL || 'http://127.0.0.1:5000'}/api/gdpr/export`, {
                headers: { 'Authorization': `Bearer ${localStorage.getItem('user_token')}` },
                credentials: 'include'
            });
            if (res.ok) {
                const data = await res.json();
                if (data.success) {
                    const blob = new Blob([JSON.stringify(data.data, null, 2)], { type: 'application/json' });
                    const url = window.URL.createObjectURL(blob);
                    const a = document.createElement('a');
                    a.href = url;
                    a.download = `my-data-export-${new Date().toISOString().split('T')[0]}.json`;
                    a.click();
                    toast.success('Data exported successfully.');
                    fetchRequests(); // refresh logs
                } else {
                    toast.error(data.message || 'Export failed.');
                }
            }
        } catch (error) {
            toast.error('Network error during export.');
        } finally {
            setLoading(false);
        }
    };

    const handleErasure = async () => {
        if (!confirm('WARNING: This action is irreversible. It will completely anonymize your personal data and delete your account. Are you absolutely sure?')) {
            return;
        }

        setLoading(true);
        try {
            const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL || 'http://127.0.0.1:5000'}/api/gdpr/erasure`, {
                method: 'DELETE',
                headers: { 'Authorization': `Bearer ${localStorage.getItem('user_token')}` },
                credentials: 'include'
            });
            if (res.ok) {
                const data = await res.json();
                if (data.success) {
                    toast.success('Account successfully erased.');
                    window.location.href = '/login'; // log out natively
                } else {
                    toast.error(data.message || 'Erasure failed.');
                }
            }
        } catch (error) {
            toast.error('Network error during erasure request.');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="space-y-6 max-w-3xl">
            <div className="flex items-center gap-3 border-b border-light-border pb-4">
                <Shield className="h-6 w-6 text-burgundy" />
                <div>
                    <h2 className="font-serif text-xl font-bold text-charcoal">Privacy & Data Management</h2>
                    <p className="text-sm text-warm-gray">Control your personal data in compliance with GDPR guidelines.</p>
                </div>
            </div>

            {/* General Privacy Center Info */}
            <div className="bg-emerald-50 border border-emerald-100 rounded-xl p-5 text-emerald-900 text-sm flex gap-3">
                <Info className="h-5 w-5 shrink-0 text-emerald-600 mt-0.5" />
                <div>
                    <p className="font-semibold mb-1 text-emerald-800">Your Data Subjects Rights</p>
                    <p className="leading-relaxed opacity-90">
                        Under the General Data Protection Regulation (GDPR), you have the right to access, rectify, port, and erase your personal information.
                        Use the tools below to execute these rights automatically.
                    </p>
                    <a href="/privacy-policy" className="inline-flex items-center gap-1 mt-2 text-emerald-700 font-medium hover:underline">
                        Read our Privacy Policy <ExternalLink className="h-3 w-3" />
                    </a>
                </div>
            </div>

            <div className="grid md:grid-cols-2 gap-4">
                {/* Data Export Card */}
                <div className="rounded-xl border border-light-border bg-white p-5 hover:shadow-md transition-shadow">
                    <div className="flex h-10 w-10 items-center justify-center rounded-full bg-blue-50 mb-4">
                        <Download className="h-5 w-5 text-blue-600" />
                    </div>
                    <h3 className="font-serif font-bold text-charcoal mb-1">Data Portability</h3>
                    <p className="text-sm text-warm-gray mb-4">Download a machine-readable JSON file containing all your personal data, orders, and addresses.</p>
                    <button
                        onClick={handleExport}
                        disabled={loading}
                        className="w-full flex justify-center items-center gap-2 rounded-lg border border-light-border px-4 py-2 text-sm font-semibold text-charcoal hover:bg-cream transition-colors disabled:opacity-50"
                    >
                        {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Download className="h-4 w-4" />}
                        Export My Data
                    </button>
                </div>

                {/* Data Erasure Card */}
                <div className="rounded-xl border border-light-border bg-white p-5 hover:border-red-200 transition-colors">
                    <div className="flex h-10 w-10 items-center justify-center rounded-full bg-red-50 mb-4">
                        <Trash2 className="h-5 w-5 text-red-600" />
                    </div>
                    <h3 className="font-serif font-bold text-charcoal mb-1">Right to be Forgotten</h3>
                    <p className="text-sm text-warm-gray mb-4">Permanently anonymize your personal information. This action will delete your account instantly.</p>
                    <button
                        onClick={handleErasure}
                        disabled={loading}
                        className="w-full flex justify-center items-center gap-2 rounded-lg bg-red-50 text-red-600 hover:bg-red-100 border border-red-100 px-4 py-2 text-sm font-semibold transition-colors disabled:opacity-50"
                    >
                        {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Trash2 className="h-4 w-4" />}
                        Erase Personal Data
                    </button>
                </div>
            </div>

            {/* Request History Log */}
            <div className="rounded-xl border border-light-border bg-white overflow-hidden mt-8">
                <div className="bg-cream px-5 py-3 border-b border-light-border flex justify-between items-center">
                    <h3 className="font-serif font-bold text-charcoal">Data Request Log</h3>
                    <div className="text-xs text-warm-gray">Maintained for Article 30 compliance</div>
                </div>
                {requests.length === 0 ? (
                    <div className="p-8 text-center text-warm-gray text-sm">
                        No previous privacy requests found.
                    </div>
                ) : (
                    <ul className="divide-y divide-light-border">
                        {requests.map(req => (
                            <li key={req.id} className="p-4 flex items-center justify-between text-sm hover:bg-gray-50/50">
                                <div>
                                    <p className="font-medium text-charcoal">{req.request_type}</p>
                                    <p className="text-xs text-warm-gray mt-0.5">{new Date(req.created_at).toLocaleString()}</p>
                                    {req.details && <p className="text-xs text-warm-gray italic mt-1 bg-gray-50 p-1 inline-block rounded border">"{req.details}"</p>}
                                </div>
                                <span className={`px-2.5 py-1 rounded-full text-xs font-semibold ${req.status === 'COMPLETED' ? 'bg-emerald-100 text-emerald-700' :
                                        req.status === 'REJECTED' ? 'bg-red-100 text-red-700' :
                                            'bg-amber-100 text-amber-700'
                                    }`}>
                                    {req.status}
                                </span>
                            </li>
                        ))}
                    </ul>
                )}
            </div>

        </div>
    );
}

'use client';

import Link from 'next/link';
import { BlogPost } from '@/lib/api';

interface BlogPostCardProps {
    post: BlogPost;
    featured?: boolean;
}

export default function BlogPostCard({ post, featured = false }: BlogPostCardProps) {
    const date = post.published_at
        ? new Date(post.published_at).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })
        : '';

    return (
        <Link
            href={`/blog/${post.slug}`}
            className={`group block rounded-2xl border border-light-border bg-white overflow-hidden transition-all duration-500 hover:shadow-xl hover:shadow-burgundy/5 hover:-translate-y-1 ${featured ? 'md:col-span-2 md:grid md:grid-cols-2' : ''}`}
        >
            {/* Cover Image */}
            <div className={`relative overflow-hidden bg-cream-dark ${featured ? 'md:h-full h-52' : 'h-52'}`}>
                {post.cover_image ? (
                    <img
                        src={post.cover_image}
                        alt={post.title}
                        className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
                    />
                ) : (
                    <div className="w-full h-full flex items-center justify-center bg-gradient-to-br from-burgundy/10 to-wine-gold/10">
                        <svg className="w-12 h-12 text-burgundy/20" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M19 20H5a2 2 0 01-2-2V6a2 2 0 012-2h10a2 2 0 012 2v1m2 13a2 2 0 01-2-2V7m2 13a2 2 0 002-2V9a2 2 0 00-2-2h-2m-4-3H9M7 16h6M7 8h6v4H7V8z" />
                        </svg>
                    </div>
                )}

                {/* Category Badge */}
                {post.category_name && (
                    <span className="absolute top-3 left-3 px-3 py-1 rounded-full text-[11px] font-semibold uppercase tracking-wider bg-burgundy/90 text-white backdrop-blur-sm">
                        {post.category_name}
                    </span>
                )}

                {/* Blog Type Badge */}
                {post.blog_type && (
                    <span className="absolute top-3 right-3 px-3 py-1 rounded-full text-[11px] font-medium bg-white/90 text-charcoal backdrop-blur-sm">
                        {post.blog_type.replace(/_/g, ' ')}
                    </span>
                )}
            </div>

            {/* Content */}
            <div className={`p-5 ${featured ? 'flex flex-col justify-center' : ''}`}>
                {/* Tags */}
                {post.tags && post.tags.length > 0 && (
                    <div className="flex flex-wrap gap-1.5 mb-3">
                        {post.tags.slice(0, 3).map(tag => (
                            <span key={tag.tag_id} className="px-2 py-0.5 rounded-md text-[10px] font-medium uppercase tracking-wider bg-cream-dark text-warm-gray border border-light-border">
                                {tag.name}
                            </span>
                        ))}
                    </div>
                )}

                {/* Title */}
                <h3 className={`font-serif font-bold text-charcoal group-hover:text-burgundy transition-colors duration-300 leading-snug ${featured ? 'text-xl md:text-2xl mb-3' : 'text-lg mb-2'}`}>
                    {post.title}
                </h3>

                {/* Excerpt */}
                {post.excerpt && (
                    <p className={`text-warm-gray leading-relaxed ${featured ? 'line-clamp-3 text-sm' : 'line-clamp-2 text-sm'}`}>
                        {post.excerpt}
                    </p>
                )}

                {/* Meta Row */}
                <div className="flex items-center gap-3 mt-4 pt-3 border-t border-light-border/60">
                    {/* Author */}
                    {post.author_name && (
                        <span className="text-xs font-medium text-charcoal/80">{post.author_name}</span>
                    )}

                    {date && (
                        <>
                            <span className="w-[3px] h-[3px] rounded-full bg-warm-gray/40" />
                            <span className="text-xs text-warm-gray">{date}</span>
                        </>
                    )}

                    {post.reading_time && (
                        <>
                            <span className="w-[3px] h-[3px] rounded-full bg-warm-gray/40" />
                            <span className="text-xs text-warm-gray">{post.reading_time} min read</span>
                        </>
                    )}

                    {/* View count */}
                    {(post.view_count ?? 0) > 0 && (
                        <span className="ml-auto text-xs text-warm-gray/60">{post.view_count?.toLocaleString()} views</span>
                    )}
                </div>
            </div>
        </Link>
    );
}

'use client';

import { ChevronDown, ChevronUp, Search, X } from 'lucide-react';
import { useState, useRef, useEffect } from 'react';
import { COUNTRIES, getFlagByName } from '@/lib/countries';

interface CountryDropdownProps {
    options: string[];
    selected: string;
    onChange: (value: string) => void;
}

export default function CountryDropdown({ options, selected, onChange }: CountryDropdownProps) {
    const [open, setOpen] = useState(false);
    const [search, setSearch] = useState('');
    const [listOpen, setListOpen] = useState(false);
    const containerRef = useRef<HTMLDivElement>(null);
    const inputRef = useRef<HTMLInputElement>(null);

    // Close list on click outside
    useEffect(() => {
        const handler = (e: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
                setListOpen(false);
                setSearch('');
            }
        };
        document.addEventListener('mousedown', handler);
        return () => document.removeEventListener('mousedown', handler);
    }, []);

    // Focus input when list opens
    useEffect(() => {
        if (listOpen && inputRef.current) {
            inputRef.current.focus();
        }
    }, [listOpen]);

    const filtered = search
        ? options.filter(c => c.toLowerCase().includes(search.toLowerCase()))
        : options;

    return (
        <div className="py-4 border-b border-light-border/60" ref={containerRef}>
            <button
                type="button"
                onClick={() => setOpen(prev => !prev)}
                className="flex w-full items-center justify-between group"
                aria-expanded={open}
            >
                <span className="text-xs font-semibold uppercase tracking-[0.15em] text-charcoal/70 group-hover:text-burgundy transition-colors">
                    Country
                </span>
                {open
                    ? <ChevronUp className="h-4 w-4 text-warm-gray/60 group-hover:text-burgundy transition-colors" />
                    : <ChevronDown className="h-4 w-4 text-warm-gray/60 group-hover:text-burgundy transition-colors" />
                }
            </button>

            {open && (
                <div className="mt-3 animate-fade-in relative" style={{ animation: 'fadeInDown 0.18s ease' }}>
                    {/* Trigger — shows selected country or search input */}
                    <div
                        className={`
                            relative flex items-center w-full rounded-lg border px-3.5 py-2.5 text-sm cursor-pointer
                            bg-white transition-all duration-200 ease-in-out
                            ${selected
                                ? 'border-burgundy/50 ring-1 ring-burgundy/10'
                                : 'border-light-border'
                            }
                            hover:border-burgundy/30
                            focus-within:border-burgundy focus-within:ring-2 focus-within:ring-burgundy/10
                        `}
                        onClick={() => { setListOpen(true); setSearch(''); }}
                    >
                        {listOpen ? (
                            <>
                                <Search className="h-4 w-4 text-warm-gray/50 mr-2 flex-shrink-0" />
                                <input
                                    ref={inputRef}
                                    type="text"
                                    value={search}
                                    onChange={e => setSearch(e.target.value)}
                                    className="w-full bg-transparent outline-none text-charcoal placeholder:text-warm-gray/50 text-sm"
                                    placeholder="Type to search..."
                                    onClick={e => e.stopPropagation()}
                                />
                            </>
                        ) : (
                            <>
                                {selected ? (
                                    <span className="flex items-center gap-2 text-charcoal font-medium flex-1 truncate">
                                        <span className="text-base leading-none">{getFlagByName(selected)}</span>
                                        {selected}
                                    </span>
                                ) : (
                                    <span className="text-warm-gray/70 flex-1">🌍 All Countries</span>
                                )}
                            </>
                        )}
                        <div className="flex items-center gap-1 ml-2 flex-shrink-0">
                            {selected && !listOpen && (
                                <button
                                    type="button"
                                    onClick={(e) => { e.stopPropagation(); onChange(''); }}
                                    className="p-0.5 rounded hover:bg-cream transition-colors"
                                >
                                    <X className="h-3.5 w-3.5 text-warm-gray/60 hover:text-burgundy" />
                                </button>
                            )}
                            <ChevronDown className={`h-4 w-4 text-warm-gray/60 transition-transform duration-200 ${listOpen ? 'rotate-180' : ''}`} />
                        </div>
                    </div>

                    {/* Dropdown list */}
                    {listOpen && (
                        <div
                            className="absolute z-50 mt-1 w-full rounded-xl border border-light-border bg-white shadow-xl overflow-hidden"
                            style={{ maxHeight: '260px' }}
                        >
                            <div className="overflow-y-auto" style={{ maxHeight: '260px' }}>
                                {/* "All Countries" option */}
                                <button
                                    type="button"
                                    onClick={() => { onChange(''); setListOpen(false); setSearch(''); }}
                                    className={`flex w-full items-center gap-2.5 px-3.5 py-2.5 text-sm transition-colors hover:bg-burgundy/5 ${!selected ? 'bg-burgundy/[0.06] text-burgundy font-medium' : 'text-charcoal'
                                        }`}
                                >
                                    <span className="text-base leading-none">🌍</span>
                                    All Countries
                                </button>
                                {filtered.length === 0 ? (
                                    <div className="px-4 py-5 text-sm text-warm-gray/60 text-center">
                                        No countries found
                                    </div>
                                ) : (
                                    filtered.map(country => (
                                        <button
                                            key={country}
                                            type="button"
                                            onClick={() => { onChange(country); setListOpen(false); setSearch(''); }}
                                            className={`flex w-full items-center gap-2.5 px-3.5 py-2.5 text-sm transition-colors hover:bg-burgundy/5 ${selected === country
                                                    ? 'bg-burgundy/[0.06] text-burgundy font-medium'
                                                    : 'text-charcoal'
                                                }`}
                                        >
                                            <span className="text-base leading-none flex-shrink-0">{getFlagByName(country)}</span>
                                            <span className="truncate">{country}</span>
                                        </button>
                                    ))
                                )}
                            </div>
                        </div>
                    )}

                    {/* Active country badge (shown when list is closed) */}
                    {selected && !listOpen && (
                        <div className="mt-2 flex items-center gap-1.5">
                            <span className="text-base leading-none">{getFlagByName(selected)}</span>
                            <span className="text-xs font-medium text-burgundy">{selected}</span>
                            <button
                                type="button"
                                onClick={() => onChange('')}
                                className="ml-auto text-[11px] text-warm-gray/60 hover:text-burgundy transition-colors"
                            >
                                Clear
                            </button>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
}

'use client';

import { useEffect, useCallback, useRef, memo } from 'react';
import styles from './gallery.module.css';

interface ImageLightboxProps {
    images: { id: string; src: string; alt: string }[];
    activeIndex: number;
    onClose: () => void;
    onPrev: () => void;
    onNext: () => void;
    onSelect?: (index: number) => void;
}

/**
 * ImageLightbox — Premium Fullscreen Gallery
 * 
 * Features:
 *  - Backdrop blur with zoom-in animation
 *  - Navigation arrows + keyboard (← → Esc)
 *  - Thumbnail strip at the bottom
 *  - Swipe left/right on mobile (touch events)
 *  - Pinch-to-zoom via CSS touch-action
 *  - Counter + body scroll lock
 *  - ARIA dialog semantics
 */
function ImageLightboxInner({
    images,
    activeIndex,
    onClose,
    onPrev,
    onNext,
    onSelect,
}: ImageLightboxProps) {
    const touchStartX = useRef<number>(0);
    const touchEndX = useRef<number>(0);

    // Keyboard navigation + scroll lock
    useEffect(() => {
        const handleKey = (e: KeyboardEvent) => {
            if (e.key === 'Escape') onClose();
            if (e.key === 'ArrowLeft') onPrev();
            if (e.key === 'ArrowRight') onNext();
        };

        document.addEventListener('keydown', handleKey);
        document.body.style.overflow = 'hidden';

        return () => {
            document.removeEventListener('keydown', handleKey);
            document.body.style.overflow = '';
        };
    }, [onClose, onPrev, onNext]);

    // Swipe support
    const handleTouchStart = useCallback((e: React.TouchEvent) => {
        touchStartX.current = e.touches[0].clientX;
    }, []);

    const handleTouchMove = useCallback((e: React.TouchEvent) => {
        touchEndX.current = e.touches[0].clientX;
    }, []);

    const handleTouchEnd = useCallback(() => {
        const diff = touchStartX.current - touchEndX.current;
        const SWIPE_THRESHOLD = 50;
        if (diff > SWIPE_THRESHOLD) onNext();
        else if (diff < -SWIPE_THRESHOLD) onPrev();
    }, [onNext, onPrev]);

    // Click overlay background to close
    const handleOverlayClick = useCallback(
        (e: React.MouseEvent) => {
            if ((e.target as HTMLElement).classList.contains(styles.lightboxOverlay)) {
                onClose();
            }
        },
        [onClose]
    );

    const current = images[activeIndex];
    if (!current) return null;

    return (
        <div
            className={styles.lightboxOverlay}
            onClick={handleOverlayClick}
            role="dialog"
            aria-modal="true"
            aria-label="Image lightbox"
        >
            {/* Close button */}
            <button className={styles.lightboxClose} onClick={onClose} aria-label="Close lightbox">
                ✕
            </button>

            {/* Previous */}
            {images.length > 1 && (
                <button
                    className={`${styles.lightboxNav} ${styles.lightboxPrev}`}
                    onClick={onPrev}
                    aria-label="Previous image"
                >
                    ‹
                </button>
            )}

            {/* Main Image */}
            <div
                className={styles.lightboxContent}
                onTouchStart={handleTouchStart}
                onTouchMove={handleTouchMove}
                onTouchEnd={handleTouchEnd}
            >
                <img
                    key={current.id}
                    src={current.src}
                    alt={current.alt}
                    className={styles.lightboxImage}
                    draggable={false}
                />
            </div>

            {/* Next */}
            {images.length > 1 && (
                <button
                    className={`${styles.lightboxNav} ${styles.lightboxNext}`}
                    onClick={onNext}
                    aria-label="Next image"
                >
                    ›
                </button>
            )}

            {/* Bottom thumbnail strip */}
            {images.length > 1 && onSelect && (
                <div className={styles.lightboxThumbs}>
                    {images.map((img, index) => (
                        <button
                            key={img.id}
                            className={`${styles.lightboxThumbBtn} ${index === activeIndex ? styles.active : ''}`}
                            onClick={() => onSelect(index)}
                            aria-label={`View image ${index + 1}`}
                        >
                            <img
                                src={img.src}
                                alt={img.alt}
                                className={styles.lightboxThumbImg}
                                draggable={false}
                            />
                        </button>
                    ))}
                </div>
            )}

            {/* Counter */}
            {images.length > 1 && (
                <div className={styles.lightboxCounter}>
                    {activeIndex + 1} / {images.length}
                </div>
            )}
        </div>
    );
}

const ImageLightbox = memo(ImageLightboxInner);
export default ImageLightbox;

'use client';

import { useState, useRef, useEffect, useCallback, memo } from 'react';
import styles from './gallery.module.css';

interface ThumbnailStripProps {
    images: { id: string; src: string; alt: string; isVideo?: boolean; videoSrc?: string }[];
    activeIndex: number;
    onSelect: (index: number) => void;
    onHover?: (index: number) => void;
}

/**
 * ImageThumbnailStrip
 * Desktop: vertical strip on the left (scrollable).
 * Mobile: horizontal scrollable strip below the main image.
 * Highlights the active thumbnail and preloads the next image on hover.
 */
function ImageThumbnailStripInner({
    images,
    activeIndex,
    onSelect,
    onHover,
}: ThumbnailStripProps) {
    const stripRef = useRef<HTMLDivElement>(null);
    const activeRef = useRef<HTMLButtonElement>(null);

    // Scroll active thumbnail into view
    useEffect(() => {
        if (activeRef.current) {
            activeRef.current.scrollIntoView({
                behavior: 'smooth',
                block: 'nearest',
                inline: 'nearest',
            });
        }
    }, [activeIndex]);

    // Preload next image on hover
    const handleMouseEnter = useCallback(
        (index: number) => {
            onHover?.(index);

            // Preload adjacent images (skip for videos)
            const nextIdx = index + 1;
            if (nextIdx < images.length && !images[nextIdx].isVideo) {
                const link = document.createElement('link');
                link.rel = 'prefetch';
                link.as = 'image';
                link.href = images[nextIdx].src;
                document.head.appendChild(link);
            }
        },
        [images, onHover]
    );

    if (images.length <= 1) return null;

    return (
        <div className={styles.thumbStrip} ref={stripRef} role="tablist" aria-label="Product images">
            {images.map((img, index) => (
                <button
                    key={img.id}
                    ref={index === activeIndex ? activeRef : null}
                    className={`${styles.thumbBtn} ${index === activeIndex ? styles.active : ''}`}
                    onClick={() => onSelect(index)}
                    onMouseEnter={() => handleMouseEnter(index)}
                    role="tab"
                    aria-selected={index === activeIndex}
                    aria-label={img.isVideo ? `Play video ${index + 1}` : `View image ${index + 1}: ${img.alt}`}
                    tabIndex={index === activeIndex ? 0 : -1}
                >
                    {img.isVideo ? (
                        <div style={{ position: 'relative', width: '100%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#1a1a1a', borderRadius: '6px' }}>
                            <svg width="24" height="24" viewBox="0 0 24 24" fill="white" stroke="none">
                                <polygon points="5,3 19,12 5,21" />
                            </svg>
                        </div>
                    ) : (
                        <img
                            src={img.src}
                            alt={img.alt}
                            className={styles.thumbImg}
                            loading="lazy"
                            draggable={false}
                        />
                    )}
                </button>
            ))}
        </div>
    );
}

const ImageThumbnailStrip = memo(ImageThumbnailStripInner);
export default ImageThumbnailStrip;

