'use client';

import { useState, useCallback, useMemo, useRef, useEffect, memo } from 'react';
import type { ProductAsset, GalleryImage } from '@/types';
import ImageThumbnailStrip from './ImageThumbnailStrip';
import ImageZoom from './ImageZoom';
import ImageLightbox from './ImageLightbox';
import styles from './gallery.module.css';

interface ProductImageGalleryProps {
    assets?: ProductAsset[];
    productName: string;
    variantId?: string;
    /** Fallback image URLs from product.images (thumbnail_url mapped) */
    fallbackImages?: string[];
}

const FALLBACK_IMAGE = '/card-drink.webp';

/**
 * Resolve ProductAsset[] → GalleryImage[]
 * Robust: handles pre-migration data, missing fields, and all src formats.
 * Falls back to `fallbackImages` (e.g. from thumbnail_url) when assets are empty.
 */
function resolveGalleryImages(
    assets: ProductAsset[] | undefined,
    productName: string,
    variantId?: string,
    fallbackImages?: string[]
): GalleryImage[] {
    if (assets && Array.isArray(assets) && assets.length > 0) {
        let filtered = assets;
        if (variantId) {
            // Include images mapped strictly to this variant OR images that have NO variant mapped (legacy fallback)
            // But absolutely exclude images mapped to OTHER variants
            filtered = assets.filter((a) => a.variant_id === variantId || !a.variant_id);

            // If the filtered list ONLY has legacy images and the variant HAS specific images, 
            // the above logic merges both. Let's make it smarter:
            // If the variant HAS explicit images mapped to it, ONLY show those.
            const explicitVariantImages = assets.filter((a) => a.variant_id === variantId);
            if (explicitVariantImages.length > 0) {
                filtered = explicitVariantImages;
            }
        } else {
            // If NO variant is selected (e.g. initial load without default variant), 
            // we should probably just show images for the default variant or legacy images
            // but `page.tsx` usually passes a variantId.
            const defaultVariantImages = assets.filter(a => a.is_primary);
            if (defaultVariantImages.length > 0) {
                filtered = defaultVariantImages;
            }
        }

        // Image assets
        const imageAssets = filtered.filter((a) => a.media_type !== 'video' || !a.media_type);
        const videoAssets = filtered.filter((a) => a.media_type === 'video');

        const gallery: GalleryImage[] = [];

        // Add images
        imageAssets.forEach((a, index) => {
            let src = a.cdn_url || a.asset_url || a.base64_data;
            let isPrimary = a.is_primary;

            // If there's only 1 fallback image passed and it matches, use it to ensure it's not broken
            if (!src && fallbackImages && fallbackImages.length > 0) {
                src = fallbackImages[0];
            }

            gallery.push({
                id: a.asset_id || `asset-${index}`,
                src: src || FALLBACK_IMAGE,
                alt: a.alt_text || `${productName} - image ${index + 1}`,
                width: a.width,
                height: a.height,
                blurhash: a.blurhash,
                imageType: a.image_type,
                isPrimary: isPrimary,
            });
        });

        // Add videos as gallery items
        videoAssets.forEach((a, index) => {
            const videoUrl = a.cdn_url || a.asset_url || a.base64_data || '';
            gallery.push({
                id: a.asset_id || `video-${index}`,
                // Use a poster/fallback for the thumbnail src
                src: FALLBACK_IMAGE,
                alt: a.alt_text || `${productName} - video ${index + 1}`,
                isVideo: true,
                videoSrc: videoUrl,
            });
        });

        if (gallery.length > 0) return gallery;
    }

    // Fallback: use product.images (populated from thumbnail_url)
    if (fallbackImages && fallbackImages.length > 0) {
        return fallbackImages
            .filter((src) => !!src)
            .map((src, index) => ({
                id: `fallback-${index}`,
                src,
                alt: `${productName} - image ${index + 1}`,
                isPrimary: index === 0,
            }));
    }

    // Default Fallback: static image
    return [
        {
            id: 'default-fallback',
            src: FALLBACK_IMAGE,
            alt: `${productName} - product image`,
            isPrimary: true,
        },
    ];
}

/**
 * ProductImageGallery — Amazon-Style with video support inline
 */
function ProductImageGalleryInner({
    assets,
    productName,
    variantId,
    fallbackImages,
}: ProductImageGalleryProps) {
    const [activeIndex, setActiveIndex] = useState(0);
    const [lightboxOpen, setLightboxOpen] = useState(false);
    const [imageLoaded, setImageLoaded] = useState(false);
    const [imageError, setImageError] = useState(false);

    // Refs for Amazon-style zoom
    const mainPreviewRef = useRef<HTMLDivElement>(null);
    const zoomPanelRef = useRef<HTMLDivElement>(null);
    const imageRef = useRef<HTMLImageElement>(null);

    const images = useMemo(
        () => resolveGalleryImages(assets, productName, variantId, fallbackImages),
        [assets, productName, variantId, fallbackImages]
    );

    useEffect(() => {
        setActiveIndex(0);
        setImageLoaded(false);
        setImageError(false);
    }, [variantId, images.length]);

    useEffect(() => {
        setImageLoaded(false);
        setImageError(false);
    }, [activeIndex]);

    // Keyboard nav (when lightbox is closed)
    useEffect(() => {
        const handleKey = (e: KeyboardEvent) => {
            if (lightboxOpen) return;
            if (e.key === 'ArrowLeft') setActiveIndex((p) => (p > 0 ? p - 1 : images.length - 1));
            if (e.key === 'ArrowRight') setActiveIndex((p) => (p < images.length - 1 ? p + 1 : 0));
        };
        document.addEventListener('keydown', handleKey);
        return () => document.removeEventListener('keydown', handleKey);
    }, [images.length, lightboxOpen]);

    const handleThumbnailSelect = useCallback((i: number) => setActiveIndex(i), []);
    const handleThumbnailHover = useCallback((i: number) => setActiveIndex(i), []);
    const openLightbox = useCallback(() => { if (images.length > 0) setLightboxOpen(true); }, [images.length]);
    const closeLightbox = useCallback(() => setLightboxOpen(false), []);
    const lightboxPrev = useCallback(() => setActiveIndex((p) => (p > 0 ? p - 1 : images.length - 1)), [images.length]);
    const lightboxNext = useCallback(() => setActiveIndex((p) => (p < images.length - 1 ? p + 1 : 0)), [images.length]);
    const handleImageLoad = useCallback(() => setImageLoaded(true), []);
    const handleImageError = useCallback(() => { setImageError(true); setImageLoaded(true); }, []);

    const currentImage = images[activeIndex] || images[0];
    const displaySrc = imageError ? FALLBACK_IMAGE : currentImage.src;

    return (
        <>
            <div
                className={`${styles.galleryContainer} ${images.length <= 1 ? styles.singleImageLayout : ''}`}
                role="region"
                aria-label="Product image gallery"
            >
                {/* Thumbnail strip */}
                {images.length > 1 && (
                    <ImageThumbnailStrip
                        images={images}
                        activeIndex={activeIndex}
                        onSelect={handleThumbnailSelect}
                        onHover={handleThumbnailHover}
                    />
                )}

                {/* Main preview area — contains preview + zoom panel side by side */}
                <div className={styles.previewZoomRow}>
                    {/* Main image (overflow:hidden for rounded corners) */}
                    <div
                        ref={mainPreviewRef}
                        className={styles.mainPreviewWrapper}
                        onClick={currentImage.isVideo ? undefined : openLightbox}
                    >
                        {!imageLoaded && !currentImage.isVideo && <div className={styles.skeleton} />}

                        {currentImage.isVideo ? (
                            <video
                                key={currentImage.id}
                                src={currentImage.videoSrc}
                                controls
                                autoPlay
                                loop
                                muted
                                playsInline
                                preload="metadata"
                                className={`${styles.mainImage} ${styles.loaded}`}
                                style={{ objectFit: 'contain', background: '#000' }}
                            >
                                Your browser does not support the video tag.
                            </video>
                        ) : (
                            <img
                                ref={imageRef}
                                key={currentImage.id}
                                src={displaySrc}
                                alt={currentImage.alt}
                                className={`${styles.mainImage} ${imageLoaded ? styles.loaded : styles.loading}`}
                                onLoad={handleImageLoad}
                                onError={handleImageError}
                                draggable={false}
                                loading="eager"
                            />
                        )}

                        {/* Image counter */}
                        {images.length > 1 && (
                            <div className={styles.imageCounter}>
                                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                    <rect x="3" y="3" width="18" height="18" rx="2" />
                                    <circle cx="8.5" cy="8.5" r="1.5" />
                                    <path d="M21 15l-5-5L5 21" />
                                </svg>
                                {activeIndex + 1} / {images.length}
                            </div>
                        )}

                        {/* Expand icon — only for images */}
                        {!currentImage.isVideo && (
                            <div className={styles.expandIcon}>
                                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                    <path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7" />
                                </svg>
                            </div>
                        )}
                    </div>

                    {/* Zoom panel — OUTSIDE overflow:hidden, positioned by CSS */}
                    <div
                        ref={zoomPanelRef}
                        className={styles.zoomPanel}
                        role="img"
                        aria-label={`Zoomed view: ${currentImage.alt}`}
                    />
                </div>

                {/* Headless zoom controller — attaches listeners to imageRef, writes to zoomPanelRef */}
                <ImageZoom
                    src={displaySrc}
                    alt={currentImage.alt}
                    isActive={imageLoaded && !imageError}
                    imageRef={imageRef}
                    panelRef={zoomPanelRef}
                />
            </div>

            {/* Lightbox */}
            {lightboxOpen && (
                <ImageLightbox
                    images={images}
                    activeIndex={activeIndex}
                    onClose={closeLightbox}
                    onPrev={lightboxPrev}
                    onNext={lightboxNext}
                    onSelect={handleThumbnailSelect}
                />
            )}

        </>
    );
}

const ProductImageGallery = memo(ProductImageGalleryInner);
export default ProductImageGallery;

'use client';

import StarRating from './StarRating';
import { ThumbsUp, ThumbsDown, BadgeCheck, Flag, CornerDownRight } from 'lucide-react';
import { voteHelpful, reportReview } from '@/lib/api';
import { useState } from 'react';
import toast from 'react-hot-toast';

export interface Review {
    review_id: string;
    rating: number;
    title?: string;
    body?: string;
    reviewer_name: string;
    is_verified_purchase?: boolean;
    helpful_count?: number;
    admin_reply?: string;
    admin_reply_at?: string;
    created_at: string;
}

interface ReviewCardProps {
    review: Review;
}

export default function ReviewCard({ review }: ReviewCardProps) {
    const [helpfulCount, setHelpfulCount] = useState(review.helpful_count ?? 0);
    const [voteStatus, setVoteStatus] = useState<'none' | 'up' | 'down'>('none');

    // Reporting state
    const [isReporting, setIsReporting] = useState(false);
    const [reportReason, setReportReason] = useState('');
    const [isSubmittingReport, setIsSubmittingReport] = useState(false);
    const [hasReported, setHasReported] = useState(false);

    const handleVote = async (type: 'up' | 'down') => {
        if (voteStatus === type) return; // Prevent double voting the same way

        // Optimistic UI update
        const previousVote = voteStatus;
        const previousCount = helpfulCount;

        setVoteStatus(type);
        if (type === 'up') {
            setHelpfulCount(c => c + (previousVote === 'down' ? 2 : 1));
        } else {
            setHelpfulCount(c => c - (previousVote === 'up' ? 2 : 1));
        }

        try {
            await voteHelpful(review.review_id, type);
        } catch (error) {
            // Revert on error
            toast.error('Failed to register vote. Please log in.');
            setVoteStatus(previousVote);
            setHelpfulCount(previousCount);
        }
    };

    const handleReport = async () => {
        if (!reportReason.trim()) {
            toast.error('Please provide a reason for reporting.');
            return;
        }

        setIsSubmittingReport(true);
        try {
            const res = await reportReview(review.review_id, reportReason);
            if (res && res.success === false) {
                toast.error(res.message || 'Failed to submit report. Ensure you are logged in.');
            } else {
                toast.success('Review reported successfully.');
                setHasReported(true);
                setIsReporting(false);
            }
        } catch (error) {
            toast.error('Network error. Please try again.');
        } finally {
            setIsSubmittingReport(false);
        }
    };

    const dateStr = new Date(review.created_at).toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
    });

    return (
        <div className="border-b border-neutral-100 py-6 last:border-0 group">
            {/* Header */}
            <div className="flex items-start justify-between gap-4">
                <div>
                    <StarRating value={review.rating} size="sm" />
                    {review.title && (
                        <p className="mt-1.5 font-serif text-sm font-semibold text-neutral-800">
                            {review.title}
                        </p>
                    )}
                </div>
            </div>

            {/* Body */}
            {review.body && (
                <p className="mt-2 text-sm text-neutral-600 leading-relaxed">
                    {review.body}
                </p>
            )}

            {/* Admin Reply */}
            {review.admin_reply && (
                <div className="mt-4 ml-4 bg-neutral-50 p-4 rounded-md border-l-2 border-[#C5A46D]">
                    <div className="flex items-center gap-2 mb-1">
                        <CornerDownRight size={14} className="text-[#C5A46D]" />
                        <span className="text-xs font-semibold text-neutral-800">KSP Wines Response</span>
                        {review.admin_reply_at && (
                            <span className="text-xs text-neutral-400 font-medium ml-1">
                                {new Date(review.admin_reply_at).toLocaleDateString('en-US', {
                                    month: 'short', day: 'numeric', year: 'numeric'
                                })}
                            </span>
                        )}
                    </div>
                    <p className="text-sm text-neutral-600 ml-5 leading-relaxed">
                        {review.admin_reply}
                    </p>
                </div>
            )}

            {/* Footer */}
            <div className="mt-4 flex items-center flex-wrap gap-4 text-xs text-neutral-400">
                <span className="font-medium text-neutral-500">{review.reviewer_name}</span>
                <span>{dateStr}</span>

                {review.is_verified_purchase && (
                    <span className="flex items-center gap-1 text-emerald-600 font-medium">
                        <BadgeCheck size={13} />
                        Verified Purchase
                    </span>
                )}

                <div className="ml-auto flex items-center gap-3">
                    {/* Helpful up/down votes */}
                    <div className="flex items-center gap-2 bg-neutral-50 px-2.5 py-1 rounded-full border border-neutral-100">
                        <button
                            onClick={() => handleVote('up')}
                            className={`flex items-center transition-colors hover:text-[#C5A46D] ${voteStatus === 'up' ? 'text-[#C5A46D]' : ''}`}
                            aria-label="Upvote review"
                        >
                            <ThumbsUp size={14} className={voteStatus === 'up' ? 'fill-current' : ''} />
                            <span className="ml-1.5 min-w-[12px] text-center font-medium text-neutral-500">
                                {helpfulCount > 0 ? helpfulCount : 0}
                            </span>
                        </button>
                        <div className="w-[1px] h-3 bg-neutral-200"></div>
                        <button
                            onClick={() => handleVote('down')}
                            className={`flex items-center transition-colors hover:text-red-500 ${voteStatus === 'down' ? 'text-red-500' : ''}`}
                            aria-label="Downvote review"
                        >
                            <ThumbsDown size={14} className={voteStatus === 'down' ? 'fill-current' : ''} />
                        </button>
                    </div>

                    {/* Report button */}
                    <button
                        onClick={() => setIsReporting(!isReporting)}
                        className="flex items-center gap-1 text-neutral-400 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100 focus:opacity-100"
                        title="Report this review"
                        disabled={hasReported}
                    >
                        <Flag size={13} className={hasReported ? "text-red-400" : ""} />
                        <span className="sr-only sm:not-sr-only">{hasReported ? 'Reported' : 'Report'}</span>
                    </button>
                </div>
            </div>

            {/* Report Form */}
            {isReporting && !hasReported && (
                <div className="mt-3 p-3 bg-red-50 border border-red-100 rounded-md text-sm">
                    <p className="font-medium text-red-800 mb-2">Report Review</p>
                    <textarea
                        value={reportReason}
                        onChange={(e) => setReportReason(e.target.value)}
                        placeholder="Why are you reporting this review? (e.g. harmful language, spam)"
                        className="w-full text-sm border-gray-200 rounded p-2 mb-2 resize-none focus:ring-red-500 focus:border-red-500 bg-white"
                        rows={2}
                    />
                    <div className="flex justify-end gap-2">
                        <button
                            onClick={() => setIsReporting(false)}
                            className="px-3 py-1.5 text-xs font-medium text-neutral-600 hover:bg-neutral-100 rounded transition-colors"
                        >
                            Cancel
                        </button>
                        <button
                            onClick={handleReport}
                            disabled={isSubmittingReport || !reportReason.trim()}
                            className="px-3 py-1.5 text-xs font-medium bg-red-600 text-white rounded hover:bg-red-700 disabled:opacity-50 transition-colors"
                        >
                            {isSubmittingReport ? 'Submitting...' : 'Submit Report'}
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { createContext, useContext, useState, useCallback, useEffect, ReactNode, useRef } from 'react';
import { BackendCartItem, BackendCart } from '@/types';
import { useAuth } from '@/context/AuthContext';
import {
    createCart as apiCreateCart,
    getCart as apiGetCart,
    addCartItem as apiAddCartItem,
    updateCartItem as apiUpdateCartItem,
    removeCartItem as apiRemoveCartItem,
    mergeGuestCart as apiMergeGuestCart,
    validateCoupon as apiValidateCoupon,
    getBestAutoApplyCoupon as apiGetBestAutoApplyCoupon,
    saveForLater as apiSaveForLater,
    moveToCartFromSaved as apiMoveToCart,
    getSavedItems as apiGetSavedItems,
} from '@/lib/api';

const GUEST_CART_KEY = 'ksp_guest_cart_id';

interface CartContextType {
    items: BackendCartItem[];
    savedItems: BackendCartItem[];
    cartId: string | null;
    loading: boolean;
    error: string | null;
    addItem: (productId: string, variantId: string | null, quantity?: number) => Promise<void>;
    removeItem: (cartItemId: string) => Promise<void>;
    updateQuantity: (cartItemId: string, quantity: number) => Promise<void>;
    clearCart: (localOnly?: boolean) => Promise<void>;
    saveForLater: (cartItemId: string) => Promise<void>;
    moveToCart: (cartItemId: string) => Promise<void>;
    totalItems: number;
    totalPrice: number;
    couponCode: string | null;
    couponDiscount: number;
    couponType: string | null;
    couponError: string | null;
    applyCoupon: (code: string) => Promise<boolean>;
    removeCoupon: () => void;
}

const CartContext = createContext<CartContextType | undefined>(undefined);

/** Flatten backend cart item → easy-to-consume shape with top-level product_id, product_name, price */
function flattenCartItem(item: BackendCartItem): BackendCartItem {
    return {
        ...item,
        product_id: item.product?.product_id || item.product_id || '',
        product_name: item.product?.product_name || item.product_name || 'Product',
        price: item.pricing?.effective_price ?? item.pricing?.unit_price ?? item.price ?? 0,
        original_price: item.pricing?.unit_price ?? item.price ?? 0,
        size_label: item.variant?.size_label || item.size_label || '',
        image_url: (item.product as any)?.thumbnail_url || item.image_url || '',
    };
}

export function CartProvider({ children }: { children: ReactNode }) {
    const [items, setItems] = useState<BackendCartItem[]>([]);
    const [savedItems, setSavedItems] = useState<BackendCartItem[]>([]);
    const [cartId, setCartId] = useState<string | null>(null);
    const [totalItems, setTotalItems] = useState(0);
    const [totalPrice, setTotalPrice] = useState(0);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [couponCode, setCouponCode] = useState<string | null>(null);
    const [couponDiscount, setCouponDiscount] = useState(0);
    const [couponType, setCouponType] = useState<string | null>(null);
    const [couponError, setCouponError] = useState<string | null>(null);
    const [autoApplyDisabled, setAutoApplyDisabled] = useState(false);
    const { onAuthChange, isAuthenticated, user } = useAuth();
    const initDone = useRef(false);

    const fetchSavedItems = useCallback(async (cId: string) => {
        try {
            const res = await apiGetSavedItems(cId);
            if (res.success && res.data) {
                setSavedItems((res.data || []).map(flattenCartItem));
            }
        } catch (err) {
            console.error('[CartContext] fetchSavedItems error:', err);
        }
    }, []);

    /** Fetch full cart state from backend */
    const fetchCart = useCallback(async (cId: string) => {
        try {
            const res = await apiGetCart({ cart_id: cId });
            if (res.success && res.data) {
                const cart = res.data as BackendCart;
                const flatItems = (cart.items || []).map(flattenCartItem);
                setItems(flatItems);
                setTotalItems(cart.summary?.item_count ?? cart.total_items ?? flatItems.reduce((s: number, i: BackendCartItem) => s + i.quantity, 0));
                setTotalPrice(cart.summary?.grand_total ?? cart.total_amount ?? flatItems.reduce((s: number, i: BackendCartItem) => s + (i.price || 0) * i.quantity, 0));
            }
            await fetchSavedItems(cId);
        } catch (err) {
            console.error('[CartContext] fetchCart error:', err);
        }
    }, [fetchSavedItems]);

    /** Initialize cart for a logged-in customer (optionally merging a guest cart first) */
    const initCart = useCallback(async (customerId: string) => {
        setLoading(true);
        setError(null);
        try {
            // Check if there's a guest cart to merge
            const guestCartId = typeof window !== 'undefined' ? localStorage.getItem(GUEST_CART_KEY) : null;
            if (guestCartId) {
                try {
                    await apiMergeGuestCart(guestCartId, customerId);
                } catch (mergeErr) {
                    console.warn('[CartContext] Guest cart merge failed (cart may have expired):', mergeErr);
                }
                localStorage.removeItem(GUEST_CART_KEY);
            }

            const getRes = await apiGetCart({ customer_id: customerId });
            if (getRes.success && getRes.data) {
                const cart = getRes.data as BackendCart;
                setCartId(cart.cart_id);
                const flatItems = (cart.items || []).map(flattenCartItem);
                setItems(flatItems);
                setTotalItems(cart.summary?.item_count ?? cart.total_items ?? flatItems.reduce((s: number, i: BackendCartItem) => s + i.quantity, 0));
                setTotalPrice(cart.summary?.grand_total ?? cart.total_amount ?? flatItems.reduce((s: number, i: BackendCartItem) => s + (i.price || 0) * i.quantity, 0));
                await fetchSavedItems(cart.cart_id);
            } else {
                const createRes = await apiCreateCart(customerId);
                if (createRes.success && createRes.data) {
                    setCartId(createRes.data.cart_id);
                    setItems([]);
                    setSavedItems([]);
                    setTotalItems(0);
                    setTotalPrice(0);
                }
            }
        } catch (err) {
            console.error('[CartContext] initCart error:', err);
            setError('Failed to load cart');
        } finally {
            setLoading(false);
        }
    }, []);

    /** Restore a guest cart from localStorage (if user is NOT authenticated) */
    const restoreGuestCart = useCallback(async () => {
        if (typeof window === 'undefined') return;
        const savedCartId = localStorage.getItem(GUEST_CART_KEY);
        if (!savedCartId) return;

        setLoading(true);
        try {
            const res = await apiGetCart({ cart_id: savedCartId });
            if (res.success && res.data) {
                const cart = res.data as BackendCart;
                setCartId(cart.cart_id);
                const flatItems = (cart.items || []).map(flattenCartItem);
                setItems(flatItems);
                setTotalItems(cart.summary?.item_count ?? cart.total_items ?? flatItems.reduce((s: number, i: BackendCartItem) => s + i.quantity, 0));
                setTotalPrice(cart.summary?.grand_total ?? cart.total_amount ?? flatItems.reduce((s: number, i: BackendCartItem) => s + (i.price || 0) * i.quantity, 0));
                await fetchSavedItems(cart.cart_id);
            } else {
                // Guest cart expired or deleted — clean up
                localStorage.removeItem(GUEST_CART_KEY);
            }
        } catch (err) {
            console.error('[CartContext] restoreGuestCart error:', err);
            localStorage.removeItem(GUEST_CART_KEY);
        } finally {
            setLoading(false);
        }
    }, []);

    /** Create a guest cart on-the-fly (called when a guest clicks "Add to Cart") */
    const ensureGuestCart = useCallback(async (): Promise<string | null> => {
        try {
            const createRes = await apiCreateCart(); // no customer_id → guest cart
            if (createRes.success && createRes.data) {
                const newCartId = createRes.data.cart_id;
                setCartId(newCartId);
                localStorage.setItem(GUEST_CART_KEY, newCartId);
                return newCartId;
            }
        } catch (err) {
            console.error('[CartContext] ensureGuestCart error:', err);
        }
        return null;
    }, []);

    const resetCart = useCallback(() => {
        setCartId(null);
        setItems([]);
        setSavedItems([]);
        setTotalItems(0);
        setTotalPrice(0);
        setError(null);
        setCouponCode(null);
        setCouponDiscount(0);
        setCouponType(null);
        setCouponError(null);
        setAutoApplyDisabled(false);
        if (typeof window !== 'undefined') {
            localStorage.removeItem(GUEST_CART_KEY);
        }
    }, []);

    const applyCoupon = useCallback(async (code: string): Promise<boolean> => {
        setCouponError(null);
        try {
            // The items here are captured correctly because they are in the dependency array (below).
            const res = await apiValidateCoupon(code, totalPrice);
            if (res.success) {
                setCouponCode(res.data.coupon.code);
                setCouponType(res.data.coupon.discount_type || null);

                if (res.data.coupon.discount_type === 'bogo') {
                    const buyQty = res.data.coupon.bogo_buy_qty || 1;
                    const getQty = res.data.coupon.bogo_get_qty || 1;

                    const flatPrices: number[] = [];
                    items.forEach(it => {
                        for (let i = 0; i < it.quantity; i++) {
                            // Effective price
                            flatPrices.push(it.price || 0);
                        }
                    });

                    flatPrices.sort((a, b) => a - b);
                    const bogoGroups = Math.floor(flatPrices.length / (buyQty + getQty));
                    const freeItemsCount = bogoGroups * getQty;

                    let bogoDiscount = 0;
                    for (let i = 0; i < freeItemsCount; i++) {
                        bogoDiscount += flatPrices[i];
                    }

                    if (res.data.coupon.max_discount_cap !== null) {
                        bogoDiscount = Math.min(bogoDiscount, parseFloat(res.data.coupon.max_discount_cap));
                    }
                    setCouponDiscount(bogoDiscount);
                } else {
                    setCouponDiscount(res.data.discount);
                }

                return true;
            } else {
                setCouponError(res.message || 'Invalid coupon');
                setCouponCode(null);
                setCouponDiscount(0);
                setCouponType(null);
                return false;
            }
        } catch {
            setCouponError('Failed to validate coupon');
            return false;
        }
    }, [totalPrice, items]);

    const removeCoupon = useCallback(() => {
        setCouponCode(null);
        setCouponDiscount(0);
        setCouponType(null);
        setCouponError(null);
        setAutoApplyDisabled(true); // Don't forcibly auto-apply again if user actively removed it
    }, []);

    // Subscribe to auth changes
    useEffect(() => {
        const unsub = onAuthChange((event, user) => {
            if (event === 'login' && user) {
                initCart(user.id);
            } else if (event === 'logout') {
                resetCart();
            }
        });
        return unsub;
    }, [onAuthChange, initCart, resetCart]);

    // On mount: if not authenticated, try to restore guest cart
    useEffect(() => {
        if (initDone.current) return;
        initDone.current = true;

        // If user is already authenticated, initCart is handled by onAuthChange listener
        // If not authenticated, try to restore a guest cart from localStorage
        if (!isAuthenticated) {
            restoreGuestCart();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    // Auto-apply effect
    useEffect(() => {
        if (couponCode || totalPrice <= 0 || autoApplyDisabled) return;

        let active = true;
        apiGetBestAutoApplyCoupon(totalPrice)
            .then(res => {
                if (active && res.success && res.data?.coupon?.code) {
                    // Temporarily skip setCouponError on this automatic background attempt
                    applyCoupon(res.data.coupon.code).catch(() => { });
                }
            })
            .catch(() => { });

        return () => { active = false; };
    }, [totalPrice, couponCode, autoApplyDisabled, applyCoupon]);

    const addItem = useCallback(async (productId: string, variantId: string | null, quantity = 1) => {
        let activeCartId = cartId;

        // If no cart exists, create one (guest cart if not authenticated)
        if (!activeCartId) {
            if (isAuthenticated && user) {
                // Shouldn't normally happen, but just in case
                const createRes = await apiCreateCart(user.id);
                if (createRes.success && createRes.data) {
                    activeCartId = createRes.data.cart_id;
                    setCartId(activeCartId);
                }
            } else {
                activeCartId = await ensureGuestCart();
            }
        }

        if (!activeCartId) {
            setError('Failed to create cart. Please try again.');
            return;
        }

        setLoading(true);
        setError(null);
        try {
            if (variantId) {
                await apiAddCartItem(activeCartId, variantId, quantity, true);
            } else {
                await apiAddCartItem(activeCartId, productId, quantity, false);
            }
            await fetchCart(activeCartId);
        } catch (err) {
            console.error('[CartContext] addItem error:', err);
            setError('Failed to add item to cart');
        } finally {
            setLoading(false);
        }
    }, [cartId, fetchCart, isAuthenticated, user, ensureGuestCart]);

    const updateQuantity = useCallback(async (cartItemId: string, quantity: number) => {
        if (quantity <= 0) {
            await apiRemoveCartItem(cartItemId);
            if (cartId) await fetchCart(cartId);
            return;
        }
        setLoading(true);
        setError(null);
        try {
            await apiUpdateCartItem(cartItemId, quantity);
            if (cartId) await fetchCart(cartId);
        } catch (err) {
            console.error('[CartContext] updateQuantity error:', err);
            setError('Failed to update quantity');
        } finally {
            setLoading(false);
        }
    }, [cartId, fetchCart]);

    const removeItem = useCallback(async (cartItemId: string) => {
        setLoading(true);
        setError(null);
        try {
            await apiRemoveCartItem(cartItemId);
            if (cartId) await fetchCart(cartId);
        } catch (err) {
            console.error('[CartContext] removeItem error:', err);
            setError('Failed to remove item');
        } finally {
            setLoading(false);
        }
    }, [cartId, fetchCart]);

    const saveForLater = useCallback(async (cartItemId: string) => {
        setLoading(true);
        setError(null);
        try {
            await apiSaveForLater(cartItemId);
            if (cartId) await fetchCart(cartId);
        } catch (err) {
            console.error('[CartContext] saveForLater error:', err);
            setError('Failed to save item for later');
        } finally {
            setLoading(false);
        }
    }, [cartId, fetchCart]);

    const moveToCart = useCallback(async (cartItemId: string) => {
        setLoading(true);
        setError(null);
        try {
            await apiMoveToCart(cartItemId);
            if (cartId) await fetchCart(cartId);
        } catch (err) {
            console.error('[CartContext] moveToCart error:', err);
            setError('Failed to move item to cart');
        } finally {
            setLoading(false);
        }
    }, [cartId, fetchCart]);

    const clearCart = useCallback(async (localOnly = false) => {
        if (!cartId) return;
        setLoading(true);
        try {
            if (!localOnly) {
                for (const item of items) {
                    await apiRemoveCartItem(item.cart_item_id);
                }
            }
            setItems([]);
            setTotalItems(0);
            setTotalPrice(0);
        } catch (err) {
            console.error('[CartContext] clearCart error:', err);
        } finally {
            setLoading(false);
        }
    }, [cartId, items]);

    return (
        <CartContext.Provider value={{
            items, savedItems, cartId, loading, error,
            addItem, removeItem, updateQuantity, clearCart, saveForLater, moveToCart,
            totalItems, totalPrice,
            couponCode, couponDiscount, couponType, couponError,
            applyCoupon, removeCoupon,
        }}>
            {children}
        </CartContext.Provider>
    );
}

export function useCart() {
    const context = useContext(CartContext);
    if (!context) throw new Error('useCart must be used within CartProvider');
    return context;
}

