'use client';

import { useSearchParams, useRouter, usePathname } from 'next/navigation';
import { useCallback, useMemo } from 'react';
import { FILTER_CONFIGS } from '@/lib/filterConfig';

export interface FilterState {
    search: string;
    category: string;
    sub_category: string;
    brands: string[];
    country: string;
    ratings: string[];
    priceRange: [number, number];
    alcoholRange: [number, number];
    inStock: boolean;
    bestSellers: boolean;
    newArrivals: boolean;
    sort: string;
}

const DEFAULTS: FilterState = {
    search: '',
    category: '',
    sub_category: '',
    brands: [],
    country: '',
    ratings: [],
    priceRange: [0, Infinity],
    alcoholRange: [0, 100],
    inStock: false,
    bestSellers: false,
    newArrivals: false,
    sort: '',
};

function parseArray(val: string | null): string[] {
    if (!val) return [];
    return val.split(',').filter(Boolean);
}

function parseRange(val: string | null, fallback: [number, number]): [number, number] {
    if (!val) return fallback;
    const parts = val.split('-').map(Number);
    if (parts.length === 2 && !isNaN(parts[0]) && !isNaN(parts[1])) {
        return [parts[0], parts[1]];
    }
    return fallback;
}

export function useFilters() {
    const searchParams = useSearchParams();
    const router = useRouter();
    const pathname = usePathname();

    // Read current state from URL
    const filters: FilterState = useMemo(() => ({
        search: searchParams.get('search') || DEFAULTS.search,
        category: searchParams.get('category') || DEFAULTS.category,
        sub_category: searchParams.get('sub_category') || DEFAULTS.sub_category,
        brands: parseArray(searchParams.get('brand')),
        country: searchParams.get('country') || DEFAULTS.country,
        ratings: parseArray(searchParams.get('rating')),
        priceRange: parseRange(searchParams.get('price'), DEFAULTS.priceRange),
        alcoholRange: parseRange(searchParams.get('alcohol'), DEFAULTS.alcoholRange),
        inStock: searchParams.get('inStock') === 'true',
        bestSellers: searchParams.get('bestSellers') === 'true',
        newArrivals: searchParams.get('newArrivals') === 'true',
        sort: searchParams.get('sort') || DEFAULTS.sort,
    }), [searchParams]);

    // Push updates to URL (shallow — no full reload)
    const setParam = useCallback((updates: Record<string, string | null>) => {
        const params = new URLSearchParams(searchParams.toString());
        Object.entries(updates).forEach(([key, value]) => {
            if (value === null || value === '' || value === 'false') {
                params.delete(key);
            } else {
                params.set(key, value);
            }
        });
        // Reset page on filter  change
        params.delete('page');
        const qs = params.toString();
        router.replace(`${pathname}${qs ? '?' + qs : ''}`, { scroll: false });
    }, [searchParams, router, pathname]);

    // Setter  helpers
    const setSearch = useCallback((val: string) => setParam({ search: val || null }), [setParam]);
    const setCategory = useCallback((val: string) => setParam({ category: val || null }), [setParam]);
    const setSubCategory = useCallback((val: string) => setParam({ sub_category: val || null }), [setParam]);
    const setBrands = useCallback((val: string[]) => setParam({ brand: val.length ? val.join(',') : null }), [setParam]);
    const setCountry = useCallback((val: string) => setParam({ country: val || null }), [setParam]);
    const setRatings = useCallback((val: string[]) => setParam({ rating: val.length ? val.join(',') : null }), [setParam]);
    const setPriceRange = useCallback((val: [number, number], maxPriceInStore?: number) => {
        const pMax = maxPriceInStore ?? Infinity;
        const isDefault = val[0] === 0 && (val[1] === pMax || val[1] === Infinity);
        setParam({ price: isDefault ? null : `${val[0]}-${val[1]}` });
    }, [setParam]);
    const setAlcoholRange = useCallback((val: [number, number]) => {
        const alcConfig = FILTER_CONFIGS.find(f => f.key === 'alcohol');
        const isDefault = val[0] === (alcConfig?.min ?? 0) && val[1] === (alcConfig?.max ?? 60);
        setParam({ alcohol: isDefault ? null : `${val[0]}-${val[1]}` });
    }, [setParam]);
    const setInStock = useCallback((val: boolean) => setParam({ inStock: val ? 'true' : null }), [setParam]);
    const setBestSellers = useCallback((val: boolean) => setParam({ bestSellers: val ? 'true' : null }), [setParam]);
    const setNewArrivals = useCallback((val: boolean) => setParam({ newArrivals: val ? 'true' : null }), [setParam]);
    const setSort = useCallback((val: string) => setParam({ sort: val || null }), [setParam]);

    const clearAll = useCallback(() => {
        router.replace(pathname, { scroll: false });
    }, [router, pathname]);

    // Remove a single chip
    const removeFilter = useCallback((key: string, value: string) => {
        switch (key) {
            case 'brand': setBrands(filters.brands.filter(b => b !== value)); break;
            case 'country': setCountry(''); break;
            case 'rating': setRatings(filters.ratings.filter(r => r !== value)); break;
            case 'category': setParam({ category: null, sub_category: null }); break;
            case 'sub_category': setSubCategory(''); break;
            case 'search': setSearch(''); break;
            case 'price': setPriceRange(DEFAULTS.priceRange); break;
            case 'alcohol': setAlcoholRange(DEFAULTS.alcoholRange); break;
            case 'inStock': setInStock(false); break;
            case 'bestSellers': setBestSellers(false); break;
            case 'newArrivals': setNewArrivals(false); break;
            case 'sort': setSort(''); break;
        }
    }, [filters, setBrands, setCountry, setRatings, setCategory, setSubCategory, setSearch, setPriceRange, setAlcoholRange, setInStock, setBestSellers, setNewArrivals, setSort]);

    // Build chips from active filters
    const activeChips = useMemo(() => {
        const chips: { key: string; label: string; value: string }[] = [];
        if (filters.search) chips.push({ key: 'search', label: 'Search', value: filters.search });
        if (filters.category) chips.push({ key: 'category', label: 'Category', value: filters.category });
        if (filters.sub_category) chips.push({ key: 'sub_category', label: 'Subcategory', value: filters.sub_category });
        filters.brands.forEach(b => chips.push({ key: 'brand', label: 'Brand', value: b }));
        if (filters.country) chips.push({ key: 'country', label: 'Country', value: filters.country });
        filters.ratings.forEach(r => chips.push({ key: 'rating', label: 'Rating', value: r }));
        const pMax = filters.priceRange[1] === Infinity ? 'Max' : `$${filters.priceRange[1]}`;
        if (filters.priceRange[0] !== 0 || filters.priceRange[1] !== Infinity) {
            chips.push({ key: 'price', label: 'Price', value: `$${filters.priceRange[0]} – ${pMax}` });
        }
        const alcConfig = FILTER_CONFIGS.find(f => f.key === 'alcohol');
        if (filters.alcoholRange[0] !== (alcConfig?.min ?? 0) || filters.alcoholRange[1] !== (alcConfig?.max ?? 100)) {
            chips.push({ key: 'alcohol', label: 'Alcohol', value: `${filters.alcoholRange[0]}% – ${filters.alcoholRange[1]}%` });
        }
        if (filters.inStock) chips.push({ key: 'inStock', label: 'Status', value: 'In Stock' });
        if (filters.bestSellers) chips.push({ key: 'bestSellers', label: 'Collection', value: 'Best Sellers' });
        if (filters.newArrivals) chips.push({ key: 'newArrivals', label: 'Collection', value: 'New Arrivals' });
        return chips;
    }, [filters]);

    return {
        filters,
        activeChips,
        setSearch,
        setCategory,
        setSubCategory,
        setBrands,
        setCountry,
        setRatings,
        setPriceRange,
        setAlcoholRange,
        setInStock,
        setBestSellers,
        setNewArrivals,
        setSort,
        removeFilter,
        clearAll,
    };
}

/**
 * Storefront  API Client
 * Consumes existing backend at https://ecommerce-backend-h23p.onrender.com
 * Backend response format: { success: boolean, message: string, data: T }
 */

import { Product, FilteredProduct, FilterMeta, ProductWithDetails, ProductAsset, ApiResponse } from '@/types';

const API_URL = process.env.NEXT_PUBLIC_API_URL || 'http://127.0.0.1:5000';
const TOKEN_KEY = 'ksp_wines_token';

/** Read the JWT stored by AuthContext after login/register */
function getStorefrontToken(): string | null {
    if (typeof window === 'undefined') return null;
    try { return localStorage.getItem(TOKEN_KEY); } catch { return null; }
}

/** fetch() wrapper that adds Authorization header + credentials: 'include' */
export function authFetch(url: string, init?: RequestInit): Promise<Response> {
    const token = getStorefrontToken();
    const headers: Record<string, string> = {};
    if (token) headers['Authorization'] = `Bearer ${token}`;
    // Merge with any existing headers
    const existingHeaders = init?.headers as Record<string, string> | undefined;
    if (existingHeaders) Object.assign(headers, existingHeaders);
    return fetch(url, { ...init, headers, credentials: 'include' });
}

/* ─── Products ─── */

export async function getProducts(params?: {
    limit?: number;
    offset?: number;
    category?: string;
    brand?: string;
    sort?: string;
    status?: string;
}): Promise<Product[]> {
    try {
        const searchParams = new URLSearchParams();
        if (params?.limit) searchParams.set('limit', String(params.limit));
        if (params?.offset) searchParams.set('offset', String(params.offset));
        if (params?.category) searchParams.set('category', params.category);
        if (params?.brand) searchParams.set('brand', params.brand);
        if (params?.sort) searchParams.set('sort', params.sort);
        if (params?.status) searchParams.set('status', params.status);

        const url = `${API_URL}/api/products${searchParams.toString() ? '?' + searchParams.toString() : ''}`;
        const res = await fetch(url);
        if (!res.ok) return [];
        const json: ApiResponse<any> = await res.json();
        // Backend may return data as { products: [...], meta } or as a direct array
        let products: any[] = [];
        if (Array.isArray(json.data)) products = json.data;
        else if (Array.isArray(json.data.products)) products = json.data.products;

        return products.map(p => ({
            ...p,
            images: p.thumbnail_url ? [p.thumbnail_url] : []
        }));
    } catch (error) {
        console.warn('[API] Failed to fetch products. Backend might be unreachable.');
        return [];
    }
}

export async function getRelatedProducts(productId: string, type: string = 'similar', limit: number = 4): Promise<Product[]> {
    try {
        const url = `${API_URL}/api/products/${productId}/related?type=${type}&limit=${limit}`;
        const res = await fetch(url);
        if (!res.ok) return [];
        const json: ApiResponse<any> = await res.json();

        let products: any[] = [];
        if (json.success && Array.isArray(json.data)) {
            products = json.data;
        }

        return products.map(p => ({
            ...p,
            images: p.thumbnail_url ? [p.thumbnail_url] : []
        }));
    } catch (error) {
        console.warn(`[API] Failed to fetch related products for ${productId}`);
        return [];
    }
}

/* ─── Featured Products ─── */

export async function getFeaturedProducts(): Promise<Product[]> {
    try {
        const res = await fetch(`${API_URL}/api/products/featured`, { cache: 'no-store' });
        if (!res.ok) return [];
        const json: ApiResponse<any> = await res.json();
        console.log('[getFeaturedProducts] response:', json);
        if (json.success && Array.isArray(json.data)) {
            const mapped = json.data.map((p: any) => ({
                ...p,
                images: p.thumbnail_url ? [p.thumbnail_url] : [],
                is_featured: true,
            }));
            return mapped;
        }
        return [];
    } catch (error) {
        console.warn('[API] Failed to fetch featured products.');
        return [];
    }
}

/* ─── Filtered Products (backend-powered) ─── */

export interface FilterParams {
    page?: number;
    limit?: number;
    sort?: string;
    min_price?: number;
    max_price?: number;
    min_abv?: number;
    max_abv?: number;
    country?: string;      // comma-separated
    min_rating?: number;
    availability?: string;  // 'in_stock' | 'out_of_stock' | 'all'
    category?: string;
    brand?: string;
}

export async function getFilteredProducts(
    params: FilterParams = {}
): Promise<{ data: FilteredProduct[]; meta: FilterMeta }> {
    try {
        const sp = new URLSearchParams();
        if (params.page) sp.set('page', String(params.page));
        if (params.limit) sp.set('limit', String(params.limit));
        if (params.sort) sp.set('sort', params.sort);
        if (params.min_price != null) sp.set('min_price', String(params.min_price));
        if (params.max_price != null) sp.set('max_price', String(params.max_price));
        if (params.min_abv != null) sp.set('min_abv', String(params.min_abv));
        if (params.max_abv != null) sp.set('max_abv', String(params.max_abv));
        if (params.country) sp.set('country', params.country);
        if (params.min_rating != null) sp.set('min_rating', String(params.min_rating));
        if (params.availability) sp.set('availability', params.availability);
        if (params.category) sp.set('category', params.category);
        if (params.brand) sp.set('brand', params.brand);

        const qs = sp.toString();
        const url = `${API_URL}/api/products/filter${qs ? '?' + qs : ''}`;
        const res = await fetch(url);
        const json = await res.json();

        if (json.success) {
            const data = json.data ?? [];
            return {
                data: data.map((p: any) => ({
                    ...p,
                    images: p.thumbnail_url ? [p.thumbnail_url] : []
                })),
                meta: json.meta ?? { total_count: 0, page: 1, limit: 20, total_pages: 0, has_next_page: false, has_prev_page: false, filters_applied: {}, sort: 'newest', cache_hit: false },
            };
        }
        return { data: [], meta: { total_count: 0, page: 1, limit: 20, total_pages: 0, has_next_page: false, has_prev_page: false, filters_applied: {}, sort: 'newest', cache_hit: false } };
    } catch (error) {
        console.error('[API] Failed to fetch filtered products:', error);
        return { data: [], meta: { total_count: 0, page: 1, limit: 20, total_pages: 0, has_next_page: false, has_prev_page: false, filters_applied: {}, sort: 'newest', cache_hit: false } };
    }
}

/* ─── Best Sellers (public endpoint) ─── */

export async function getBestSellers(params?: {
    period?: string;
    limit?: number;
    page?: number;
    category?: string;
    country?: string;
    minPrice?: number;
    maxPrice?: number;
}): Promise<{ data: FilteredProduct[]; meta: FilterMeta }> {
    try {
        const sp = new URLSearchParams();
        if (params?.period) sp.set('period', params.period);
        if (params?.limit) sp.set('limit', String(params.limit));
        if (params?.page) sp.set('page', String(params.page));
        if (params?.category) sp.set('category', params.category);
        if (params?.country) sp.set('country', params.country);
        if (params?.minPrice != null) sp.set('minPrice', String(params.minPrice));
        if (params?.maxPrice != null) sp.set('maxPrice', String(params.maxPrice));

        const qs = sp.toString();
        const url = `${API_URL}/api/products/best-sellers${qs ? '?' + qs : ''}`;
        const res = await fetch(url);
        const json = await res.json();

        if (json.success && json.data) {
            const products = json.data.products ?? json.data ?? [];
            const pagination = json.data.pagination ?? {};
            return {
                data: products.map((p: any) => ({
                    ...p,
                    images: p.thumbnail_url ? [p.thumbnail_url] : [],
                })),
                meta: {
                    total_count: pagination.total ?? products.length,
                    page: pagination.page ?? 1,
                    limit: pagination.limit ?? params?.limit ?? 12,
                    total_pages: pagination.totalPages ?? 1,
                    has_next_page: (pagination.page ?? 1) < (pagination.totalPages ?? 1),
                    has_prev_page: (pagination.page ?? 1) > 1,
                    filters_applied: {},
                    sort: 'best_sellers',
                    cache_hit: false,
                },
            };
        }
